definitions.validar_soma_pesos():
CREATE OR REPLACE FUNCTION public.validar_soma_pesos()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if (select sum(peso_percentual) from fases where obra_id = new.obra_id) > 100.5 then
    raise exception 'Soma dos pesos das fases da obra % excede 100%%', new.obra_id;
  end if;
  return new;
end;
$function$

definitions.fn_cancelar_rnc(uuid):
CREATE OR REPLACE FUNCTION public.fn_cancelar_rnc(p_rnc_id uuid)
 RETURNS rnc
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_row public.rnc;
begin
  select * into v_row from public.rnc where id=p_rnc_id for update;
  if not found then raise exception 'RNC não encontrada.'; end if;
  if not public.fn_pode_editar_obra(v_row.obra_id) then raise exception 'Sem permissão.' using errcode='42501'; end if;
  update public.rnc set estado='cancelado' where id=p_rnc_id returning * into v_row; return v_row;
end; $function$

definitions.fn_mapa_gestao_obras():
CREATE OR REPLACE FUNCTION public.fn_mapa_gestao_obras()
 RETURNS TABLE(origem_id uuid, obra_id uuid, obra_numero text, obra_nome text, categoria text, data_lancamento date, entidade_nome text, descricao text, documento text, valor numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_atual public.utilizadores;
  v_linha record;
  v_json jsonb;
  v_obra public.obras;
  v_sub public.subempreitadas;
  v_uuid uuid;
  v_nome text;
  v_data_text text;
  v_estado text;
begin
  if not public.fn_pode_ver_mapa_gestao_obras() then
      raise exception 'Sem acesso ao Mapa de Gestão de Obras.' using errcode = '42501';
    end if;

  select * into v_atual
  from public.utilizadores u
  where u.id = public.fn_utilizador_atual_id()
    and coalesce(u.ativo, true);

  if not found then
    raise exception 'Utilizador autenticado sem perfil ativo.';
  end if;

  -- Materiais: usa lancamentos_materiais quando a tabela existe.
  if to_regclass('public.lancamentos_materiais') is not null then
    for v_linha in execute 'select to_jsonb(t) as dados from public.lancamentos_materiais t'
    loop
      v_json := v_linha.dados;
      v_estado := lower(coalesce(v_json ->> 'estado_pagamento', ''));
      if v_json ? 'estado_pagamento' and v_estado not in ('pago', 'paga') then continue; end if;
      if v_json ? 'pago' and lower(coalesce(v_json ->> 'pago', 'false')) not in ('true', 't', '1') then continue; end if;
      if v_json ? 'data_pagamento' and nullif(v_json ->> 'data_pagamento', '') is null then continue; end if;

      begin v_uuid := nullif(v_json ->> 'obra_id', '')::uuid; exception when others then continue; end;
      select * into v_obra from public.obras o where o.id = v_uuid and o.empresa_id = v_atual.empresa_id;
      if not found then continue; end if;

      v_nome := null;
      begin
        v_uuid := nullif(v_json ->> 'fornecedor_id', '')::uuid;
        select f.nome into v_nome from public.fornecedores f where f.id = v_uuid;
      exception when others then v_nome := null; end;
      v_data_text := coalesce(nullif(v_json ->> 'data_pagamento',''), nullif(v_json ->> 'data',''), nullif(v_json ->> 'data_fatura',''), nullif(v_json ->> 'criado_em',''));

      origem_id := (v_json ->> 'id')::uuid; obra_id := v_obra.id; obra_numero := v_obra.numero::text; obra_nome := v_obra.nome;
      categoria := 'materiais'; data_lancamento := left(v_data_text, 10)::date; entidade_nome := coalesce(v_nome, v_json ->> 'fornecedor', 'Fornecedor não identificado');
      descricao := coalesce(v_json ->> 'designacao', v_json ->> 'descricao', 'Material'); documento := coalesce(v_json ->> 'numero_doc', v_json ->> 'documento');
      valor := coalesce(nullif(v_json ->> 'valor_total','')::numeric, nullif(v_json ->> 'valor','')::numeric, nullif(v_json ->> 'total','')::numeric, 0); return next;
    end loop;
  else
    -- Compatibilidade com o fluxo atual, que regista materiais em faturas.
    for v_linha in
      select f.*, o.numero as numero_obra, o.nome as nome_obra, fr.nome as nome_fornecedor
      from public.faturas f
      join public.obras o on o.id = f.obra_id
      left join public.fornecedores fr on fr.id = f.fornecedor_id
      where o.empresa_id = v_atual.empresa_id
        and f.tipo_origem = 'material'
        and f.estado_pagamento = 'pago'
    loop
      origem_id := v_linha.id; obra_id := v_linha.obra_id; obra_numero := v_linha.numero_obra::text; obra_nome := v_linha.nome_obra;
      categoria := 'materiais'; data_lancamento := v_linha.data_pagamento; entidade_nome := coalesce(v_linha.nome_fornecedor, 'Fornecedor não identificado');
      descricao := 'Fatura de material'; documento := v_linha.numero_doc; valor := coalesce(v_linha.valor, 0); return next;
    end loop;
  end if;

  -- Despesas de estaleiro.
  for v_linha in execute 'select to_jsonb(t) as dados from public.despesas_estaleiro t'
  loop
    v_json := v_linha.dados; v_estado := lower(coalesce(v_json ->> 'estado_pagamento', ''));
    if v_json ? 'estado_pagamento' and v_estado not in ('pago', 'paga') then continue; end if;
    if nullif(v_json ->> 'estado_aprovacao','') is not null and lower(v_json ->> 'estado_aprovacao') not in ('aprovado','aprovada') then continue; end if;
    begin v_uuid := nullif(v_json ->> 'obra_id', '')::uuid; exception when others then continue; end;
    select * into v_obra from public.obras o where o.id = v_uuid and o.empresa_id = v_atual.empresa_id; if not found then continue; end if;
    v_nome := null;
    begin v_uuid := nullif(v_json ->> 'fornecedor_id', '')::uuid; select f.nome into v_nome from public.fornecedores f where f.id = v_uuid; exception when others then v_nome := null; end;
    if v_nome is null then
      begin v_uuid := nullif(v_json ->> 'colaborador_id', '')::uuid; select c.nome into v_nome from public.colaboradores c where c.id = v_uuid; exception when others then v_nome := null; end;
    end if;
    v_data_text := coalesce(nullif(v_json ->> 'data_pagamento',''), nullif(v_json ->> 'data',''), nullif(v_json ->> 'criado_em',''));
    origem_id := (v_json ->> 'id')::uuid; obra_id := v_obra.id; obra_numero := v_obra.numero::text; obra_nome := v_obra.nome; categoria := 'estaleiro';
    data_lancamento := left(v_data_text,10)::date; entidade_nome := coalesce(v_nome, v_json ->> 'fornecedor', 'Estaleiro');
    descricao := coalesce(v_json ->> 'designacao', v_json ->> 'descricao', 'Despesa de estaleiro'); documento := coalesce(v_json ->> 'numero_doc', v_json ->> 'documento');
    valor := coalesce(nullif(v_json ->> 'valor_total','')::numeric, nullif(v_json ->> 'valor','')::numeric, 0); return next;
  end loop;

  -- Pessoal em obra / mão de obra: cada lançamento é custo realizado.
  for v_linha in execute 'select to_jsonb(t) as dados from public.lancamentos_mao_obra t'
  loop
    v_json := v_linha.dados; v_estado := lower(coalesce(v_json ->> 'estado_pagamento', ''));
    if v_json ? 'estado_pagamento' and v_estado not in ('pago', 'paga') then continue; end if;
    begin v_uuid := nullif(v_json ->> 'obra_id', '')::uuid; exception when others then continue; end;
    select * into v_obra from public.obras o where o.id = v_uuid and o.empresa_id = v_atual.empresa_id; if not found then continue; end if;
    v_nome := null;
    begin v_uuid := nullif(v_json ->> 'colaborador_id', '')::uuid; select c.nome into v_nome from public.colaboradores c where c.id = v_uuid; exception when others then v_nome := null; end;
    v_data_text := coalesce(nullif(v_json ->> 'data_pagamento',''), nullif(v_json ->> 'data',''), nullif(v_json ->> 'criado_em',''));
    origem_id := (v_json ->> 'id')::uuid; obra_id := v_obra.id; obra_numero := v_obra.numero::text; obra_nome := v_obra.nome; categoria := 'mao_obra';
    data_lancamento := left(v_data_text,10)::date; entidade_nome := coalesce(v_nome, 'Colaborador não identificado');
    descricao := concat_ws(' · ', nullif(v_json ->> 'horas','') || case when nullif(v_json ->> 'horas','') is not null then ' h' end, case when nullif(v_json ->> 'valor_hora','') is not null then nullif(v_json ->> 'valor_hora','') || ' €/h' end, nullif(v_json ->> 'percentual_afetacao','') || case when nullif(v_json ->> 'percentual_afetacao','') is not null then ' afetação' end);
    documento := null; valor := coalesce(nullif(v_json ->> 'valor_total','')::numeric, (nullif(v_json ->> 'horas','')::numeric * nullif(v_json ->> 'valor_hora','')::numeric), 0); return next;
  end loop;

  -- Pagamentos de subempreitadas.
  for v_linha in execute 'select to_jsonb(t) as dados from public.pagamentos_subempreitada t'
  loop
    v_json := v_linha.dados; v_estado := lower(coalesce(v_json ->> 'estado_pagamento', ''));
    if v_json ? 'estado_pagamento' and v_estado not in ('pago', 'paga') then continue; end if;
    if nullif(v_json ->> 'estado_aprovacao','') is not null and lower(v_json ->> 'estado_aprovacao') not in ('aprovado','aprovada') then continue; end if;
    begin v_uuid := nullif(v_json ->> 'subempreitada_id', '')::uuid; exception when others then continue; end;
    select * into v_sub from public.subempreitadas s where s.id = v_uuid; if not found then continue; end if;
    select * into v_obra from public.obras o where o.id = v_sub.obra_id and o.empresa_id = v_atual.empresa_id; if not found then continue; end if;
    v_nome := null; select f.nome into v_nome from public.fornecedores f where f.id = v_sub.fornecedor_id;
    v_data_text := coalesce(nullif(v_json ->> 'data_pagamento',''), nullif(v_json ->> 'data',''), nullif(v_json ->> 'criado_em',''));
    origem_id := (v_json ->> 'id')::uuid; obra_id := v_obra.id; obra_numero := v_obra.numero::text; obra_nome := v_obra.nome; categoria := 'subempreitadas';
    data_lancamento := left(v_data_text,10)::date; entidade_nome := coalesce(v_nome, 'Subempreiteiro não identificado');
    descricao := coalesce(v_sub.especialidade, v_json ->> 'descricao', 'Pagamento de subempreitada'); documento := coalesce(v_json ->> 'numero_doc', v_json ->> 'documento');
    valor := coalesce(nullif(v_json ->> 'valor','')::numeric, nullif(v_json ->> 'valor_total','')::numeric, 0); return next;
  end loop;

  -- Faturação emitida ao cliente: receita, recebida ou ainda por receber.
  for v_linha in
    select f.*, o.numero as numero_obra, o.nome as nome_obra
    from public.faturacao f
    join public.obras o on o.id=f.obra_id
    where o.empresa_id=v_atual.empresa_id
  loop
    origem_id:=v_linha.id; obra_id:=v_linha.obra_id; obra_numero:=v_linha.numero_obra::text; obra_nome:=v_linha.nome_obra;
    categoria:='faturacao'; data_lancamento:=coalesce(v_linha.data_recebimento,v_linha.data_emissao_fatura);
    entidade_nome:='Cliente'; descricao:=concat_ws(' · ','Emitida '||coalesce(v_linha.data_emissao_fatura::text,'—')||' · '||coalesce(v_linha.valor,0)::text||' €','Recebida '||coalesce(v_linha.data_recebimento::text,'—')||' · '||coalesce(v_linha.valor_recebido,0)::text||' €','Estado '||coalesce(v_linha.estado,'—'));
    documento:=v_linha.numero_fatura; valor:=coalesce(v_linha.valor_recebido,v_linha.valor,0); return next;
  end loop;
end;
$function$

definitions.fn_medicina_proteger():
CREATE OR REPLACE FUNCTION public.fn_medicina_proteger()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_owner name; v_inicial boolean;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PROTECTED_HISTORY: anule pela RPC, não apague.' USING ERRCODE='42501'; END IF;
 SELECT pg_get_userbyid(proowner) INTO v_owner FROM pg_proc
 WHERE oid='public.fn_medicina_guardar_interno(integer,text,uuid,uuid,date,text,date,integer,uuid,text)'::regprocedure;
 IF current_user<>v_owner THEN
  RAISE EXCEPTION 'PROTECTED_MEDICINE: use as RPCs de Medicina.' USING ERRCODE='42501';
 END IF;
 -- Compatibilidade restrita com a admissão existente SECURITY DEFINER.
 -- Nenhuma linha antiga recebe autor/request. Só um INSERT novo de admissão.
 v_inicial:=TG_OP='INSERT' AND coalesce(current_setting('primeline.medicina_rpc',true),'')<>'on';
 IF v_inicial THEN
  PERFORM 1 FROM public.colaboradores WHERE id=NEW.colaborador_id FOR UPDATE;
  IF NEW.resultado IS DISTINCT FROM 'Consulta inicial registada na admissão'
   OR NEW.data_proxima_consulta IS NOT NULL
   OR NOT public.fn_medicina_pode_gerir(NEW.colaborador_id)
   OR EXISTS(SELECT 1 FROM public.medicina_trabalho WHERE colaborador_id=NEW.colaborador_id) THEN
   RAISE EXCEPTION 'PROTECTED_MEDICINE: inserção fora do fluxo controlado.' USING ERRCODE='42501';
  END IF;
  NEW.registado_por:=public.fn_utilizador_atual_id(); NEW.request_id:=gen_random_uuid();
 ELSIF coalesce(current_setting('primeline.medicina_rpc',true),'')<>'on' THEN
  RAISE EXCEPTION 'PROTECTED_MEDICINE: sinalizador e proprietário obrigatórios.' USING ERRCODE='42501';
 END IF;
 IF NEW.anulado_em IS NULL AND (NEW.data_ultima_consulta IS NULL OR NEW.data_ultima_consulta>current_date) THEN
  RAISE EXCEPTION 'VALIDATION_FAILED: indique uma consulta efetivamente realizada, não futura.' USING ERRCODE='22023';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.revisao<>0 OR NEW.anulado_em IS NOT NULL OR NEW.registado_por IS NULL OR NEW.request_id IS NULL THEN
   RAISE EXCEPTION 'VALIDATION_FAILED: metadados de criação inválidos.';
  END IF;
 ELSE
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.colaborador_id IS DISTINCT FROM OLD.colaborador_id
   OR NEW.criado_em IS DISTINCT FROM OLD.criado_em OR NEW.registado_por IS DISTINCT FROM OLD.registado_por
   OR NEW.request_id IS DISTINCT FROM OLD.request_id OR NEW.revisao<>OLD.revisao+1
   OR OLD.anulado_em IS NOT NULL THEN
   RAISE EXCEPTION 'VALIDATION_FAILED: identidade/histórico imutável ou consulta anulada.';
  END IF;
 END IF;
 RETURN NEW;
END $function$

definitions.fn_alerta_nova_fatura():
CREATE OR REPLACE FUNCTION public.fn_alerta_nova_fatura()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_diretor_obra_id uuid;
  v_empresa_id uuid;
begin
  select diretor_obra_id, empresa_id into v_diretor_obra_id, v_empresa_id
  from public.obras where id = new.obra_id;

  if v_diretor_obra_id is not null then
    insert into public.alertas (
      empresa_id, obra_id, tipo, entidade_tipo, entidade_id,
      titulo, descricao, data_gatilho,
      destinatario_colaborador_id, estado
    ) values (
      v_empresa_id, new.obra_id, 'nova_fatura', 'faturas', new.id,
      'Nova fatura para aprovação (' || new.tipo_origem || ')',
      'Nº ' || coalesce(new.numero_doc, 's/nº') || ' · ' || new.valor || ' €',
      current_date,
      v_diretor_obra_id, 'pendente'
    );
  end if;

  return new;
end;
$function$

definitions.fn_resolver_alerta(uuid):
CREATE OR REPLACE FUNCTION public.fn_resolver_alerta(p_alerta_id uuid)
 RETURNS alertas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_alerta public.alertas;
  v_utilizador_id uuid;
begin
  v_utilizador_id := public.fn_utilizador_atual_id();

  if v_utilizador_id is null then
    raise exception 'Sessão autenticada sem utilizador associado.';
  end if;

  select *
  into v_alerta
  from public.alertas
  where id = p_alerta_id
  for update;

  if not found then
    raise exception 'Alerta não encontrado.';
  end if;

  if not (
    public.fn_e_admin()
    or public.fn_e_administrativo()
    or (
      public.fn_e_financeiro()
      and v_alerta.destinatario_role in ('financeiro', 'tesouraria')
    )
    or (
      v_alerta.obra_id is not null
      and public.fn_pode_editar_obra(v_alerta.obra_id)
    )
  ) then
    raise exception 'Sem permissão para resolver este alerta.';
  end if;

  if v_alerta.estado <> 'resolvido' then
    update public.alertas
    set estado = 'resolvido',
        resolvido_por = v_utilizador_id,
        resolvido_em = now()
    where id = p_alerta_id
    returning * into v_alerta;
  end if;

  return v_alerta;
end;
$function$

definitions.validar_tipo_item_auto():
CREATE OR REPLACE FUNCTION public.validar_tipo_item_auto()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_tipo text;
begin
  select tipo into v_tipo from autos_medicao where id = new.auto_medicao_id;
  if v_tipo = 'contratual' and new.item_orcamento_id is null then
    raise exception 'Auto contratual só pode ter itens de orçamento';
  end if;
  if v_tipo = 'adicional' and new.item_tee_id is null then
    raise exception 'Auto adicional só pode ter itens de TEE';
  end if;
  return new;
end;
$function$

definitions.fn_apagar_anexo_rnc(uuid):
CREATE OR REPLACE FUNCTION public.fn_apagar_anexo_rnc(p_anexo_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_path text; v_obra uuid;
begin
  select a.arquivo_url,r.obra_id into v_path,v_obra from public.rnc_anexos a join public.rnc r on r.id=a.rnc_id where a.id=p_anexo_id;
  if not found then raise exception 'Anexo não encontrado.'; end if;
  if not public.fn_pode_editar_obra(v_obra) then raise exception 'Sem permissão.' using errcode='42501'; end if;
  delete from public.rnc_anexos where id=p_anexo_id; return v_path;
end; $function$

definitions.fn_apagar_compromisso(uuid):
CREATE OR REPLACE FUNCTION public.fn_apagar_compromisso(p_compromisso_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_atual public.utilizadores;v_row public.compromissos;
begin
  select * into v_atual from public.utilizadores where id=public.fn_utilizador_atual_id() and coalesce(ativo,true);
  if not found then raise exception 'Utilizador autenticado sem perfil ativo.';end if;
  select * into v_row from public.compromissos where id=p_compromisso_id and empresa_id=v_atual.empresa_id for update;
  if not found then raise exception 'O compromisso jÃ¡ nÃ£o existe.';end if;
  if v_row.criado_por<>v_atual.id and v_row.responsavel_id<>v_atual.id and not public.fn_e_admin() then raise exception 'Sem permissÃ£o para apagar este compromisso.' using errcode='42501';end if;
  update public.alertas set estado='resolvido',expira_em=now() where tipo='compromisso_agenda' and entidade_tipo='compromissos' and entidade_id=p_compromisso_id and estado='pendente';delete from public.compromissos where id=p_compromisso_id;return true;end;$function$

definitions.fn_apagar_guia_fatura(uuid):
CREATE OR REPLACE FUNCTION public.fn_apagar_guia_fatura(p_guia_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_path text; v_obra uuid;
begin
  select g.arquivo_url,f.obra_id into v_path,v_obra from public.faturas_guias g join public.faturas f on f.id=g.fatura_id where g.id=p_guia_id;
  if not found then raise exception 'Guia não encontrada.'; end if;
  if not (public.fn_pode_editar_obra(v_obra) or public.fn_e_admin() or public.fn_e_administrativo() or public.fn_e_financeiro()) then raise exception 'Sem permissão.' using errcode='42501'; end if;
  delete from public.faturas_guias where id=p_guia_id;
  return v_path;
end;
$function$

definitions.fn_proximo_numero_rnc(uuid):
CREATE OR REPLACE FUNCTION public.fn_proximo_numero_rnc(p_obra_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not (
    public.fn_pode_ver_obra(p_obra_id)
    or public.fn_e_encarregado_da_obra(p_obra_id)
  ) then
    raise exception using
      errcode = '42501',
      message = 'Sem permissão para consultar RNCs desta obra.';
  end if;

  return (
    select coalesce(max(numero), 0) + 1
    from public.rnc
    where obra_id = p_obra_id
  );
end;
$function$

definitions.fn_registar_log_auditoria():
CREATE OR REPLACE FUNCTION public.fn_registar_log_auditoria()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_anterior jsonb;
  v_novo jsonb;
  v_registo jsonb;
  v_registo_id uuid;
  v_utilizador_id uuid;
  v_campo text;
  v_campos_sensiveis constant text[] := array[
    'password', 'senha', 'palavra_passe', 'access_token', 'refresh_token',
    'token', 'secret', 'service_role_key', 'anon_key'
  ];
begin
  if tg_op = 'INSERT' then
    v_novo := to_jsonb(new);
    v_registo := v_novo;
  elsif tg_op = 'UPDATE' then
    v_anterior := to_jsonb(old);
    v_novo := to_jsonb(new);
    v_registo := v_novo;
  else
    v_anterior := to_jsonb(old);
    v_registo := v_anterior;
  end if;

  v_registo_id := nullif(v_registo ->> coalesce(nullif(tg_argv[0], ''), 'id'), '')::uuid;

  -- Uma tabela sem UUID identificável não pode alimentar a estrutura existente.
  -- Os triggers abaixo são instalados apenas em tabelas com coluna id UUID.
  if v_registo_id is null then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  v_utilizador_id := public.fn_utilizador_atual_id();

  if tg_op = 'INSERT' then
    insert into public.log_auditoria (
      tabela_afetada, registo_id, campo, valor_anterior, valor_novo,
      utilizador_id, criado_em
    ) values (
      tg_table_schema || '.' || tg_table_name,
      v_registo_id,
      '__INSERT__',
      null,
      (v_novo - v_campos_sensiveis)::text,
      v_utilizador_id,
      now()
    );
    return new;
  end if;

  if tg_op = 'DELETE' then
    insert into public.log_auditoria (
      tabela_afetada, registo_id, campo, valor_anterior, valor_novo,
      utilizador_id, criado_em
    ) values (
      tg_table_schema || '.' || tg_table_name,
      v_registo_id,
      '__DELETE__',
      (v_anterior - v_campos_sensiveis)::text,
      null,
      v_utilizador_id,
      now()
    );
    return old;
  end if;

  for v_campo in
    select campo
    from (
      select jsonb_object_keys(v_anterior) as campo
      union
      select jsonb_object_keys(v_novo) as campo
    ) campos
    where not (campo = any(v_campos_sensiveis))
      and v_anterior -> campo is distinct from v_novo -> campo
    order by campo
  loop
    insert into public.log_auditoria (
      tabela_afetada, registo_id, campo, valor_anterior, valor_novo,
      utilizador_id, criado_em
    ) values (
      tg_table_schema || '.' || tg_table_name,
      v_registo_id,
      v_campo,
      case when v_anterior ? v_campo then (v_anterior -> v_campo)::text else null end,
      case when v_novo ? v_campo then (v_novo -> v_campo)::text else null end,
      v_utilizador_id,
      now()
    );
  end loop;

  return new;
end;
$function$

definitions.fn_resumo_custos_obra(uuid):
CREATE OR REPLACE FUNCTION public.fn_resumo_custos_obra(p_obra_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_real_pl numeric:=0;v_real_sub numeric:=0;v_est_pl numeric:=0;v_est_sub numeric:=0;v_comp_sub numeric:=0;v_adjudicado numeric:=0;
  v_componentes jsonb:='[]';v_ajustes jsonb:='[]';v_ajustes_total numeric:=0;v_faturado_cliente numeric:=0;v_venda numeric:=0;
begin
  if not (public.fn_pode_ver_obra(p_obra_id) or public.fn_e_administrativo() or public.fn_e_financeiro()) then raise exception 'Sem permissão.' using errcode='42501'; end if;
  select coalesce(sum(case when estado_custo='concluido' then coalesce(valor_real_pl,custo_total_estimado) else 0 end),0),
    coalesce(sum(case when estado_custo not in ('concluido','cancelado') then custo_total_estimado else 0 end),0)
  into v_real_pl,v_est_pl from public.orcamento_fases where obra_id=p_obra_id;
  select v_real_pl+coalesce(sum(case when c.estado_custo='concluido' then coalesce(c.valor_real_pl,c.valor_orcamentado) else 0 end),0),
    v_est_pl+coalesce(sum(case when c.estado_custo not in ('concluido','cancelado') then c.valor_orcamentado else 0 end),0)
  into v_real_pl,v_est_pl from public.planeamento_custos_componentes c join public.planeamento_itens pi on pi.id=c.planeamento_item_id join public.fases f on f.id=pi.fase_id
  where f.obra_id=p_obra_id and c.tipo='PL' and not exists(select 1 from public.orcamento_fases ofa where ofa.fase_id=f.id);
  with subs as(select c.*,s.valor_adjudicado,coalesce((select sum(p.valor) from public.pagamentos_subempreitada p where p.subempreitada_id=s.id and lower(coalesce(to_jsonb(p)->>'estado_pagamento',to_jsonb(p)->>'estado_aprovacao','pago')) in ('pago','aprovado','aprovada')),0) pago_sub
    from public.planeamento_custos_componentes c join public.planeamento_itens pi on pi.id=c.planeamento_item_id join public.fases f on f.id=pi.fase_id left join public.subempreitadas s on s.id=c.subempreitada_id where f.obra_id=p_obra_id and c.tipo='subempreitada')
  select coalesce(sum(pago_sub),0),coalesce(sum(case when remocao_estimado_confirmada_em is null and estado_custo<>'cancelado' then valor_orcamentado else 0 end),0),coalesce(sum(case when remocao_estimado_confirmada_em is not null and estado_custo<>'cancelado' then greatest(coalesce(valor_adjudicado,0)-pago_sub,0) else 0 end),0),coalesce(sum(coalesce(valor_adjudicado,0)),0)
  into v_real_sub,v_est_sub,v_comp_sub,v_adjudicado from subs;
  with rows as(
    select ofa.id,null::uuid planeamento_item_id,ofa.descricao,coalesce(f.descricao,'Fase') especialidade,'PL'::text tipo,ofa.custo_total_estimado valor_orcamentado,0::numeric valor_adjudicado,coalesce(ofa.valor_real_pl,0) valor_real,0::numeric compromisso_remanescente,ofa.estado_custo,null::uuid subempreitada_id,true remocao_confirmada,'0_Orçamento'::text fonte,
      ofa.venda_prevista,ofa.margem_prevista,ofa.deslocacoes,ofa.mao_obra,ofa.maquinas,ofa.materiais,ofa.mao_obra_sub,ofa.subempreitada
    from public.orcamento_fases ofa join public.fases f on f.id=ofa.fase_id where ofa.obra_id=p_obra_id
    union all
    select c.id,c.planeamento_item_id,pi.descricao,coalesce(e.nome,'Sem especialidade'),c.tipo,c.valor_orcamentado,coalesce(s.valor_adjudicado,0),case when c.tipo='PL' then coalesce(c.valor_real_pl,0) else coalesce((select sum(p.valor) from public.pagamentos_subempreitada p where p.subempreitada_id=s.id),0) end,
      case when c.tipo='subempreitada' and c.remocao_estimado_confirmada_em is not null then greatest(coalesce(s.valor_adjudicado,0)-coalesce((select sum(p.valor) from public.pagamentos_subempreitada p where p.subempreitada_id=s.id),0),0) else 0 end,c.estado_custo,c.subempreitada_id,c.remocao_estimado_confirmada_em is not null,'Composição manual',null,null,null,null,null,null,null,null
    from public.planeamento_custos_componentes c join public.planeamento_itens pi on pi.id=c.planeamento_item_id join public.fases f on f.id=pi.fase_id left join public.especialidades e on e.id=c.especialidade_id left join public.subempreitadas s on s.id=c.subempreitada_id
    where f.obra_id=p_obra_id and (c.tipo='subempreitada' or not exists(select 1 from public.orcamento_fases ofa where ofa.fase_id=f.id))
  ) select coalesce(jsonb_agg(to_jsonb(rows) order by especialidade,tipo),'[]') into v_componentes from rows;
  select coalesce(sum(a.valor),0),coalesce(jsonb_agg(jsonb_build_object('id',a.id,'valor',a.valor,'motivo',a.motivo,'autor',u.nome,'criado_em',a.criado_em) order by a.criado_em desc),'[]') into v_ajustes_total,v_ajustes from public.ajustes_custo_obra a left join public.utilizadores u on u.id=a.criado_por where a.obra_id=p_obra_id;
  select coalesce(max(c.venda_contratual_efetiva),max(c.venda_contratual_inicial),0) into v_venda from public.contratos c where c.obra_id=p_obra_id;
  if to_regclass('public.faturacao') is not null then execute $q$select coalesce(sum(coalesce(nullif(j->>'valor_fatura','')::numeric,nullif(j->>'valor_a_faturar','')::numeric,nullif(j->>'valor','')::numeric,0)),0) from(select to_jsonb(f) j from public.faturacao f where f.obra_id=$1)x where lower(coalesce(j->>'estado_aprovacao',j->>'estado','aprovado')) in('aprovado','aprovada','emitida','paga')$q$ into v_faturado_cliente using p_obra_id; end if;
  return jsonb_build_object('obra_id',p_obra_id,'formula','Custo Real + Custos Estimados = Estimativa Final','real',jsonb_build_object('pl',v_real_pl,'subempreitadas',v_real_sub,'total',v_real_pl+v_real_sub),'por_concluir',jsonb_build_object('pl',v_est_pl,'sub_orcamento_aguarda_confirmacao',v_est_sub,'sub_compromisso_remanescente',v_comp_sub,'total',v_est_pl+v_est_sub+v_comp_sub),'estimativa_terminus_direta',v_real_pl+v_real_sub+v_est_pl+v_est_sub+v_comp_sub,'custos_fixos',0,'pessoal_viatura_estimado',0,'ajustes_total',v_ajustes_total,'estimativa_terminus_total',v_real_pl+v_real_sub+v_est_pl+v_est_sub+v_comp_sub+v_ajustes_total,'percentagem_faturado',case when v_venda>0 then round(v_faturado_cliente*100/v_venda,2) else 0 end,'percentagem_pago',case when v_adjudicado>0 then round(v_real_sub*100/v_adjudicado,2) else 0 end,'componentes',v_componentes,'ajustes',v_ajustes);
end $function$

definitions.fn_rotear_fatura_aprovada():
CREATE OR REPLACE FUNCTION public.fn_rotear_fatura_aprovada()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.estado_aprovacao = 'aprovado' and (old.estado_aprovacao is distinct from 'aprovado') then

    if new.tipo_origem = 'subempreitada' then
      if new.subempreitada_id is null then
        raise notice 'Fatura % aprovada sem subempreitada_id — não foi possível criar o pagamento automaticamente.', new.id;
      else
        insert into public.pagamentos_subempreitada
          (subempreitada_id, numero_doc, data_fatura, valor, estado_aprovacao, aprovado_por, data_aprovacao, observacoes)
        values
          (new.subempreitada_id, new.numero_doc, new.data_fatura, new.valor, 'aprovado', new.aprovado_por, new.data_aprovacao,
           'Criado automaticamente a partir de faturas.id = ' || new.id);
      end if;

    elsif new.tipo_origem = 'estaleiro' then
      insert into public.despesas_estaleiro
        (obra_id, fornecedor_id, numero_doc, data, valor_total, estado_aprovacao, aprovado_por, data_aprovacao)
      values
        (new.obra_id, new.fornecedor_id, new.numero_doc, new.data_fatura, new.valor, 'aprovado', new.aprovado_por, new.data_aprovacao);

    elsif new.tipo_origem = 'material' then
      raise notice 'Fatura % de material aprovada — lancamentos_materiais ainda não existe.', new.id;
    end if;

  end if;
  return new;
end;
$function$

definitions.fn_apagar_anexo_fatura(uuid):
CREATE OR REPLACE FUNCTION public.fn_apagar_anexo_fatura(p_anexo_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_path text; v_obra uuid;
begin
  select a.arquivo_url,f.obra_id into v_path,v_obra from public.faturas_anexos a join public.faturas f on f.id=a.fatura_id where a.id=p_anexo_id;
  if not found then raise exception 'Anexo não encontrado.'; end if;
  if not (public.fn_pode_editar_obra(v_obra) or public.fn_e_admin() or public.fn_e_administrativo() or public.fn_e_financeiro()) then raise exception 'Sem permissão.' using errcode='42501'; end if;
  delete from public.faturas_anexos where id=p_anexo_id;
  return v_path;
end;
$function$

definitions.fn_mapa_gestao_obras_excel():
CREATE OR REPLACE FUNCTION public.fn_mapa_gestao_obras_excel()
 RETURNS TABLE(origem_id uuid, obra_id uuid, obra_numero text, obra_nome text, categoria text, data_lancamento date, entidade_nome text, descricao text, documento text, unidade_medida text, quantidade numeric, valor_unitario numeric, data_pagamento date, valor numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  base record;
  dados jsonb;
  origem regclass;
begin
  if not public.fn_pode_ver_mapa_gestao_obras() then
    raise exception 'Sem acesso ao Mapa de Gestão de Obras.'
      using errcode = '42501';
  end if;

  for base in
    select * from public.fn_mapa_gestao_obras()
  loop
    dados := '{}'::jsonb;

    origem := case base.categoria
      when 'materiais'
        then to_regclass('public.lancamentos_materiais')
      when 'estaleiro'
        then to_regclass('public.despesas_estaleiro')
      when 'mao_obra'
        then to_regclass('public.lancamentos_mao_obra')
      when 'subempreitadas'
        then to_regclass('public.pagamentos_subempreitada')
      when 'faturacao'
        then to_regclass('public.faturacao')
      else null
    end;

    if origem is not null then
      execute format(
        'select to_jsonb(t) from %s t where id=$1',
        origem
      )
      into dados
      using base.origem_id;

      dados := coalesce(dados, '{}'::jsonb);
    end if;

    origem_id := base.origem_id;
    obra_id := base.obra_id;
    obra_numero := base.obra_numero;
    obra_nome := base.obra_nome;
    categoria := base.categoria;
    data_lancamento := base.data_lancamento;
    entidade_nome := base.entidade_nome;
    descricao := base.descricao;
    documento := base.documento;

    -- mgo-periodicidade-v1
    if base.categoria='mao_obra' and dados->>'tipo_registo'='mensal' then
      descricao:=concat(
        'TOTAL MENSAL ',
        to_char((dados->>'mes_referencia')::date,'MM/YYYY'),
        ' · ',
        base.descricao
      );
    end if;

    unidade_medida := coalesce(
      nullif(dados->>'unidade_medida', ''),
      nullif(dados->>'unidade', ''),
      case when base.categoria = 'mao_obra' then 'h' end
    );

    quantidade := coalesce(
      nullif(dados->>'quantidade', '')::numeric,
      nullif(dados->>'horas', '')::numeric
    );

    valor_unitario := coalesce(
      nullif(dados->>'valor_unitario', '')::numeric,
      nullif(dados->>'valor_hora', '')::numeric
    );

    data_pagamento :=
      nullif(left(dados->>'data_pagamento', 10), '')::date;

    valor := base.valor;

    return next;
  end loop;
end
$function$

definitions.fn_quadro_proteger_escrita():
CREATE OR REPLACE FUNCTION public.fn_quadro_proteger_escrita()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  u public.utilizadores;
  c public.colaboradores;
  q public.quadro_pessoal_alocacao;
BEGIN
  IF TG_OP = 'DELETE' THEN
    q := OLD;
  ELSE
    q := NEW;
  END IF;

  IF EXISTS(SELECT 1 FROM public.quadro_escrita_interna p WHERE p.transacao=txid_current() AND p.colaborador_id=q.colaborador_id AND p.data=q.data AND p.utilizador_id=public.fn_utilizador_atual_id()) THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
  END IF;
  SELECT *
  INTO c
  FROM public.colaboradores
  WHERE id = q.colaborador_id;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(q.colaborador_id::text, 0)
  );

  IF TG_OP = 'UPDATE'
     AND (
       NEW.id IS DISTINCT FROM OLD.id
       OR NEW.colaborador_id IS DISTINCT FROM OLD.colaborador_id
     )
  THEN
    RAISE EXCEPTION 'Não é permitido alterar a identidade da alocação.';
  END IF;

  SELECT *
  INTO u
  FROM public.utilizadores
  WHERE id = public.fn_utilizador_atual_id()
    AND ativo IS TRUE;

  IF u.id IS NULL THEN

    IF session_user NOT IN ('postgres', 'supabase_admin')
       OR auth.uid() IS NOT NULL
    THEN
      RAISE EXCEPTION 'Sem utilizador autorizado.'
      USING ERRCODE = '42501';
    END IF;

  ELSE

    IF c.empresa_id IS DISTINCT FROM u.empresa_id THEN
      RAISE EXCEPTION 'Colaborador de outra empresa.'
      USING ERRCODE = '42501';
    END IF;

    IF NOT public.fn_pode_gerir_quadro(NULL) THEN

      IF TG_OP = 'DELETE'
         OR NOT EXISTS (
           SELECT 1
           FROM public.quadro_pessoal_rpc_permit p
           WHERE p.transacao = txid_current()
             AND p.utilizador_id = u.id
             AND p.colaborador_id = NEW.colaborador_id
             AND p.destino_id = NEW.obra_id
             AND p.data = NEW.data
             AND p.periodo = NEW.periodo
             AND NEW.tipo_alocacao = 'obra'
             AND NEW.descricao_livre IS NULL
             AND (
               (
                 TG_OP = 'INSERT'
                 AND p.origem_id IS NULL
               )
               OR (
                 TG_OP = 'UPDATE'
                 AND p.origem_id = OLD.id
                 AND NEW.data = OLD.data
                 AND NEW.periodo = OLD.periodo
               )
             )
             AND public.fn_quadro_minha_obra(p.destino_id)
         )
      THEN
        RAISE EXCEPTION 'Sem autorização para editar o Quadro Geral.'
        USING ERRCODE = '42501';
      END IF;

    END IF;
  END IF;

  IF q.obra_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.obras o
       WHERE o.id = q.obra_id
         AND o.empresa_id = c.empresa_id
     )
  THEN
    RAISE EXCEPTION 'Obra de outra empresa.'
    USING ERRCODE = '42501';
  END IF;

  IF TG_OP <> 'DELETE' THEN

    IF c.id IS NULL
       OR (
         c.data_saida IS NOT NULL
         AND c.data_saida <= NEW.data
       )
       OR c.data_admissao > NEW.data
    THEN
      RAISE EXCEPTION 'Colaborador indisponível nesta data.';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.ausencias a
      WHERE a.colaborador_id = NEW.colaborador_id
        AND a.data = NEW.data
    )
    THEN
      RAISE EXCEPTION
        'Este colaborador está de férias/ausente nesta data.';
    END IF;

    IF u.id IS NOT NULL
       AND TG_OP = 'INSERT'
    THEN
      NEW.criado_por := u.id;
    END IF;

    IF TG_OP = 'UPDATE' THEN
      NEW.criado_por := OLD.criado_por;
    END IF;

  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END
$function$

definitions.fn_bloquear_verificacao_rnc():
CREATE OR REPLACE FUNCTION public.fn_bloquear_verificacao_rnc()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.estado = 'verificado' and old.estado is distinct from 'verificado' then
    if not exists (select 1 from public.rnc_anexos where rnc_id = new.id)
       and (new.observacao_verificacao is null or trim(new.observacao_verificacao) = '') then
      raise exception 'Não é possível verificar uma RNC sem anexo comprovativo ou observação de verificação.';
    end if;
  end if;
  return new;
end;
$function$

definitions.fn_executar_rotinas_diarias():
CREATE OR REPLACE FUNCTION public.fn_executar_rotinas_diarias()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_baselines jsonb := null;
  v_primeiras_consultas integer := 0;
  v_vencimentos integer := 0;
  v_seguros integer := 0;
  v_equipa_tecnica jsonb := '{}'::jsonb;
  v_imoveis_orcamentos jsonb := '{}'::jsonb;
begin
  if to_regprocedure(
    'public.fn_verificar_congelamentos_pendentes()'
  ) is not null then
    execute
      'select to_jsonb(public.fn_verificar_congelamentos_pendentes())'
    into v_baselines;
  end if;

  if to_regprocedure(
    'public.fn_verificar_primeiras_consultas_medicina()'
  ) is not null then
    v_primeiras_consultas :=
      public.fn_verificar_primeiras_consultas_medicina();
  end if;

  if to_regprocedure(
    'public.fn_verificar_alertas_vencimento()'
  ) is not null then
    v_vencimentos :=
      public.fn_verificar_alertas_vencimento();
  end if;

  if to_regprocedure(
    'public.fn_verificar_alertas_seguro_viaturas()'
  ) is not null then
    v_seguros :=
      public.fn_verificar_alertas_seguro_viaturas();
  end if;

  if to_regprocedure(
    'public.fn_verificar_alertas_fim_contrato()'
  ) is not null then
    perform public.fn_verificar_alertas_fim_contrato();
  end if;

  if to_regprocedure(
    'public.fn_verificar_alertas_imoveis_orcamentos(date)'
  ) is not null then
    v_imoveis_orcamentos :=
      public.fn_verificar_alertas_imoveis_orcamentos(current_date);
  end if;

  v_equipa_tecnica :=
    public.fn_criar_lembretes_equipa_tecnica(current_date);

  return jsonb_build_object(
    'baselines', v_baselines,
    'primeiras_consultas_criadas', v_primeiras_consultas,
    'alertas_vencimento_criados', v_vencimentos,
    'alertas_seguro_criados', v_seguros,
    'contratos_trabalho_verificados', true,
    'equipa_tecnica', v_equipa_tecnica,
    'imoveis_orcamentos', v_imoveis_orcamentos
  );
end;
$function$

definitions.fn_registar_percurso_fatura():
CREATE OR REPLACE FUNCTION public.fn_registar_percurso_fatura()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    new.criado_por := coalesce(
      new.criado_por,
      public.fn_utilizador_atual_id()
    );
  end if;

  if tg_op = 'UPDATE'
     and new.estado_aprovacao is distinct from old.estado_aprovacao then
    new.aprovado_por := public.fn_utilizador_atual_id();
    new.data_aprovacao := coalesce(new.data_aprovacao, now());
  end if;

  if tg_op = 'UPDATE'
     and new.estado_pagamento = 'pago'
     and new.estado_pagamento is distinct from old.estado_pagamento then
    new.pago_por := public.fn_utilizador_atual_id();
    new.data_pagamento := coalesce(
      new.data_pagamento,
      current_date
    );
  end if;

  return new;
end;
$function$

definitions.fn_rh_importar(jsonb,boolean):
CREATE OR REPLACE FUNCTION public.fn_rh_importar(p_linhas jsonb, p_confirmar boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_empresa uuid:=public.fn_rh_empresa(true); v_row jsonb; v_result jsonb:='[]';
  v_validado jsonb; v_erros integer:=0; v_seen uuid[]:='{}'; v_id uuid; v_patch jsonb;
begin
  p_confirmar:=coalesce(p_confirmar,false);
  if jsonb_typeof(p_linhas) is distinct from 'array' then raise exception 'Lista inválida.'; end if;
  if octet_length(p_linhas::text)>4194304 then raise exception 'Lote demasiado grande (máximo 4 MB).'; end if;
  if jsonb_array_length(p_linhas) not between 1 and 1000 then raise exception 'Importe entre 1 e 1000 linhas.'; end if;
  perform pg_advisory_xact_lock(hashtextextended('rh:'||v_empresa::text,0));
  for v_row in select value from jsonb_array_elements(p_linhas) loop
    begin
      v_id:=nullif(v_row->>'id','')::uuid;
      if v_id is null or v_id=any(v_seen) then raise exception 'ID ausente ou repetido.'; end if;
      v_seen:=array_append(v_seen,v_id);
      if coalesce(v_row->'campos','{}') ? 'data_saida' then raise exception 'Excel não altera ativo/inativo.'; end if;
      select coalesce(jsonb_object_agg(key,value),'{}') into v_patch from jsonb_each(coalesce(v_row->'campos','{}'))
        where value<>'null'::jsonb and btrim(value#>>'{}')<>'';
      v_row:=v_row||jsonb_build_object('campos',v_patch);
      if btrim(coalesce(v_row->>'niss',''))='' then v_row:=v_row-'niss'; end if;
      if jsonb_typeof(v_row->'contrato')='object' then
        select coalesce(jsonb_object_agg(key,value),'{}') into v_patch from jsonb_each(v_row->'contrato')
          where value<>'null'::jsonb and btrim(value#>>'{}')<>'';
        v_row:=v_row-'contrato';
        if v_patch<>'{}'::jsonb then v_row:=v_row||jsonb_build_object('contrato',v_patch); end if;
      end if;
      v_validado:=public.fn_rh_guardar_interno(v_row,not p_confirmar,true);
      v_result:=v_result||jsonb_build_array(v_validado||jsonb_build_object('id',v_id,'ok',true));
    exception when others then
      v_erros:=v_erros+1;
      v_result:=v_result||jsonb_build_array(jsonb_build_object('id',v_row->>'id','ok',false,'erro',sqlerrm));
    end;
  end loop;
  if p_confirmar and v_erros>0 then raise exception 'Lote cancelado; nenhuma alteração guardada. %',v_result; end if;
  return jsonb_build_object('linhas',v_result,'erros',v_erros,'confirmado',p_confirmar);
end $function$

definitions.fn_sincronizar_tee_previsao():
CREATE OR REPLACE FUNCTION public.fn_sincronizar_tee_previsao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(
       current_setting(
         'primeline.tee_revision_import',
         true
       ),
       ''
     ) = 'on'
  THEN
    IF tg_op = 'DELETE' THEN
      RETURN OLD;
    END IF;

    RETURN NEW;
  END IF;

  IF tg_op <> 'INSERT'
     AND old.estado_aprovacao_cliente = 'aprovado'
     AND old.data_inicio_execucao IS NOT NULL
     AND old.data_fim_execucao IS NOT NULL
  THEN
    PERFORM public.fn_ajustar_saida_prevista_mensal(
      old.obra_id,
      old.data_inicio_execucao,
      -COALESCE(old.preco_custo, 0)
    );
  END IF;

  IF tg_op <> 'DELETE'
     AND new.estado_aprovacao_cliente = 'aprovado'
     AND new.data_inicio_execucao IS NOT NULL
     AND new.data_fim_execucao IS NOT NULL
  THEN
    PERFORM public.fn_ajustar_saida_prevista_mensal(
      new.obra_id,
      new.data_inicio_execucao,
      COALESCE(new.preco_custo, 0)
    );
  END IF;

  IF tg_op = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$function$

