definitions.validar_consumo_adiantamento():
CREATE OR REPLACE FUNCTION public.validar_consumo_adiantamento()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_total_adiantamento numeric;
  v_ja_consumido numeric;
begin
  select c.valor_adiantamento into v_total_adiantamento
  from contratos c where c.obra_id = new.obra_id;

  select coalesce(sum(valor_deduzido_adiantamento), 0) into v_ja_consumido
  from autos_medicao where obra_id = new.obra_id and id != new.id;

  if v_total_adiantamento is not null
     and v_ja_consumido + new.valor_deduzido_adiantamento > v_total_adiantamento then
    raise exception 'Adiantamento da obra % excedido: % disponível, % a deduzir',
      new.obra_id, v_total_adiantamento - v_ja_consumido, new.valor_deduzido_adiantamento;
  end if;
  return new;
end;
$function$

definitions.validar_soma_afetacao_diaria():
CREATE OR REPLACE FUNCTION public.validar_soma_afetacao_diaria()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_soma numeric;
begin
  if TG_TABLE_NAME = 'afetacao_semanal' then
    select coalesce(sum(percentual_afetacao), 0) into v_soma
    from afetacao_semanal
    where colaborador_id = new.colaborador_id and data = new.data and id != new.id;
  else
    select coalesce(sum(percentual_afetacao), 0) into v_soma
    from lancamentos_mao_obra
    where colaborador_id = new.colaborador_id and data = new.data and id != new.id;
  end if;

  if v_soma + new.percentual_afetacao > 1.0 then
    raise exception 'Colaborador % já tem % de afetação em %, não pode exceder 100%%',
      new.colaborador_id, v_soma * 100, new.data;
  end if;
  return new;
end;
$function$

definitions.fn_normalizar_estado_ausencia():
CREATE OR REPLACE FUNCTION public.fn_normalizar_estado_ausencia()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.tipo in ('ferias', 'falta_justificada_com_remuneracao') then
      new.estado := 'confirmada';
    elsif new.tipo in ('falta_injustificada', 'falta_justificada_sem_remuneracao') then
      new.estado := 'ausente_pendente';
    end if;
  end if;

  if new.estado = 'justificada' and nullif(btrim(new.comentario), '') is null then
    raise exception 'Para justificar a ausência é obrigatório preencher o comentário.';
  end if;

  return new;
end;
$function$

