definitions.fn_mesclar_fornecedor(uuid,uuid):
CREATE OR REPLACE FUNCTION public.fn_mesclar_fornecedor(p_fornecedor_origem_id uuid, p_fornecedor_destino_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_atual public.utilizadores;
  v_origem public.fornecedores;
  v_destino public.fornecedores;
  v_previa jsonb;
  v_ref record;
  v_movidos bigint;
  v_total_movidos bigint := 0;
  v_impacto jsonb := '{}'::jsonb;
  v_tipo text;
begin
  if not (public.fn_e_admin() or public.fn_e_administrativo()) then
    raise exception 'SÃ³ o Administrativo ou a GestÃ£o da Plataforma pode mesclar fornecedores.' using errcode = '42501';
  end if;

  v_previa := public.fn_previsualizar_mesclagem_fornecedor(
    p_fornecedor_origem_id, p_fornecedor_destino_id
  );
  if not coalesce((v_previa ->> 'pode_mesclar')::boolean, false) then
    raise exception 'A mesclagem tem conflitos que precisam de revisÃ£o: %', v_previa -> 'conflitos';
  end if;

  select * into v_atual from public.utilizadores
  where id = public.fn_utilizador_atual_id() and coalesce(ativo, true);
  select * into v_origem from public.fornecedores
  where id = p_fornecedor_origem_id and empresa_id = v_atual.empresa_id
  for update;
  select * into v_destino from public.fornecedores
  where id = p_fornecedor_destino_id and empresa_id = v_atual.empresa_id
  for update;
  if v_origem.id is null or v_destino.id is null then
    raise exception 'Um dos fornecedores deixou de estar disponÃ­vel. Atualize a pÃ¡gina.';
  end if;

  perform set_config('app.mesclagem_fornecedor', 'on', true);

  update public.faturas
  set fornecedor_nome_original = coalesce(nullif(fornecedor_nome_original, ''), v_origem.nome)
  where fornecedor_id = p_fornecedor_origem_id;

  insert into public.fornecedores_zonas(fornecedor_id, zona, criado_por)
  select p_fornecedor_destino_id, zona, coalesce(criado_por, v_atual.id)
  from public.fornecedores_zonas where fornecedor_id = p_fornecedor_origem_id
  on conflict (fornecedor_id, zona) do nothing;

  insert into public.fornecedores_especialidades(fornecedor_id, especialidade_id, origem, criado_por)
  select p_fornecedor_destino_id, especialidade_id, origem, coalesce(criado_por, v_atual.id)
  from public.fornecedores_especialidades where fornecedor_id = p_fornecedor_origem_id
  on conflict (fornecedor_id, especialidade_id) do nothing;

  update public.fornecedores_aliases
  set fornecedor_id = p_fornecedor_destino_id
  where fornecedor_id = p_fornecedor_origem_id;

  insert into public.fornecedores_aliases(
    empresa_id, fornecedor_id, nome, nif, email, fornecedor_origem_id, criado_por
  ) values (
    v_atual.empresa_id, p_fornecedor_destino_id, v_origem.nome, v_origem.nif, v_origem.email,
    p_fornecedor_origem_id, v_atual.id
  ) on conflict (empresa_id, nome_normalizado) do nothing;
  delete from public.fornecedores_zonas where fornecedor_id = p_fornecedor_origem_id;
  delete from public.fornecedores_especialidades where fornecedor_id = p_fornecedor_origem_id;

  for v_ref in
    select c.conrelid::regclass as tabela, a.attname as coluna
    from pg_constraint c
    join pg_attribute a on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
    where c.contype = 'f'
      and c.confrelid = 'public.fornecedores'::regclass
      and array_length(c.conkey, 1) = 1
      and c.conrelid not in (
        'public.fornecedores_zonas'::regclass,
        'public.fornecedores_especialidades'::regclass,
        'public.fornecedores_aliases'::regclass
      )
  loop
    execute format('update %s set %I = $1 where %I = $2',
      v_ref.tabela, v_ref.coluna, v_ref.coluna)
      using p_fornecedor_destino_id, p_fornecedor_origem_id;
    get diagnostics v_movidos = row_count;
    if v_movidos > 0 then
      v_total_movidos := v_total_movidos + v_movidos;
      v_impacto := v_impacto || jsonb_build_object(
        v_ref.tabela::text || '.' || v_ref.coluna, v_movidos
      );
    end if;
  end loop;

  v_tipo := case
    when v_destino.tipo_entidade = 'ambos' or v_origem.tipo_entidade = 'ambos' then 'ambos'
    when v_destino.tipo_entidade in ('fornecedor', 'subempreiteiro')
     and v_origem.tipo_entidade in ('fornecedor', 'subempreiteiro')
     and v_destino.tipo_entidade <> v_origem.tipo_entidade then 'ambos'
    when v_destino.tipo_entidade in ('fornecedor', 'subempreiteiro') then v_destino.tipo_entidade
    else v_origem.tipo_entidade
  end;

  update public.fornecedores set
    nif = coalesce(nullif(nif, ''), nullif(v_origem.nif, '')),
    email = coalesce(nullif(email, ''), nullif(v_origem.email, '')),
    telefone = coalesce(nullif(telefone, ''), nullif(v_origem.telefone, '')),
    representante = coalesce(nullif(representante, ''), nullif(v_origem.representante, '')),
    notas = coalesce(nullif(notas, ''), nullif(v_origem.notas, '')),
    tipo_entidade = coalesce(nullif(v_tipo, ''), tipo_entidade),
    estado_confianca = case
      when coalesce(estado_confianca, 'nao_avaliado') = 'nao_avaliado'
       and coalesce(v_origem.estado_confianca, 'nao_avaliado') <> 'nao_avaliado'
      then v_origem.estado_confianca else estado_confianca end
  where id = p_fornecedor_destino_id;

  insert into public.fornecedores_mesclagens(
    empresa_id, fornecedor_origem_id, fornecedor_destino_id,
    nome_origem, nome_destino, impacto, executado_por
  ) values (
    v_atual.empresa_id, p_fornecedor_origem_id, p_fornecedor_destino_id,
    v_origem.nome, v_destino.nome,
    jsonb_build_object('total_movidos', v_total_movidos, 'tabelas', v_impacto),
    v_atual.id
  );

  delete from public.fornecedores where id = p_fornecedor_origem_id;

  return jsonb_build_object(
    'mesclado', true,
    'origem_id', p_fornecedor_origem_id,
    'destino_id', p_fornecedor_destino_id,
    'total_movidos', v_total_movidos,
    'impacto', v_impacto,
    'alias_preservado', v_origem.nome
  );
exception
  when unique_violation then
    raise exception 'A mesclagem foi cancelada sem alterar dados porque criaria um registo duplicado: %', sqlerrm;
end;
$function$

definitions.fn_proteger_atribuicao_viatura():
CREATE OR REPLACE FUNCTION public.fn_proteger_atribuicao_viatura()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF coalesce(current_setting('primeline.atribuicao_viatura_rpc', true), '') <> 'on'
     OR current_user <> (
       SELECT pg_get_userbyid(proowner) FROM pg_proc
       WHERE oid = 'public.fn_alterar_responsavel_viatura(integer,uuid,uuid,integer,uuid,text)'::regprocedure
     ) THEN
    RAISE EXCEPTION 'PROTECTED_ASSIGNMENT: use fn_alterar_responsavel_viatura.'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.atribuicao_revisao <> OLD.atribuicao_revisao + 1
     OR NEW.colaborador_atribuido_id IS NOT DISTINCT FROM OLD.colaborador_atribuido_id THEN
    RAISE EXCEPTION 'VALIDATION_FAILED: transição de atribuição inválida.' USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$function$

definitions.fn_quadro_contexto_v1(date,date):
CREATE OR REPLACE FUNCTION public.fn_quadro_contexto_v1(p_inicio date, p_fim date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE u public.utilizadores; v_allocations jsonb; v_revisions jsonb; v_read jsonb; v_edit jsonb;
BEGIN
 SELECT * INTO u FROM public.utilizadores WHERE id=public.fn_utilizador_atual_id() AND ativo IS TRUE;
 IF u.id IS NULL OR u.empresa_id IS NULL THEN RAISE EXCEPTION 'PERMISSION_DENIED: sessão sem utilizador ativo.' USING ERRCODE='42501'; END IF;
 IF NOT public.fn_quadro_pode_consultar_v1() THEN RAISE EXCEPTION 'PERMISSION_DENIED: sem responsabilidade autorizada para consultar o Quadro.' USING ERRCODE='42501'; END IF;
 IF p_inicio IS NULL OR p_fim IS NULL OR p_fim<p_inicio OR p_fim-p_inicio>93 THEN RAISE EXCEPTION 'VALIDATION_ERROR: intervalo inválido.'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.data,q.id),'[]') INTO v_allocations
 FROM generate_series(p_inicio::timestamp,p_fim::timestamp,interval '1 day') d(data)
 CROSS JOIN LATERAL public.fn_quadro_resolver_data(d.data::date) q JOIN public.colaboradores c ON c.id=q.colaborador_id
 WHERE c.empresa_id=u.empresa_id AND q.data BETWEEN p_inicio AND p_fim
 AND (public.fn_quadro_leitura_global_v1() OR (q.tipo_alocacao='obra' AND public.fn_quadro_ler_obra(q.obra_id)));
 SELECT coalesce(jsonb_agg(to_jsonb(d)),'[]') INTO v_revisions FROM public.quadro_dias_revisoes d
 JOIN public.colaboradores c ON c.id=d.colaborador_id WHERE c.empresa_id=u.empresa_id AND d.data BETWEEN p_inicio AND p_fim
 AND (public.fn_quadro_leitura_global_v1() OR EXISTS(SELECT 1 FROM unnest(d.obras_visiveis) w(id) WHERE public.fn_quadro_ler_obra(w.id)) OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_allocations) a
 WHERE (a->>'colaborador_id')::uuid=d.colaborador_id AND (a->>'data')::date=d.data));
 SELECT coalesce(jsonb_agg(o.id ORDER BY o.id),'[]') INTO v_read FROM public.obras o WHERE o.empresa_id=u.empresa_id AND public.fn_quadro_ler_obra(o.id);
 SELECT coalesce(jsonb_agg(o.id ORDER BY o.id),'[]') INTO v_edit FROM public.obras o WHERE o.empresa_id=u.empresa_id AND (public.fn_quadro_pode_gerir_v1(o.id) OR public.fn_quadro_minha_obra_v1(o.id));
 RETURN jsonb_build_object('version',1,'allocations',v_allocations,'revisions',v_revisions,
 'can_manage_global',public.fn_quadro_pode_gerir_v1(NULL),'read_work_ids',v_read,'edit_work_ids',v_edit,
 'people',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'nome',c.nome,'funcao',c.funcao,'data_admissao',c.data_admissao,'data_saida',c.data_saida) ORDER BY c.nome),'[]') FROM public.colaboradores c WHERE c.empresa_id=u.empresa_id AND c.data_saida IS NULL AND (
 public.fn_quadro_leitura_global_v1() OR u.funcao='encarregado' OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_allocations) a WHERE (a->>'colaborador_id')::uuid=c.id))),
 'works',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'numero',o.numero,'nome',o.nome,'situacao',o.situacao) ORDER BY o.numero),'[]') FROM public.obras o WHERE o.empresa_id=u.empresa_id AND public.fn_quadro_ler_obra(o.id)));
END $function$

definitions.fn_resumo_mapa_comparativo(uuid):
CREATE OR REPLACE FUNCTION public.fn_resumo_mapa_comparativo(p_mapa_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_mapa public.mapas_comparativos; v_melhores jsonb; v_itens_sem_cotacao integer;
begin
  select * into v_mapa from public.mapas_comparativos where id=p_mapa_id;
  if not found then raise exception 'Mapa comparativo não encontrado.' using errcode='P0002'; end if;
  if not public.fn_pode_ver_obra(v_mapa.obra_id) then raise exception 'Sem acesso a esta obra.' using errcode='42501'; end if;
  with classificados as (
    select i.id item_id,i.numero,i.designacao,p.preco_total,pr.fornecedor_id,f.nome fornecedor,
      row_number() over(partition by i.id order by p.preco_total,pr.id) posicao
    from public.comparativo_itens i
    join public.comparativo_itens_precos p on p.item_id=i.id and p.comparavel and p.estado_ambito='incluido'
    join public.comparativo_propostas pr on pr.id=p.proposta_id
    join public.fornecedores f on f.id=pr.fornecedor_id where i.mapa_id=p_mapa_id
  )
  select coalesce(jsonb_agg(jsonb_build_object('item_id',item_id,'numero',numero,'designacao',designacao,
    'fornecedor_id',fornecedor_id,'fornecedor',fornecedor,'melhor_preco',preco_total) order by numero),'[]'::jsonb)
  into v_melhores from classificados where posicao=1;
  select count(*) into v_itens_sem_cotacao from public.comparativo_itens i where i.mapa_id=p_mapa_id
    and not exists(select 1 from public.comparativo_itens_precos p where p.item_id=i.id and p.comparavel and p.estado_ambito='incluido');
  return jsonb_build_object('mapa',to_jsonb(v_mapa),'melhores_por_item',v_melhores,
    'itens_sem_cotacao',v_itens_sem_cotacao,'melhor_preco_comparativo',v_mapa.melhor_preco_comparativo,
    'diferenca_negociacao',v_mapa.diferenca_negociacao,'desvio_orcamento_valor',v_mapa.desvio_orcamento_valor,
    'desvio_orcamento_percentual',v_mapa.desvio_orcamento_percentual,'margem_real_valor',v_mapa.margem_real_valor,
    'margem_real_percentual',v_mapa.margem_real_percentual);
end $function$

definitions.validar_aprovador_diretor_obra():
CREATE OR REPLACE FUNCTION public.validar_aprovador_diretor_obra()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.estado_aprovacao = 'aprovado' and new.aprovado_por is not null then
    if not exists (
      select 1 from obras o
      where o.id = new.obra_id and o.diretor_obra_id = new.aprovado_por
    ) and not exists (
      select 1 from permissoes_obra p
      where p.obra_id = new.obra_id and p.utilizador_id = new.aprovado_por
        and p.nivel_acesso = 'aprovacao'
    ) then
      raise exception 'Aprovador tem de ser o diretor de obra ou ter nível de aprovação atribuído nesta obra';
    end if;
  end if;
  return new;
end;
$function$

