definitions.fn_eliminar_item_comparativo(uuid):
CREATE OR REPLACE FUNCTION public.fn_eliminar_item_comparativo(p_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_mapa_id uuid;
  v_obra_id uuid;
  v_precos_antes integer;
  v_precos_depois integer;
begin
  select i.mapa_id, m.obra_id
  into v_mapa_id, v_obra_id
  from public.comparativo_itens i
  join public.mapas_comparativos m on m.id = i.mapa_id
  where i.id = p_item_id
  for update of i;

  if not found then
    raise exception 'Item do mapa comparativo não encontrado.'
      using errcode = 'P0002';
  end if;

  if not public.fn_pode_editar_obra(v_obra_id) then
    raise exception 'Sem permissão para eliminar itens desta obra.'
      using errcode = '42501';
  end if;

  select count(*)
  into v_precos_antes
  from public.comparativo_itens_precos
  where item_id = p_item_id;

  delete from public.comparativo_itens
  where id = p_item_id;

  select count(*)
  into v_precos_depois
  from public.comparativo_itens_precos
  where item_id = p_item_id;

  if v_precos_depois <> 0 then
    raise exception
      'A eliminação foi cancelada: existem preços órfãos para o item.';
  end if;

  perform public.fn_atualizar_melhor_preco_comparativo(v_mapa_id);

  return jsonb_build_object(
    'item_id', p_item_id,
    'precos_eliminados', v_precos_antes,
    'precos_restantes', v_precos_depois
  );
end;
$function$

definitions.fn_eliminar_mapa_comparativo(uuid):
CREATE OR REPLACE FUNCTION public.fn_eliminar_mapa_comparativo(p_mapa_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_obra_id uuid;
  v_item_ids uuid[];
  v_proposta_ids uuid[];
  v_itens_antes integer;
  v_propostas_antes integer;
  v_precos_antes integer;
  v_ajustes_antes integer;
  v_mapas_depois integer;
  v_itens_depois integer;
  v_propostas_depois integer;
  v_precos_depois integer;
  v_ajustes_depois integer;
begin
  select obra_id into v_obra_id
  from public.mapas_comparativos
  where id = p_mapa_id
  for update;

  if not found then
    raise exception 'Mapa comparativo não encontrado.'
      using errcode = 'P0002';
  end if;

  if not public.fn_pode_editar_obra(v_obra_id) then
    raise exception 'Sem permissão para eliminar este mapa comparativo.'
      using errcode = '42501';
  end if;

  if exists (
    select 1
    from public.subempreitadas
    where mapa_comparativo_id = p_mapa_id
  ) then
    raise exception 'Este mapa já originou uma subempreitada e não pode ser eliminado. O histórico da adjudicação deve ser preservado.'
      using errcode = '23503';
  end if;

  select coalesce(array_agg(id), '{}'::uuid[]), count(*)
  into v_item_ids, v_itens_antes
  from public.comparativo_itens
  where mapa_id = p_mapa_id;

  select coalesce(array_agg(id), '{}'::uuid[]), count(*)
  into v_proposta_ids, v_propostas_antes
  from public.comparativo_propostas
  where mapa_id = p_mapa_id;

  select count(*) into v_precos_antes
  from public.comparativo_itens_precos
  where item_id = any(v_item_ids)
     or proposta_id = any(v_proposta_ids);

  select count(*) into v_ajustes_antes
  from public.comparativo_ajustes
  where mapa_id = p_mapa_id;

  delete from public.mapas_comparativos
  where id = p_mapa_id;

  select count(*) into v_mapas_depois
  from public.mapas_comparativos
  where id = p_mapa_id;

  select count(*) into v_itens_depois
  from public.comparativo_itens
  where id = any(v_item_ids);

  select count(*) into v_propostas_depois
  from public.comparativo_propostas
  where id = any(v_proposta_ids);

  select count(*) into v_precos_depois
  from public.comparativo_itens_precos
  where item_id = any(v_item_ids)
     or proposta_id = any(v_proposta_ids);

  select count(*) into v_ajustes_depois
  from public.comparativo_ajustes
  where mapa_id = p_mapa_id
     or proposta_id = any(v_proposta_ids);

  if v_mapas_depois <> 0
     or v_itens_depois <> 0
     or v_propostas_depois <> 0
     or v_precos_depois <> 0
     or v_ajustes_depois <> 0 then
    raise exception 'A eliminação foi cancelada: existem registos relacionados com o mapa.';
  end if;

  return jsonb_build_object(
    'mapa_id', p_mapa_id,
    'itens_eliminados', v_itens_antes,
    'propostas_eliminadas', v_propostas_antes,
    'precos_eliminados', v_precos_antes,
    'ajustes_eliminados', v_ajustes_antes,
    'mapas_restantes', v_mapas_depois,
    'itens_restantes', v_itens_depois,
    'propostas_restantes', v_propostas_depois,
    'precos_restantes', v_precos_depois,
    'ajustes_restantes', v_ajustes_depois
  );
end;
$function$

definitions.fn_bloquear_venda_contrato_direta():
CREATE OR REPLACE FUNCTION public.fn_bloquear_venda_contrato_direta()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if (new.venda_contratual_inicial,new.venda_contratual_efetiva) is distinct from (old.venda_contratual_inicial,old.venda_contratual_efetiva)
     and coalesce(current_setting('primeline.alteracao_via_tee',true),'')<>'on' then
    raise exception 'O preço de venda só pode ser alterado por um TEE formal aprovado.' using errcode='42501';
  end if;
  return new;
end;
$function$

definitions.fn_disparar_recalculo_planeamento():
CREATE OR REPLACE FUNCTION public.fn_disparar_recalculo_planeamento()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_fim_anterior date := coalesce(old.data_fim_real, old.data_fim_prevista);
  v_fim_novo date := coalesce(new.data_fim_real, new.data_fim_prevista);
begin
  if current_setting('primeline.recalculo_cascata', true) = 'ativo' then
    return new;
  end if;
  if v_fim_novo is not null and (v_fim_anterior is null or v_fim_novo > v_fim_anterior) then
    perform public.fn_recalcular_planeamento_cascata(new.id);
  end if;
  return new;
end;
$function$

definitions.fn_validar_tee_pedido_prorrogacao():
CREATE OR REPLACE FUNCTION public.fn_validar_tee_pedido_prorrogacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.tee_id is not null and not exists (
    select 1 from public.alteracoes_tee t
    where t.id = new.tee_id and t.obra_id = new.obra_id
  ) then
    raise exception using errcode = '23514',
      message = 'O TEE de origem tem de pertencer à mesma obra do pedido de prorrogação.';
  end if;
  return new;
end;
$function$

definitions.fn_calcular_preco_item_comparativo():
CREATE OR REPLACE FUNCTION public.fn_calcular_preco_item_comparativo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_quantidade numeric;
  v_mapa_item uuid;
  v_mapa_proposta uuid;
begin
  select mapa_id, quantidade
  into v_mapa_item, v_quantidade
  from public.comparativo_itens
  where id = new.item_id;

  select mapa_id
  into v_mapa_proposta
  from public.comparativo_propostas
  where id = new.proposta_id;

  if v_mapa_item is null
    or v_mapa_item is distinct from v_mapa_proposta then
    raise exception
      'O item e a proposta devem pertencer ao mesmo mapa comparativo.'
      using errcode = '23514';
  end if;

  new.preco_total := round(new.preco_unitario * v_quantidade, 2);

  return new;
end;
$function$

definitions.fn_custo_real_ligado(uuid,uuid,uuid):
CREATE OR REPLACE FUNCTION public.fn_custo_real_ligado(p_obra_id uuid, p_tee_id uuid DEFAULT NULL::uuid, p_item_id uuid DEFAULT NULL::uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_table text;
  v_total numeric := 0;
  v_part numeric;
begin
  foreach v_table in array array[
    'lancamentos_materiais',
    'lancamentos_mao_obra',
    'despesas_estaleiro'
  ]
  loop
    if to_regclass('public.' || v_table) is null then
      continue;
    end if;

    execute format(
      'select coalesce(
         sum(public.fn_valor_lancamento_custo(to_jsonb(t))),
         0
       )
       from public.%I t
       where t.obra_id = $1
         and ($2 is null or t.tee_id = $2)
         and ($3 is null or t.item_orcamento_id = $3)',
      v_table
    )
    into v_part
    using p_obra_id, p_tee_id, p_item_id;

    v_total := v_total + coalesce(v_part, 0);
  end loop;

  return v_total;
end;
$function$

definitions.fn_decidir_faturacao_auto(uuid,text):
CREATE OR REPLACE FUNCTION public.fn_decidir_faturacao_auto(p_faturacao_id uuid, p_decisao text)
 RETURNS faturacao
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_faturacao public.faturacao;
begin
  if p_decisao not in ('aprovado', 'recusado') then
    raise exception 'Decisão inválida.';
  end if;

  select * into v_faturacao
  from public.faturacao
  where id = p_faturacao_id
  for update;

  if not found or v_faturacao.estado_aprovacao <> 'pendente' then
    raise exception 'A fatura já não está pendente.';
  end if;

  if not public.fn_pode_editar_obra(v_faturacao.obra_id) then
    raise exception 'Sem permissão para decidir esta fatura.';
  end if;

  update public.faturacao
  set estado_aprovacao = p_decisao,
      estado = case
        when p_decisao = 'aprovado' then 'emitida'
        else 'rascunho'
      end,
      aprovado_por = public.fn_utilizador_atual_id(),
      data_aprovacao = now()
  where id = p_faturacao_id
  returning * into v_faturacao;

  return v_faturacao;
end;
$function$

definitions.fn_sincronizar_estado_fluxo_fatura():
CREATE OR REPLACE FUNCTION public.fn_sincronizar_estado_fluxo_fatura()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.estado_pagamento='pago' then new.estado_fluxo='paga';
  elsif new.estado_aprovacao='aprovado' then new.estado_fluxo='enviada_financeiro';
  elsif new.estado_fluxo is null then new.estado_fluxo='recebida'; end if;
  return new;
end;
$function$

definitions.fn_proteger_evento_validade_viatura():
CREATE OR REPLACE FUNCTION public.fn_proteger_evento_validade_viatura()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rpc boolean;
BEGIN
  v_rpc :=
    COALESCE(
      current_setting('primeline.validade_viatura_rpc', true),
      ''
    ) = 'on';

  IF TG_OP = 'INSERT' THEN
    IF NEW.validade_operacao IS NOT NULL
       AND NOT v_rpc
    THEN
      RAISE EXCEPTION
        'PROTECTED_HISTORY: histórico de validade deve ser criado pela RPC.';
    END IF;

    RETURN NEW;
  END IF;

  IF OLD.validade_operacao IS NOT NULL
     AND NOT v_rpc
  THEN
    RAISE EXCEPTION
      'PROTECTED_HISTORY: eventos de validade não podem ser editados nem apagados.';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$function$

definitions.fn_eliminar_fornecedor_duplicado(uuid):
CREATE OR REPLACE FUNCTION public.fn_eliminar_fornecedor_duplicado(p_fornecedor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_fornecedor public.fornecedores;
  v_referencia record;
  v_total bigint;
  v_bloqueios text[] := array[]::text[];
begin
  if not (public.fn_e_admin() or public.fn_e_administrativo()) then
    raise exception 'SÃ³ o Administrativo ou a GestÃ£o da Plataforma pode eliminar registos duplicados.' using errcode = '42501';
  end if;

  select f.* into v_fornecedor
  from public.fornecedores f
  join public.utilizadores u on u.id = public.fn_utilizador_atual_id()
  where f.id = p_fornecedor_id
    and f.empresa_id = u.empresa_id
    and coalesce(u.ativo, true)
  for update;
  if not found then
    raise exception 'Fornecedor inexistente ou fora da sua empresa.';
  end if;

  -- Qualquer referÃªncia de negÃ³cio bloqueia a eliminaÃ§Ã£o. Apenas as tabelas de
  -- classificaÃ§Ã£o do prÃ³prio diretÃ³rio podem ser limpas com o duplicado.
  for v_referencia in
    select
      c.conrelid::regclass as tabela,
      a.attname as coluna
    from pg_constraint c
    join pg_attribute a
      on a.attrelid = c.conrelid
     and a.attnum = c.conkey[1]
    where c.contype = 'f'
      and c.confrelid = 'public.fornecedores'::regclass
      and array_length(c.conkey, 1) = 1
      and c.conrelid not in (
        'public.fornecedores_zonas'::regclass,
        'public.fornecedores_especialidades'::regclass
      )
  loop
    execute format(
      'select count(*) from %s where %I = $1',
      v_referencia.tabela,
      v_referencia.coluna
    ) into v_total using p_fornecedor_id;
    if v_total > 0 then
      v_bloqueios := array_append(
        v_bloqueios,
        format('%s (%s registo%s)', v_referencia.tabela, v_total, case when v_total = 1 then '' else 's' end)
      );
    end if;
  end loop;

  if cardinality(v_bloqueios) > 0 then
    raise exception 'Este registo nÃ£o pode ser eliminado porque jÃ¡ tem histÃ³rico associado: %. Consolide-o com o registo correto antes de eliminar.',
      array_to_string(v_bloqueios, ', ');
  end if;

  delete from public.fornecedores_zonas where fornecedor_id = p_fornecedor_id;
  delete from public.fornecedores_especialidades where fornecedor_id = p_fornecedor_id;
  delete from public.fornecedores where id = p_fornecedor_id;

  return jsonb_build_object(
    'eliminado', true,
    'fornecedor_id', p_fornecedor_id,
    'nome', v_fornecedor.nome
  );
end;
$function$

definitions.fn_eliminar_proposta_comparativo(uuid):
CREATE OR REPLACE FUNCTION public.fn_eliminar_proposta_comparativo(p_proposta_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_mapa_id uuid;
  v_obra_id uuid;
  v_precos_antes integer;
  v_ajustes_antes integer;
  v_precos_depois integer;
  v_ajustes_depois integer;
begin
  select p.mapa_id, m.obra_id
  into v_mapa_id, v_obra_id
  from public.comparativo_propostas p
  join public.mapas_comparativos m on m.id = p.mapa_id
  where p.id = p_proposta_id
  for update of p;

  if not found then
    raise exception 'Proposta do mapa comparativo não encontrada.'
      using errcode = 'P0002';
  end if;

  if not public.fn_pode_editar_obra(v_obra_id) then
    raise exception 'Sem permissão para eliminar propostas desta obra.'
      using errcode = '42501';
  end if;

  select count(*)
  into v_precos_antes
  from public.comparativo_itens_precos
  where proposta_id = p_proposta_id;

  select count(*)
  into v_ajustes_antes
  from public.comparativo_ajustes
  where proposta_id = p_proposta_id;

  delete from public.comparativo_propostas
  where id = p_proposta_id;

  select count(*)
  into v_precos_depois
  from public.comparativo_itens_precos
  where proposta_id = p_proposta_id;

  select count(*)
  into v_ajustes_depois
  from public.comparativo_ajustes
  where proposta_id = p_proposta_id;

  if v_precos_depois <> 0 or v_ajustes_depois <> 0 then
    raise exception
      'A eliminação foi cancelada: existem preços ou ajustes órfãos para a proposta.';
  end if;

  perform public.fn_atualizar_melhor_preco_comparativo(v_mapa_id);

  return jsonb_build_object(
    'proposta_id', p_proposta_id,
    'precos_eliminados', v_precos_antes,
    'ajustes_eliminados', v_ajustes_antes,
    'precos_restantes', v_precos_depois,
    'ajustes_restantes', v_ajustes_depois
  );
end;
$function$

definitions.fn_importar_mapa_gestao(jsonb,boolean):
CREATE OR REPLACE FUNCTION public.fn_importar_mapa_gestao(p_linhas jsonb, p_confirmar boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_atual public.utilizadores; v_linha jsonb; v_obra public.obras; v_fornecedor public.fornecedores;
  v_colaborador public.colaboradores; v_sub public.subempreitadas; v_categoria text; v_documento text;
  v_entidade text; v_chave text; v_chave_documento text; v_valor numeric; v_criar integer:=0; v_criados integer:=0;
  v_duplicados integer:=0; v_erros jsonb:='[]'::jsonb; v_chaves text[]:=array[]::text[];
  v_chaves_existentes text[]:=array[]::text[]; v_dados jsonb; v_sub_chave text;
  v_sub_chaves text[]:=array[]::text[]; v_sub_historicas jsonb:='[]'::jsonb;
begin
  if not (public.fn_e_admin() or public.fn_e_financeiro()) then raise exception 'Sem permissão para importar o Mapa de Gestão.' using errcode='42501'; end if;
  select * into v_atual from public.utilizadores u where u.id=public.fn_utilizador_atual_id() and coalesce(u.ativo,true);
  if not found then raise exception 'Utilizador autenticado sem perfil ativo.'; end if;
  if jsonb_typeof(p_linhas)<>'array' then raise exception 'Formato de importação inválido.'; end if;

  -- Calcula o universo de duplicados uma única vez. Em ficheiros grandes isto
  -- evita executar o mapa completo novamente por cada linha importada.
  select coalesce(array_agg(lower(concat_ws('|',m.categoria,m.obra_id,
    coalesce(m.documento,m.data_lancamento::text,''),coalesce(m.entidade_nome,''),round(coalesce(m.valor,0),2)))),array[]::text[])
  into v_chaves_existentes
  from public.fn_mapa_gestao_obras() m;

  for v_linha in select value from jsonb_array_elements(p_linhas)
  loop
    v_categoria:=v_linha->>'categoria'; v_documento:=coalesce(v_linha->>'numero_documento',v_linha->>'numero_fatura');
    if regexp_replace(btrim(coalesce(v_linha->>'obra_numero','')), '^0+', '') in ('79','85','127') then
      v_erros:=v_erros||jsonb_build_array(format(
        'Linha %s: Obra %s não aceita importação por este caminho — usar Saldo de Abertura.',
        v_linha->>'linha',coalesce(v_linha->>'obra_numero','—')
      ));
      continue;
    end if;
    select * into v_obra from public.obras o where o.empresa_id=v_atual.empresa_id and o.numero::text=btrim(v_linha->>'obra_numero') limit 1;
    if not found then v_erros:=v_erros||jsonb_build_array(format('Linha %s: obra %s não encontrada.',v_linha->>'linha',coalesce(v_linha->>'obra_numero','—'))); continue; end if;

    if v_categoria='mao_obra' then
      select * into v_colaborador from public.colaboradores c where c.empresa_id=v_atual.empresa_id and lower(btrim(c.nome))=lower(btrim(v_linha->>'colaborador')) limit 1;
      if not found then v_erros:=v_erros||jsonb_build_array(format('Linha %s: colaborador %s não encontrado.',v_linha->>'linha',coalesce(v_linha->>'colaborador','—'))); continue; end if;
      if nullif(v_linha->>'data','') is null or nullif(v_linha->>'horas','') is null or nullif(v_linha->>'valor_hora','') is null then v_erros:=v_erros||jsonb_build_array(format('Linha %s: data, horas e valor/hora são obrigatórios.',v_linha->>'linha')); continue; end if;
      v_entidade:=v_colaborador.nome; v_valor:=(v_linha->>'horas')::numeric*(v_linha->>'valor_hora')::numeric; v_documento:=v_linha->>'data';
    elsif v_categoria='faturacao' then
      if nullif(v_documento,'') is null or nullif(v_linha->>'data_emissao','') is null or nullif(v_linha->>'valor','') is null then v_erros:=v_erros||jsonb_build_array(format('Linha %s: nº fatura, data de emissão e valor são obrigatórios.',v_linha->>'linha')); continue; end if;
      v_entidade:='Cliente'; v_valor:=coalesce(nullif(v_linha->>'valor_recebido','')::numeric,(v_linha->>'valor')::numeric);
    else
      if v_categoria not in ('materiais','estaleiro','subempreitadas') then v_erros:=v_erros||jsonb_build_array(format('Linha %s: categoria inválida.',v_linha->>'linha')); continue; end if;
      v_fornecedor:=null; v_colaborador:=null;
      if v_categoria='estaleiro' and nullif(btrim(v_linha->>'fornecedor'),'') is null and nullif(btrim(v_linha->>'colaborador'),'') is not null then
        select * into v_colaborador from public.colaboradores c where c.empresa_id=v_atual.empresa_id and lower(btrim(c.nome))=lower(btrim(v_linha->>'colaborador')) limit 1;
        if not found then v_erros:=v_erros||jsonb_build_array(format('Linha %s: colaborador %s não encontrado para o reembolso.',v_linha->>'linha',coalesce(v_linha->>'colaborador','—'))); continue; end if;
        v_entidade:=v_colaborador.nome;
      else
        select * into v_fornecedor from public.fornecedores f where f.empresa_id=v_atual.empresa_id and lower(btrim(f.nome))=lower(btrim(v_linha->>'fornecedor')) limit 1;
        if not found then v_erros:=v_erros||jsonb_build_array(format('Linha %s: fornecedor %s não encontrado.',v_linha->>'linha',coalesce(v_linha->>'fornecedor','—'))); continue; end if;
        v_entidade:=v_fornecedor.nome;
      end if;
      if nullif(v_linha->>'valor_total','') is null then v_erros:=v_erros||jsonb_build_array(format('Linha %s: valor total é obrigatório.',v_linha->>'linha')); continue; end if;
      if v_categoria<>'estaleiro' and nullif(v_documento,'') is null then v_erros:=v_erros||jsonb_build_array(format('Linha %s: documento é obrigatório.',v_linha->>'linha')); continue; end if;
      if v_categoria='estaleiro' and nullif(v_documento,'') is null and nullif(v_linha->>'data','') is null then v_erros:=v_erros||jsonb_build_array(format('Linha %s: despesas sem documento exigem data para deduplicação.',v_linha->>'linha')); continue; end if;
      v_valor:=(v_linha->>'valor_total')::numeric;
    end if;

    v_chave_documento:=coalesce(nullif(v_documento,''), nullif(v_linha->>'data',''));
    v_chave:=lower(concat_ws('|',v_categoria,v_obra.id,v_chave_documento,v_entidade,round(v_valor,2)));
    if v_chave=any(v_chaves) or v_chave=any(v_chaves_existentes) then
      v_duplicados:=v_duplicados+1; continue;
    end if;

    -- mgo-periodicidade-v1: mesma validação na simulação e gravação, após deduplicação.
    if v_categoria='mao_obra' then
      v_dados:=jsonb_build_object('erro',public.fn_mgo_validar_periodo_mao_obra(v_linha,v_colaborador.id,v_obra.id));
      if nullif(v_dados->>'erro','') is not null then
        v_erros:=v_erros||jsonb_build_array(v_dados->>'erro'); continue;
      end if;
      if exists(select 1 from jsonb_array_elements(p_linhas) other
        where other->>'categoria'='mao_obra'
          and lower(btrim(other->>'colaborador'))=lower(btrim(v_linha->>'colaborador'))
          and other->>'obra_numero'=v_linha->>'obra_numero'
          and left(other->>'data',7)=left(v_linha->>'data',7)
          and ('mensal' in (other->>'tipo_registo',v_linha->>'tipo_registo'))
          and (
            coalesce(nullif(other->>'tipo_registo',''),'diario')<>coalesce(nullif(v_linha->>'tipo_registo',''),'diario')
            or other->>'data' is distinct from v_linha->>'data'
            or (other->>'horas')::numeric is distinct from (v_linha->>'horas')::numeric
            or (other->>'valor_hora')::numeric is distinct from (v_linha->>'valor_hora')::numeric
          )) then
        v_erros:=v_erros||jsonb_build_array(format('Linha %s: mais de um lançamento ou mistura de diário e mensal para %s na obra/mês.',v_linha->>'linha',v_colaborador.nome)); continue;
      end if;
    end if;
    v_chaves:=array_append(v_chaves,v_chave); v_criar:=v_criar+1;

    if v_categoria='subempreitadas' then
      v_sub:=null;
      select * into v_sub
      from public.subempreitadas s
      where s.obra_id=v_obra.id and s.fornecedor_id=v_fornecedor.id
      order by s.criado_em desc
      limit 1;

      if not found then
        v_sub_chave:=v_obra.id::text||'|'||v_fornecedor.id::text;
        if not (v_sub_chave=any(v_sub_chaves)) then
          v_sub_chaves:=array_append(v_sub_chaves,v_sub_chave);
          v_sub_historicas:=v_sub_historicas||jsonb_build_array(
            format('Obra %s · %s',v_obra.numero,v_fornecedor.nome)
          );
        end if;
      end if;
    end if;

    if not p_confirmar then continue; end if;

    if v_categoria='mao_obra' then
      v_dados:=jsonb_build_object('empresa_id',v_atual.empresa_id,'obra_id',v_obra.id,'colaborador_id',v_colaborador.id,'data',v_linha->>'data','horas',v_linha->>'horas','valor_hora',v_linha->>'valor_hora','criado_por',v_atual.id);
      v_dados:=v_dados||jsonb_build_object('tipo_registo',coalesce(nullif(v_linha->>'tipo_registo',''),'diario'),
        'mes_referencia',nullif(v_linha->>'mes_referencia',''));
      perform public.fn_mgo_inserir_json_compativel('public.lancamentos_mao_obra'::regclass,v_dados);
    elsif v_categoria='faturacao' then
      v_dados:=jsonb_build_object('empresa_id',v_atual.empresa_id,'obra_id',v_obra.id,'numero_fatura',v_documento,'data_emissao_fatura',v_linha->>'data_emissao','valor',v_linha->>'valor','data_recebimento',v_linha->>'data_recebimento','valor_recebido',v_linha->>'valor_recebido','estado',coalesce(nullif(v_linha->>'estado',''),'recebida'));
      perform public.fn_mgo_inserir_json_compativel('public.faturacao'::regclass,v_dados);
    elsif v_categoria='subempreitadas' then
      if v_sub.id is null then
        insert into public.subempreitadas (
          obra_id, fornecedor_id, especialidade, valor_adjudicado, estado
        ) values (
          v_obra.id, v_fornecedor.id, 'Por classificar · Importação histórica', 0, 'adjudicado'
        ) returning * into v_sub;

        insert into public.alertas (
          empresa_id, obra_id, tipo, entidade_tipo, entidade_id, titulo,
          descricao, data_evento_referencia, antecedencia_dias, data_gatilho,
          destinatario_role, estado
        )
        select
          v_atual.empresa_id, v_obra.id, 'subempreitada_historica_por_validar',
          'subempreitadas', v_sub.id, 'Subempreitada histórica por validar',
          'Foi importado um lançamento de '||v_fornecedor.nome||' na Obra '||v_obra.numero||
            ' sem subempreitada prévia. Regularize a especialidade e o valor adjudicado.',
          coalesce(nullif(v_linha->>'data','')::date,current_date), 0, current_date,
          'diretor_obra', 'pendente'
        where not exists (
          select 1 from public.alertas a
          where a.tipo='subempreitada_historica_por_validar'
            and a.entidade_tipo='subempreitadas'
            and a.entidade_id=v_sub.id
            and a.estado='pendente'
        );
      end if;
      v_dados:=jsonb_build_object('empresa_id',v_atual.empresa_id,'subempreitada_id',v_sub.id,'numero_doc',v_documento,'documento',v_documento,'data',v_linha->>'data','data_pagamento',v_linha->>'data_pagamento','valor',v_valor,'valor_total',v_valor,'estado_aprovacao','aprovado','estado_pagamento','pago','criado_por',v_atual.id);
      perform public.fn_mgo_inserir_json_compativel('public.pagamentos_subempreitada'::regclass,v_dados);
    else
      v_dados:=jsonb_build_object('empresa_id',v_atual.empresa_id,'obra_id',v_obra.id,'fornecedor_id',v_fornecedor.id,'colaborador_id',v_colaborador.id,'numero_doc',v_documento,'documento',v_documento,'data',v_linha->>'data','fornecedor',v_fornecedor.nome,'designacao',v_linha->>'designacao','descricao',v_linha->>'designacao','unidade',v_linha->>'unidade','quantidade',v_linha->>'quantidade','valor_unitario',v_linha->>'valor_unitario','valor_total',v_valor,'valor',v_valor,'data_pagamento',v_linha->>'data_pagamento','estado_aprovacao','aprovado','estado_pagamento','pago','criado_por',v_atual.id);
      perform public.fn_mgo_inserir_json_compativel(case when v_categoria='materiais' then 'public.lancamentos_materiais'::regclass else 'public.despesas_estaleiro'::regclass end,v_dados);
    end if;
    v_criados:=v_criados+1;
  end loop;
  if p_confirmar and jsonb_array_length(v_erros)>0 then raise exception 'Importação cancelada: %',v_erros::text; end if;
  return jsonb_build_object(
    'linhas',jsonb_array_length(p_linhas),
    'criar',v_criar,
    'criados',v_criados,
    'duplicados',v_duplicados,
    'erros',v_erros,
    'subempreitadas_historicas',v_sub_historicas
  );
end;$function$

definitions.fn_registar_evento_financeiro_fatura():
CREATE OR REPLACE FUNCTION public.fn_registar_evento_financeiro_fatura()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_table_name = 'faturas_anexos' and tg_op = 'INSERT' then
    insert into public.faturas_eventos (fatura_id, tipo, observacao, utilizador_id)
    values (new.fatura_id, 'anexo_adicionado', new.nome_arquivo, public.fn_utilizador_atual_id());
    return new;
  end if;

  if old.estado_pagamento is distinct from new.estado_pagamento then
    if new.estado_pagamento = 'pago' then
      insert into public.faturas_eventos (fatura_id, tipo, utilizador_id)
      values (new.id, 'paga', public.fn_utilizador_atual_id());
    elsif old.estado_pagamento = 'pago' and new.estado_pagamento = 'por_pagar' then
      insert into public.faturas_eventos (fatura_id, tipo, utilizador_id)
      values (new.id, 'pagamento_revertido', public.fn_utilizador_atual_id());
    end if;
  end if;

  if old.estado_fluxo is distinct from new.estado_fluxo
     and new.estado_fluxo = 'devolvida_administrativo' then
    insert into public.faturas_eventos (fatura_id, tipo, observacao, utilizador_id)
    values (new.id, 'devolvida_administrativo', new.observacao_devolucao, public.fn_utilizador_atual_id());
  elsif old.estado_fluxo = 'devolvida_administrativo'
        and new.estado_fluxo = 'recebida' then
    insert into public.faturas_eventos (fatura_id, tipo, utilizador_id)
    values (new.id, 'corrigida_reenviada', public.fn_utilizador_atual_id());
  elsif old.estado_aprovacao = 'aprovado'
        and new.estado_aprovacao = 'pendente'
        and nullif(btrim(new.observacao_devolucao), '') is not null then
    insert into public.faturas_eventos (fatura_id, tipo, observacao, utilizador_id)
    values (new.id, 'devolvida', new.observacao_devolucao, public.fn_utilizador_atual_id());
  end if;
  return new;
end;
$function$

definitions.fn_apagar_lancamento_gestao_obras(uuid):
