$function$

definitions.fn_confirmar_custo_real_pl(uuid,numeric):
CREATE OR REPLACE FUNCTION public.fn_confirmar_custo_real_pl(p_planeamento_item_id uuid, p_valor_real numeric DEFAULT NULL::numeric)
 RETURNS planeamento_itens
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_item public.planeamento_itens; v_obra_id uuid; v_utilizador_id uuid; v_valor numeric;
begin
  select pi.* into v_item from public.planeamento_itens pi
  where pi.id=p_planeamento_item_id for update;
  if not found then raise exception 'Tarefa/pacote PL não encontrado.'; end if;
  select f.obra_id into v_obra_id from public.fases f where f.id=v_item.fase_id;
  if not public.fn_pode_editar_obra(v_obra_id) then
    raise exception 'Só a equipa técnica responsável pode confirmar o custo PL.' using errcode='42501';
  end if;
  if coalesce(v_item.executado_por,'PL') not in ('PL','misto') then
    raise exception 'Esta tarefa não possui uma componente executada pela Primeline.';
  end if;
  if v_item.estado<>'concluido' then
    raise exception 'A componente PL só pode passar a Custo Real quando a tarefa estiver concluída.';
  end if;
  v_valor:=coalesce(p_valor_real,v_item.valor_orca_pl,v_item.valor_estimado);
  if v_valor is null or v_valor<0 then raise exception 'Indique um Valor Real PL válido.'; end if;
  select id into v_utilizador_id from public.utilizadores where auth_user_id=auth.uid() limit 1;
  update public.planeamento_itens set valor_real_pl=v_valor,custo_pl_confirmado=true,
    custo_pl_confirmado_por=v_utilizador_id,custo_pl_confirmado_em=now(),custo_estado='concluido'
  where id=p_planeamento_item_id returning * into v_item;
  return v_item;
end;$function$

definitions.fn_definir_zonas_fornecedor(uuid,text[]):
CREATE OR REPLACE FUNCTION public.fn_definir_zonas_fornecedor(p_fornecedor_id uuid, p_zonas text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_empresa_id uuid;
  v_zona text;
  v_zonas text[] := coalesce(p_zonas, '{}'::text[]);
begin
  if not (public.fn_e_admin() or public.fn_e_administrativo()) then
    raise exception 'SÃ³ o Administrativo ou a GestÃ£o da Plataforma pode classificar zonas.' using errcode = '42501';
  end if;

  select f.empresa_id into v_empresa_id
  from public.fornecedores f
  join public.utilizadores u on u.id = public.fn_utilizador_atual_id()
  where f.id = p_fornecedor_id
    and f.empresa_id = u.empresa_id
    and coalesce(u.ativo, true)
  for update of f;

  if not found then
    raise exception 'Fornecedor inexistente ou fora da sua empresa.';
  end if;

  if exists (
    select 1 from unnest(v_zonas) zona
    where zona not in ('lisboa_cascais', 'algarve')
  ) then
    raise exception 'Zona invÃ¡lida. Use apenas Lisboa/Cascais ou Algarve.';
  end if;

  delete from public.fornecedores_zonas
  where fornecedor_id = p_fornecedor_id
    and not (zona = any(v_zonas));

  foreach v_zona in array v_zonas loop
    insert into public.fornecedores_zonas (fornecedor_id, zona, criado_por)
    values (p_fornecedor_id, v_zona, public.fn_utilizador_atual_id())
    on conflict (fornecedor_id, zona) do nothing;
  end loop;

  return jsonb_build_object(
    'fornecedor_id', p_fornecedor_id,
    'zonas', coalesce((
      select jsonb_agg(fz.zona order by fz.zona)
      from public.fornecedores_zonas fz
      where fz.fornecedor_id = p_fornecedor_id
    ), '[]'::jsonb)
  );
end;
$function$

definitions.fn_guardar_integridade_orcamento_fonte():
CREATE OR REPLACE FUNCTION public.fn_guardar_integridade_orcamento_fonte()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_versao public.orcamento_versoes%ROWTYPE;
  v_obra_documento uuid;
  v_versao_id uuid;
BEGIN
  IF TG_OP = 'UPDATE' AND ROW(NEW.id, NEW.versao_id) IS DISTINCT FROM ROW(OLD.id, OLD.versao_id) THEN
    RAISE EXCEPTION 'Identidade e versão da fonte são imutáveis.' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'DELETE' THEN v_versao_id := OLD.versao_id;
  ELSE v_versao_id := NEW.versao_id; END IF;
  -- Serializa mutações de fontes com a validação da respetiva versão.
  SELECT * INTO v_versao FROM public.orcamento_versoes WHERE id = v_versao_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Versão da fonte inexistente.' USING ERRCODE = '23503';
  END IF;
  IF v_versao.estado_validacao = 'validada' THEN
    RAISE EXCEPTION 'Fontes de versão validada são imutáveis.' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  IF NEW.documento_obra_id IS NOT NULL THEN
    SELECT obra_id INTO v_obra_documento FROM public.documentos_obra
      WHERE id = NEW.documento_obra_id FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Documento inexistente.' USING ERRCODE = '23503';
    END IF;
    IF v_obra_documento IS DISTINCT FROM v_versao.obra_id THEN
      RAISE EXCEPTION 'Documento pertence a outra obra.' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

definitions.fn_trigger_alerta_limite_subempreitada():
