definitions.fn_validar_justificacao_ponto(uuid,text):
CREATE OR REPLACE FUNCTION public.fn_validar_justificacao_ponto(p_ponto_id uuid, p_decisao text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
