definitions.fn_atualizar_venda_contrato_via_tee(uuid:
CREATE OR REPLACE FUNCTION public.fn_atualizar_venda_contrato_via_tee(p_tee_id uuid)
 RETURNS contratos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_obra_id uuid; v_row public.contratos%rowtype;
begin
  select obra_id into v_obra_id from public.alteracoes_tee where id=p_tee_id and estado_aprovacao_cliente='aprovado';
  if not found then raise exception 'TEE formal aprovado não encontrado.'; end if;
  if not public.fn_e_diretor_obra(v_obra_id) then raise exception 'Operação reservada ao Diretor de Obra ou Gerência.' using errcode='42501'; end if;
  perform set_config('primeline.alteracao_via_tee','on',true);
  update public.contratos c set venda_contratual_efetiva=coalesce(c.venda_contratual_inicial,0)+
    coalesce((select sum(t.valor) from public.alteracoes_tee t where t.obra_id=v_obra_id and t.estado_aprovacao_cliente='aprovado'),0),atualizado_em=now()
  where c.obra_id=v_obra_id returning * into v_row;
  return v_row;
end;
$function$

definitions.fn_guardar_integridade_orcamento_versao(:
CREATE OR REPLACE FUNCTION public.fn_guardar_integridade_orcamento_versao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_anterior public.orcamento_versoes%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    IF OLD.estado_validacao = 'validada' THEN
      RAISE EXCEPTION 'Versão validada é imutável; crie uma revisão.' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    IF ROW(NEW.id, NEW.obra_id, NEW.numero_versao, NEW.versao_anterior_id)
      IS DISTINCT FROM ROW(OLD.id, OLD.obra_id, OLD.numero_versao, OLD.versao_anterior_id) THEN
      RAISE EXCEPTION 'Identidade e linhagem da versão são imutáveis.' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF NEW.versao_anterior_id IS NOT NULL THEN
    SELECT * INTO v_anterior FROM public.orcamento_versoes
      WHERE id = NEW.versao_anterior_id FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Versão anterior inexistente.' USING ERRCODE = '23503';
    END IF;
    IF v_anterior.obra_id <> NEW.obra_id OR v_anterior.numero_versao >= NEW.numero_versao THEN
      RAISE EXCEPTION 'Versão anterior deve ser da mesma obra e ter número menor.' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF NEW.estado_validacao = 'validada' THEN
    IF NOT EXISTS (SELECT 1 FROM public.orcamento_versoes_fontes WHERE versao_id = NEW.id) THEN
      RAISE EXCEPTION 'Validação exige pelo menos uma fonte documental.' USING ERRCODE = '23514';
    END IF;
    -- Revalidar a estrutura, mesmo se constraints tiverem sido removidas antes.
    IF EXISTS (
      SELECT 1 FROM public.orcamento_versoes_fontes f WHERE f.versao_id = NEW.id
        AND (f.id IS NOT NULL AND btrim(f.papel_fonte) <> ''
          AND btrim(f.nome_original) <> '' AND btrim(f.bucket) <> ''
          AND btrim(f.object_key) <> '' AND f.sha256 ~ '^[0-9a-f]{64}$'
          AND (f.tamanho_bytes IS NULL OR f.tamanho_bytes >= 0)
          AND f.associado_em IS NOT NULL) IS NOT TRUE
    ) THEN
      RAISE EXCEPTION 'Fonte documental estruturalmente inválida.' USING ERRCODE = '23514';
    END IF;
    -- Contrato: SHA-256 dos bytes UTF-8 de manifesto::text emitido pelo PostgreSQL.
    -- Não é canonicalização JSON interoperável; não normaliza escalas numéricas.
    IF NEW.manifesto_hash IS DISTINCT FROM
      pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(NEW.manifesto::text, 'UTF8')), 'hex') THEN
      RAISE EXCEPTION 'Hash não corresponde ao manifesto serializado pelo PostgreSQL.' USING ERRCODE = '23514';
    END IF;
    -- Revalidar referências documentais antes de congelar a versão.
    PERFORM d.id FROM public.documentos_obra d
      JOIN public.orcamento_versoes_fontes f ON f.documento_obra_id = d.id
      WHERE f.versao_id = NEW.id FOR SHARE OF d;
    IF EXISTS (
      SELECT 1 FROM public.orcamento_versoes_fontes f
      JOIN public.documentos_obra d ON d.id = f.documento_obra_id
      WHERE f.versao_id = NEW.id AND d.obra_id IS DISTINCT FROM NEW.obra_id
    ) THEN
      RAISE EXCEPTION 'Documento de outra obra na versão.' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

definitions.fn_preparar_destinatario_alerta_viatura(:
CREATE OR REPLACE FUNCTION public.fn_preparar_destinatario_alerta_viatura()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_colaborador_id uuid;
  v_utilizador_id uuid;
  v_ciclo_id uuid;
BEGIN
  IF NEW.entidade_tipo IS DISTINCT FROM 'viaturas'
     OR NEW.tipo NOT IN ('seguro_viatura', 'inspecao_viatura')
  THEN
    RETURN NEW;
  END IF;

  SELECT
    v.colaborador_atribuido_id,
    CASE
      WHEN NEW.tipo = 'seguro_viatura'
        THEN v.seguro_ciclo_id
      ELSE v.inspecao_ciclo_id
    END
  INTO
    v_colaborador_id,
    v_ciclo_id
  FROM public.viaturas v
  WHERE v.id = NEW.entidade_id;

  IF v_colaborador_id IS NOT NULL THEN
    SELECT c.utilizador_id
    INTO v_utilizador_id
    FROM public.colaboradores c
    WHERE c.id = v_colaborador_id;
  ELSE
    v_utilizador_id := NULL;
  END IF;

  NEW.destinatario_role := 'administrativo';
  NEW.destinatario_colaborador_id := v_colaborador_id;
  NEW.destinatario_utilizador_id := v_utilizador_id;
  NEW.ocorrencia_chave := v_ciclo_id;

  RETURN NEW;
END;
$function$

definitions.fn_quadro_operar(text,jsonb,boolean,text:
CREATE OR REPLACE FUNCTION public.fn_quadro_operar(p_acao text, p_dados jsonb, p_confirmar boolean DEFAULT false, p_versao text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  u public.utilizadores;
  c public.colaboradores;
  src public.quadro_pessoal_alocacao;
  dest uuid;
  person uuid;
  day date;
  period text;
  kind text;
  description text;
  sid uuid;
  rows_before jsonb;
  v_version text;
  n integer;
  result_id uuid;
  manage boolean;
  result jsonb;
BEGIN
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;
 PERFORM pg_advisory_xact_lock(61001,1);

  SELECT *
  INTO u
  FROM public.utilizadores
  WHERE id = public.fn_utilizador_atual_id()
    AND ativo IS TRUE;

  IF u.id IS NULL THEN
    RAISE EXCEPTION 'Sessão sem utilizador ativo.'
    USING ERRCODE = '42501';
  END IF;

  manage := public.fn_pode_gerir_quadro(NULL);

  IF p_acao IS NULL
     OR p_acao NOT IN (
       'adicionar',
       'mover',
       'remover',
       'corrigir',
       'minha_obra'
     )
  THEN
    RAISE EXCEPTION 'Ação inválida.';
  END IF;

  IF NOT manage
     AND (
       u.funcao <> 'encarregado'
       OR p_acao <> 'minha_obra'
     )
  THEN
    RAISE EXCEPTION 'Sem autorização para editar o Quadro Geral.'
    USING ERRCODE = '42501';
  END IF;

  IF p_acao IN ('mover', 'remover', 'corrigir') THEN

    sid := nullif(p_dados->>'id', '')::uuid;

    SELECT *
    INTO src
    FROM public.quadro_pessoal_alocacao
    WHERE id = sid;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Alocação não encontrada; recarregue.';
    END IF;

    person := src.colaborador_id;

  ELSE

    person := (p_dados->>'colaborador_id')::uuid;

  END IF;

  SELECT *
  INTO c
  FROM public.colaboradores
  WHERE id = person
    AND empresa_id = u.empresa_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Colaborador não autorizado.'
    USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(person::text, 0)
  );

  IF sid IS NOT NULL THEN

    SELECT *
    INTO src
    FROM public.quadro_pessoal_alocacao
    WHERE id = sid
    FOR UPDATE;

    IF NOT FOUND
       OR src.colaborador_id <> person
    THEN
      RAISE EXCEPTION 'Origem alterada; recarregue.';
    END IF;

  END IF;

  day := coalesce(
    (p_dados->>'data')::date,
    src.data
  );

  period := coalesce(
    p_dados->>'periodo',
    src.periodo
  );

  dest := nullif(p_dados->>'obra_id', '')::uuid;

  kind := coalesce(
    p_dados->>'tipo_alocacao',
    'obra'
  );

  description := nullif(
    btrim(p_dados->>'descricao_livre'),
    ''
  );

  IF p_acao = 'remover' THEN
    dest := src.obra_id;
    kind := src.tipo_alocacao;
    description := src.descricao_livre;
  END IF;

  IF day IS NULL
     OR period IS NULL
     OR period NOT IN ('manha', 'tarde', 'dia_inteiro')
  THEN
    RAISE EXCEPTION 'Indique data e período válidos.';
  END IF;

  IF p_acao <> 'remover'
     AND (
       (
         c.data_saida IS NOT NULL
         AND c.data_saida <= day
       )
       OR c.data_admissao > day
     )
  THEN
    RAISE EXCEPTION 'Colaborador indisponível nesta data.';
  END IF;

  IF kind NOT IN (
       'obra',
       'garantia',
       'pontual',
       'escritorio'
     )
     OR (
       kind = 'obra'
       AND dest IS NULL
     )
     OR (
       kind <> 'obra'
       AND (
         dest IS NOT NULL
         OR description IS NULL
       )
     )
  THEN
    RAISE EXCEPTION 'Destino inválido.';
  END IF;

  IF kind = 'obra' THEN
    description := NULL;
  END IF;

  IF dest IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.obras o
       WHERE o.id = dest
         AND o.empresa_id = u.empresa_id
     )
  THEN
    RAISE EXCEPTION 'Destino de outra empresa.'
    USING ERRCODE = '42501';
  END IF;

  IF p_acao = 'minha_obra'
     AND (
       kind <> 'obra'
       OR NOT public.fn_quadro_minha_obra(dest)
     )
  THEN
    RAISE EXCEPTION
      'Só pode adicionar à obra em que é Encarregado.'
    USING ERRCODE = '42501';
  END IF;

  IF p_acao <> 'remover'
     AND EXISTS (
       SELECT 1
       FROM public.ausencias a
       WHERE a.colaborador_id = person
         AND a.data = day
     )
  THEN
    RAISE EXCEPTION
      'Este colaborador está de férias/ausente nesta data.';
  END IF;

  SELECT coalesce(
           jsonb_agg(
             to_jsonb(q)
             ORDER BY q.id
           ),
           '[]'::jsonb
         )
  INTO rows_before
  FROM public.quadro_pessoal_alocacao q
  WHERE q.colaborador_id = person
    AND q.data = day
    AND (
      q.periodo = period
      OR q.periodo = 'dia_inteiro'
      OR period = 'dia_inteiro'
    );

  IF p_acao = 'minha_obra' THEN

    IF EXISTS (
      SELECT 1
      FROM public.quadro_pessoal_alocacao q
      WHERE q.colaborador_id = person
        AND q.data = day
        AND q.periodo = period
        AND q.obra_id = dest
        AND q.tipo_alocacao = 'obra'
        AND q.descricao_livre IS NULL
    )
    THEN
      RAISE EXCEPTION
        'Destino já existente: nenhuma origem foi removida.';
    END IF;

    n := jsonb_array_length(rows_before);

    IF n > 1 THEN
      RAISE EXCEPTION
        'Várias origens: peça a resolução ao ADM/Gestão. Nada foi alterado.';
    END IF;

    IF n = 1 THEN

      SELECT *
      INTO src
      FROM jsonb_populate_record(
        NULL::public.quadro_pessoal_alocacao,
        rows_before->0
      );

      IF src.periodo <> period THEN
        RAISE EXCEPTION
          'Sobreposição parcial: peça a resolução ao ADM/Gestão.';
      END IF;

      sid := src.id;

    END IF;

  END IF;

  IF p_acao <> 'remover'
     AND EXISTS (
       SELECT 1
       FROM public.quadro_pessoal_alocacao q
       WHERE q.colaborador_id = person
         AND q.data = day
         AND q.periodo = period
         AND q.obra_id IS NOT DISTINCT FROM dest
         AND q.tipo_alocacao = kind
         AND q.descricao_livre IS NOT DISTINCT FROM description
         AND q.id IS DISTINCT FROM sid
     )
  THEN
    RAISE EXCEPTION 'Alocação idêntica já existente.'
    USING ERRCODE = '23505';
  END IF;

  v_version := md5(
    jsonb_build_object(
      'linhas', rows_before,
      'origem', to_jsonb(src),
      'dados', p_dados,
      'acao', p_acao
    )::text
  );

  result := jsonb_build_object(
    'versao', v_version,
    'colaborador', c.nome,
    'origem_id', sid,
    'obra_origem_id', src.obra_id,
    'obra_destino_id', dest,
    'data', day,
    'periodo', period,
    'acao',
      CASE
        WHEN p_acao = 'minha_obra'
          THEN CASE
                 WHEN sid IS NULL THEN 'adicionar'
                 ELSE 'mover'
               END
        ELSE p_acao
      END
  );

  IF NOT p_confirmar THEN
    RETURN result
      || jsonb_build_object(
           'estado',
           'PREVISUALIZACAO'
         );
  END IF;

  IF p_versao IS DISTINCT FROM v_version THEN
    RAISE EXCEPTION
      'Pré-visualização desatualizada. Consulte novamente.';
  END IF;

  IF NOT manage THEN

    INSERT INTO public.quadro_pessoal_rpc_permit
    VALUES (
      txid_current(),
      u.id,
      person,
      sid,
      dest,
      day,
      period
    );

  END IF;

  IF p_acao = 'remover' THEN

    DELETE FROM public.quadro_pessoal_alocacao
    WHERE id = sid;

    result_id := sid;

  ELSIF sid IS NOT NULL THEN

    UPDATE public.quadro_pessoal_alocacao
    SET
      obra_id = dest,
      data = day,
      periodo = period,
      semana_inicio =
        date_trunc(
          'week',
          day::timestamp
        )::date,
      tipo_alocacao = kind,
      descricao_livre = description
    WHERE id = sid
    RETURNING id INTO result_id;

  ELSE

    INSERT INTO public.quadro_pessoal_alocacao (
      colaborador_id,
      obra_id,
      data,
      periodo,
      semana_inicio,
      tipo_alocacao,
      descricao_livre,
      criado_por
    )
    VALUES (
      person,
      dest,
      day,
      period,
      date_trunc(
        'week',
        day::timestamp
      )::date,
      kind,
      description,
      u.id
    )
    RETURNING id INTO result_id;

  END IF;

  DELETE FROM public.quadro_pessoal_rpc_permit
  WHERE transacao = txid_current()
    AND utilizador_id = u.id;

  RETURN result
    || jsonb_build_object(
         'estado',
         'GUARDADO',
         'alocacao_id',
         result_id
       );

END
$function$

definitions.fn_validar_vinculo_fatura_subempreitada(:
CREATE OR REPLACE FUNCTION public.fn_validar_vinculo_fatura_subempreitada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.tipo_origem = 'subempreitada' then
