definitions.fn_criar_fornecedor_comparativo(uuid,tex:
CREATE OR REPLACE FUNCTION public.fn_criar_fornecedor_comparativo(p_mapa_id uuid, p_nome text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_obra_id uuid; v_empresa_id uuid; v_nome text; v_chave text; v_fornecedor public.fornecedores; v_ja_existia boolean := false;
begin
  v_nome := regexp_replace(btrim(coalesce(p_nome,'')), '\s+', ' ', 'g');
  if length(v_nome) < 2 then raise exception 'Indique o nome do fornecedor.' using errcode='23514'; end if;
  v_chave := lower(regexp_replace(regexp_replace(v_nome,'\y(unipessoal|unip|lda|sa|ltda)\y\.?','','gi'),'[^[:alnum:]]+','','g'));

  select m.obra_id,o.empresa_id into v_obra_id,v_empresa_id
  from public.mapas_comparativos m join public.obras o on o.id=m.obra_id where m.id=p_mapa_id;
  if v_obra_id is null then raise exception 'Mapa comparativo não encontrado.' using errcode='P0002'; end if;
  if not public.fn_pode_editar_obra(v_obra_id) then
    raise exception 'Sem permissão para criar fornecedores nesta obra.' using errcode='42501';
  end if;

  select * into v_fornecedor from public.fornecedores
  where empresa_id=v_empresa_id
    and lower(regexp_replace(regexp_replace(nome,'\y(unipessoal|unip|lda|sa|ltda)\y\.?','','gi'),'[^[:alnum:]]+','','g'))=v_chave
  order by id limit 1;
  if found then
    v_ja_existia := true;
  else
    insert into public.fornecedores(empresa_id,nome,tipo_entidade,estado_confianca)
    values(v_empresa_id,v_nome,'subempreiteiro','nao_avaliado') returning * into v_fornecedor;
  end if;

  return jsonb_build_object('id',v_fornecedor.id,'nome',v_fornecedor.nome,
    'tipo_entidade',v_fornecedor.tipo_entidade,'estado_confianca',v_fornecedor.estado_confianca,
    'ja_existia',v_ja_existia);
end $function$

definitions.fn_proteger_historico_atribuicao_viatura:
CREATE OR REPLACE FUNCTION public.fn_proteger_historico_atribuicao_viatura()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'PROTECTED_HISTORY: histórico de atribuições é imutável.' USING ERRCODE = '42501';
  END IF;
  IF coalesce(current_setting('primeline.atribuicao_viatura_rpc', true), '') <> 'on'
     OR current_user <> (
       SELECT pg_get_userbyid(proowner) FROM pg_proc
       WHERE oid = 'public.fn_alterar_responsavel_viatura(integer,uuid,uuid,integer,uuid,text)'::regprocedure
     ) THEN
    RAISE EXCEPTION 'PROTECTED_HISTORY: histórico deve ser criado pela RPC.' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

definitions.fn_criar_alerta_validade_viatura(uuid,te:
CREATE OR REPLACE FUNCTION public.fn_criar_alerta_validade_viatura(p_viatura_id uuid, p_tipo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v public.viaturas%rowtype;
  v_data date;
  v_tipo_alerta text;
  v_titulo text;
  v_texto text;
  v_id uuid;
BEGIN
  IF p_tipo NOT IN ('seguro', 'inspecao') THEN
    RAISE EXCEPTION
      'VALIDATION_FAILED: tipo inválido.';
  END IF;

  SELECT *
  INTO v
  FROM public.viaturas
  WHERE id = p_viatura_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'VALIDATION_FAILED: viatura não encontrada.';
  END IF;

  IF p_tipo = 'seguro' THEN
    v_data := v.seguro_data;
    v_tipo_alerta := 'seguro_viatura';
    v_titulo := 'Seguro da viatura a vencer';
    v_texto := 'seguro em ';
  ELSE
    v_data := v.data_inspecao_proxima;
    v_tipo_alerta := 'inspecao_viatura';
    v_titulo := 'Inspeção da viatura a vencer';
    v_texto := 'inspeção em ';
  END IF;

  IF v_data IS NULL OR v_data - 15 > current_date THEN
    RETURN jsonb_build_object(
      'created', false,
      'reason', 'fora_do_periodo'
    );
  END IF;

  INSERT INTO public.alertas (
    empresa_id,
    tipo,
    entidade_tipo,
    entidade_id,
    titulo,
    descricao,
    data_evento_referencia,
    antecedencia_dias,
    data_gatilho,
    destinatario_role,
    estado
  )
  VALUES (
    v.empresa_id,
    v_tipo_alerta,
    'viaturas',
    v.id,
    v_titulo,
    concat_ws(
      ' · ',
      nullif(v.marca_modelo, ''),
      nullif(v.matricula, ''),
      v_texto || to_char(v_data, 'DD/MM/YYYY')
    ),
    v_data,
    15,
    v_data - 15,
    'administrativo',
    'pendente'
  )
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'created', v_id IS NOT NULL,
    'alert_id', v_id
  );
END;
$function$

definitions.fn_impedir_saida_colaborador_com_viatura:
CREATE OR REPLACE FUNCTION public.fn_impedir_saida_colaborador_com_viaturas()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_quantidade bigint;
BEGIN
  IF OLD.data_saida IS NOT NULL OR NEW.data_saida IS NULL THEN
    RETURN NEW;
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'STALE_REVISION: repita a saída em READ COMMITTED para validar atribuições atuais.'
      USING ERRCODE = '40001';
  END IF;
  SELECT count(*) INTO v_quantidade FROM public.viaturas
    WHERE colaborador_atribuido_id = OLD.id;
  IF v_quantidade > 0 THEN
    RAISE EXCEPTION 'VEHICLE_ASSIGNMENT_PENDING: o colaborador possui % viatura(s) atribuída(s); é necessário primeiro reatribuir ou deixar "Sem atribuição" pela RPC de Viaturas.', v_quantidade
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

definitions.fn_validar_colaborador_utilizador_empres:
CREATE OR REPLACE FUNCTION public.fn_validar_colaborador_utilizador_empresa()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_empresa uuid;
BEGIN
  IF NEW.utilizador_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT empresa_id
  INTO v_empresa
  FROM public.utilizadores
  WHERE id = NEW.utilizador_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'VALIDATION_FAILED: utilizador não encontrado.';
  END IF;

  IF v_empresa IS DISTINCT FROM NEW.empresa_id THEN
    RAISE EXCEPTION
      'VALIDATION_FAILED: colaborador e utilizador pertencem a empresas diferentes.';
  END IF;

  RETURN NEW;
END;
$function$

definitions.fn_verificar_primeiras_consultas_medicin:
CREATE OR REPLACE FUNCTION public.fn_verificar_primeiras_consultas_medicina()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before bigint; v_after bigint;
BEGIN
 SELECT count(*) INTO v_before FROM public.alertas WHERE tipo='primeira_consulta_medicina';
 PERFORM public.fn_medicina_reconciliar_alertas(c.id) FROM public.colaboradores c ORDER BY c.id;
 SELECT count(*) INTO v_after FROM public.alertas WHERE tipo='primeira_consulta_medicina';
 RETURN greatest(0,v_after-v_before)::integer;
END $function$

definitions.fn_vincular_fatura_subempreitada(uuid,uu:
CREATE OR REPLACE FUNCTION public.fn_vincular_fatura_subempreitada(p_fatura_id uuid, p_subempreitada_id uuid)
 RETURNS faturas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_fatura public.faturas;
begin
  select * into v_fatura
  from public.faturas
  where id = p_fatura_id
  for update;

  if not found then
    raise exception 'A fatura selecionada nÃ£o existe.';
  end if;
  if v_fatura.tipo_origem <> 'subempreitada' then
    raise exception 'SÃ³ as faturas de subempreitada podem ser vinculadas a um trabalho.';
  end if;
  if v_fatura.estado_fluxo not in ('recebida', 'em_validacao') then
    raise exception 'O vÃ­nculo sÃ³ pode ser alterado antes da aprovaÃ§Ã£o tÃ©cnica.';
  end if;
  if not (public.fn_pode_editar_obra(v_fatura.obra_id) or public.fn_e_admin()) then
    raise exception 'SÃ³ a equipa tÃ©cnica responsÃ¡vel pela obra pode confirmar este vÃ­nculo.' using errcode = '42501';
  end if;
  if p_subempreitada_id is not null and not exists (
    select 1
    from public.subempreitadas s
    where s.id = p_subempreitada_id
      and s.obra_id = v_fatura.obra_id
      and s.fornecedor_id = v_fatura.fornecedor_id
  ) then
    raise exception 'O trabalho selecionado nÃ£o pertence simultaneamente a esta obra e a este fornecedor.';
  end if;

  update public.faturas
  set subempreitada_id = p_subempreitada_id
  where id = p_fatura_id
  returning * into v_fatura;

  return v_fatura;
end;
$function$

definitions.fn_confirmar_compromisso_subempreitada(u:
CREATE OR REPLACE FUNCTION public.fn_confirmar_compromisso_subempreitada(p_planeamento_item_id uuid)
 RETURNS planeamento_itens
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_item public.planeamento_itens;
  v_obra_id uuid;
  v_sub public.subempreitadas;
  v_utilizador_id uuid;
begin
  select pi
  into v_item
  from public.planeamento_itens pi
  where pi.id = p_planeamento_item_id
  for update;

  if not found then
    raise exception
      'Tarefa/pacote de subempreitada não encontrado.';
  end if;

  select fase.obra_id
  into v_obra_id
  from public.fases fase
  where fase.id = v_item.fase_id;

  if not found then
    raise exception
      'A fase associada à tarefa não foi encontrada.';
  end if;

  select s.*
  into v_sub
  from public.subempreitadas s
  where s.id = v_item.subempreitada_id;

  if not found then
    raise exception
      'A tarefa não está associada a uma subempreitada.';
  end if;

  if not public.fn_pode_editar_obra(v_obra_id) then
    raise exception
      'Só a equipa técnica responsável pode confirmar este compromisso.';
  end if;

  if lower(coalesce(v_sub.estado,'')) not in (
    'adjudicada',
    'adjudicado',
    'em_execucao',
    'concluida',
    'concluido'
  ) then
    raise exception
      'A subempreitada ainda não está adjudicada.';
  end if;

  select id
  into v_utilizador_id
  from public.utilizadores
  where auth_user_id = auth.uid()
  limit 1;

  update public.planeamento_itens
  set
    compromisso_confirmado = true,
    compromisso_confirmado_por = v_utilizador_id,
    compromisso_confirmado_em = now(),
    custo_estado = 'adjudicado'
  where id = p_planeamento_item_id
  returning * into v_item;

  return v_item;
end;
$function$

definitions.fn_criar_especialidade_fornecedor(uuid,t:
CREATE OR REPLACE FUNCTION public.fn_criar_especialidade_fornecedor(p_fornecedor_id uuid, p_nome text)
 RETURNS especialidades
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_especialidade public.especialidades;
  v_nome text := nullif(btrim(p_nome), '');
  v_nome_normalizado text;
begin
  if not (public.fn_e_admin() or public.fn_e_administrativo()) then
    raise exception 'SÃ³ o Administrativo ou a GestÃ£o da Plataforma pode criar especialidades.' using errcode = '42501';
  end if;
  if v_nome is null or length(v_nome) < 3 then
    raise exception 'Indique uma especialidade com pelo menos 3 caracteres.';
  end if;
  if length(v_nome) > 120 then
    raise exception 'A especialidade nÃ£o pode exceder 120 caracteres.';
  end if;
  if not exists (
    select 1
    from public.fornecedores f
    join public.utilizadores u on u.id = public.fn_utilizador_atual_id()
    where f.id = p_fornecedor_id
      and f.empresa_id = u.empresa_id
      and coalesce(u.ativo, true)
  ) then
    raise exception 'Fornecedor inexistente ou fora da sua empresa.';
  end if;

  v_nome_normalizado := regexp_replace(
    translate(lower(v_nome), 'Ã¡Ã Ã£Ã¢Ã¤Ã©Ã¨ÃªÃ«Ã­Ã¬Ã®Ã¯Ã³Ã²ÃµÃ´Ã¶ÃºÃ¹Ã»Ã¼Ã§Ã±', 'aaaaaeeeeiiiiooooouuuucn'),
    '[^a-z0-9]', '', 'g'
  );
  perform pg_advisory_xact_lock(hashtext('especialidade:' || v_nome_normalizado));

  select e.* into v_especialidade
  from public.especialidades e
  where regexp_replace(
    translate(lower(btrim(e.nome)), 'Ã¡Ã Ã£Ã¢Ã¤Ã©Ã¨ÃªÃ«Ã­Ã¬Ã®Ã¯Ã³Ã²ÃµÃ´Ã¶ÃºÃ¹Ã»Ã¼Ã§Ã±', 'aaaaaeeeeiiiiooooouuuucn'),
    '[^a-z0-9]', '', 'g'
  ) = v_nome_normalizado
  order by e.id
  limit 1
  for update;

  if not found then
    insert into public.especialidades (nome, aplicavel_subempreiteiro)
    values (v_nome, true)
    returning * into v_especialidade;
  elsif not coalesce(v_especialidade.aplicavel_subempreiteiro, false) then
    update public.especialidades
    set aplicavel_subempreiteiro = true
    where id = v_especialidade.id
    returning * into v_especialidade;
  end if;

  insert into public.fornecedores_especialidades (
    fornecedor_id, especialidade_id, origem, criado_por
  ) values (
    p_fornecedor_id, v_especialidade.id, 'manual', public.fn_utilizador_atual_id()
  ) on conflict (fornecedor_id, especialidade_id) do nothing;

  return v_especialidade;
end;
$function$

definitions.fn_devolver_fatura_administrativo(uuid,t:
CREATE OR REPLACE FUNCTION public.fn_devolver_fatura_administrativo(p_fatura_id uuid, p_observacao text)
 RETURNS faturas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_fatura public.faturas;
  v_funcao text;
begin
  select funcao into v_funcao
  from public.utilizadores
  where id = public.fn_utilizador_atual_id()
    and coalesce(ativo, true);

  select * into v_fatura
  from public.faturas
  where id = p_fatura_id
  for update;

  if not found then
    raise exception 'Fatura nÃ£o encontrada.' using errcode = 'P0002';
  end if;
  if not (public.fn_e_admin() or v_funcao in ('diretor_obra', 'adjunto'))
     or not (public.fn_e_admin() or public.fn_pode_editar_obra(v_fatura.obra_id)) then
    raise exception 'A devoluÃ§Ã£o estÃ¡ reservada ao Diretor ou Adjunto responsÃ¡vel pela obra.' using errcode = '42501';
  end if;
  if nullif(btrim(p_observacao), '') is null then
    raise exception 'A nota Ã© obrigatÃ³ria para devolver a fatura.';
  end if;
  if v_fatura.estado_fluxo not in ('recebida', 'em_validacao', 'aprovada_tecnicamente')
     or v_fatura.estado_pagamento = 'pago' then
    raise exception 'Esta fatura jÃ¡ nÃ£o pode ser devolvida ao Administrativo.';
  end if;

  update public.faturas
  set estado_fluxo = 'devolvida_administrativo',
      estado_aprovacao = 'pendente',
      estado_pagamento = 'por_pagar',
      observacao_devolucao = btrim(p_observacao),
      devolvido_por = public.fn_utilizador_atual_id(),
      devolvido_em = now(),
      aprovado_por = null,
      data_aprovacao = null,
      aprovada_sem_guia = false
  where id = p_fatura_id
  returning * into v_fatura;

  return v_fatura;
end;
$function$

definitions.fn_editar_rnc_base(uuid,date,text,text,t:
CREATE OR REPLACE FUNCTION public.fn_editar_rnc_base(p_rnc_id uuid, p_data_deteccao date, p_local_ocorrencia text, p_descricao text, p_gravidade text)
 RETURNS rnc
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_row public.rnc;
begin
  select * into v_row from public.rnc where id=p_rnc_id for update;
  if not found then raise exception 'RNC não encontrada.'; end if;
  if not public.fn_pode_editar_obra(v_row.obra_id) then raise exception 'Sem permissão.' using errcode='42501'; end if;
  if nullif(btrim(p_descricao),'') is null or p_gravidade not in ('critica','maior','menor') then raise exception 'Dados da RNC inválidos.'; end if;
  update public.rnc set data_deteccao=coalesce(p_data_deteccao,data_deteccao),local_ocorrencia=nullif(btrim(p_local_ocorrencia),''),descricao=btrim(p_descricao),gravidade=p_gravidade
  where id=p_rnc_id returning * into v_row; return v_row;
end; $function$

definitions.fn_gerir_registo_frota(text,uuid,text,js:
CREATE OR REPLACE FUNCTION public.fn_gerir_registo_frota(p_tabela text, p_registo_id uuid, p_acao text, p_dados jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_row jsonb;
begin
  if not (public.fn_e_admin() or public.fn_e_administrativo()) then raise exception 'Operação reservada a Administrativo/Gerência.' using errcode='42501'; end if;
  if p_acao not in ('editar','apagar') then raise exception 'Ação inválida.'; end if;
  if p_tabela='viaturas_eventos' then
    if p_acao='editar' then update public.viaturas_eventos set descricao=nullif(btrim(p_dados->>'descricao'),'') where id=p_registo_id returning to_jsonb(viaturas_eventos) into v_row;
    else delete from public.viaturas_eventos where id=p_registo_id returning to_jsonb(viaturas_eventos) into v_row; end if;
  elsif p_tabela='viaturas_sinistros' then
    if p_acao='editar' then update public.viaturas_sinistros set descricao=coalesce(nullif(btrim(p_dados->>'descricao'),''),descricao),estado=case when p_dados ? 'estado' and p_dados->>'estado' in ('aberto','em_seguradora','fechado') then p_dados->>'estado' else estado end where id=p_registo_id returning to_jsonb(viaturas_sinistros) into v_row;
    else delete from public.viaturas_sinistros where id=p_registo_id returning to_jsonb(viaturas_sinistros) into v_row; end if;
  elsif p_tabela='multas' then
    if p_acao='editar' then update public.multas set descricao=nullif(btrim(p_dados->>'descricao'),'') where id=p_registo_id returning to_jsonb(multas) into v_row;
    else delete from public.multas where id=p_registo_id returning to_jsonb(multas) into v_row; end if;
  elsif p_tabela='viaturas_sinistros_anexos' and p_acao='apagar' then delete from public.viaturas_sinistros_anexos where id=p_registo_id returning to_jsonb(viaturas_sinistros_anexos) into v_row;
  elsif p_tabela='multas_anexos' and p_acao='apagar' then delete from public.multas_anexos where id=p_registo_id returning to_jsonb(multas_anexos) into v_row;
  else raise exception 'Tabela de frota não autorizada.'; end if;
  if v_row is null then raise exception 'Registo não encontrado.'; end if;
  return v_row;
end; $function$

definitions.fn_importar_orcamento_fases(uuid,jsonb,t:
CREATE OR REPLACE FUNCTION public.fn_importar_orcamento_fases(p_obra_id uuid, p_linhas jsonb, p_nome_ficheiro text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare linha jsonb; total integer:=0; fase_obra uuid;
begin
  if not (public.fn_e_gestao_plataforma() or public.fn_e_diretor_obra(p_obra_id)) then raise exception 'Importação reservada à Gestão da Plataforma ou Diretor de Obra.' using errcode='42501'; end if;
  for linha in select * from jsonb_array_elements(coalesce(p_linhas,'[]'::jsonb)) loop
    select obra_id into fase_obra from public.fases where id=(linha->>'fase_id')::uuid;
    if fase_obra is distinct from p_obra_id then raise exception 'A fase indicada não pertence à obra.'; end if;
    insert into public.orcamento_fases(obra_id,fase_id,descricao,venda_prevista,custo_total_estimado,margem_prevista,deslocacoes,mao_obra,maquinas,materiais,mao_obra_sub,subempreitada,nome_ficheiro_origem,importado_por,importado_em)
    values(p_obra_id,(linha->>'fase_id')::uuid,linha->>'descricao',coalesce((linha->>'venda_prevista')::numeric,0),coalesce((linha->>'custo_total_estimado')::numeric,0),coalesce((linha->>'margem_prevista')::numeric,0),coalesce((linha->>'deslocacoes')::numeric,0),coalesce((linha->>'mao_obra')::numeric,0),coalesce((linha->>'maquinas')::numeric,0),coalesce((linha->>'materiais')::numeric,0),coalesce((linha->>'mao_obra_sub')::numeric,0),coalesce((linha->>'subempreitada')::numeric,0),p_nome_ficheiro,public.fn_utilizador_atual_id(),now())
    on conflict(fase_id) do update set descricao=excluded.descricao,venda_prevista=excluded.venda_prevista,custo_total_estimado=excluded.custo_total_estimado,margem_prevista=excluded.margem_prevista,deslocacoes=excluded.deslocacoes,mao_obra=excluded.mao_obra,maquinas=excluded.maquinas,materiais=excluded.materiais,mao_obra_sub=excluded.mao_obra_sub,subempreitada=excluded.subempreitada,nome_ficheiro_origem=excluded.nome_ficheiro_origem,importado_por=excluded.importado_por,importado_em=now();
    total:=total+1;
  end loop;
  return jsonb_build_object('importadas',total);
end $function$

definitions.fn_quadro_operar_v1(text,jsonb,boolean,t:
CREATE OR REPLACE FUNCTION public.fn_quadro_operar_v1(p_acao text, p_dados jsonb, p_confirmar boolean DEFAULT false, p_versao text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE u public.utilizadores; c public.colaboradores; v_person uuid; v_day date;
 v_before jsonb; v_after jsonb; v_row jsonb; v_source jsonb; v_period text; v_dest uuid; v_kind text; v_desc text;
 v_request uuid; v_revision integer; v_version text; v_result jsonb; v_operation public.quadro_operacoes;
 v_overlap jsonb; v_id uuid; v_ids jsonb; v_data jsonb;
BEGIN
 IF coalesce(p_dados->>'version','')<>'1' OR jsonb_typeof(p_dados)<>'object' THEN RAISE EXCEPTION 'CONTRACT_VERSION: contrato esperado 1.'; END IF;
 IF p_acao='renomear_linha' AND p_confirmar IS NOT NULL THEN RETURN public.fn_quadro_renomear_interno(p_dados,p_confirmar,p_versao); END IF;
 IF p_acao IS NULL OR p_acao NOT IN('alocar','adicionar','mover','corrigir','remover') OR p_confirmar IS NULL
 THEN RAISE EXCEPTION 'VALIDATION_ERROR: operação inválida.'; END IF;
 SELECT * INTO u FROM public.utilizadores WHERE id=public.fn_utilizador_atual_id() AND ativo IS TRUE;
 IF u.id IS NULL OR u.empresa_id IS NULL THEN RAISE EXCEPTION 'PERMISSION_DENIED: sessão sem utilizador ativo.' USING ERRCODE='42501'; END IF;
 v_request:=nullif(p_dados->>'request_id','')::uuid;
 IF v_request IS NULL THEN RAISE EXCEPTION 'VALIDATION_ERROR: request_id obrigatório.'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('quadro-request:'||v_request::text,0));
 SELECT * INTO v_operation FROM public.quadro_operacoes WHERE request_id=v_request;
 IF FOUND THEN
  IF v_operation.utilizador_id<>u.id OR v_operation.empresa_id<>u.empresa_id
   OR v_operation.pedido IS DISTINCT FROM jsonb_build_object('acao',p_acao,'dados',p_dados,'versao',p_versao)
  THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: request_id usado com outro pedido.'; END IF;
  RETURN v_operation.resultado||jsonb_build_object('idempotent',true);
 END IF;
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;
 PERFORM pg_advisory_xact_lock(61001,1);
 v_person:=(p_dados->>'colaborador_id')::uuid; v_day:=(p_dados->>'data')::date;
 SELECT * INTO c FROM public.colaboradores WHERE id=v_person AND empresa_id=u.empresa_id FOR UPDATE;
 IF NOT FOUND OR v_day IS NULL THEN RAISE EXCEPTION 'PERMISSION_DENIED: colaborador/data inválidos nesta empresa.' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_person::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended(v_person::text||':'||v_day::text,0));
 SELECT coalesce((SELECT revisao FROM public.quadro_dias_revisoes WHERE colaborador_id=v_person AND data=v_day),0) INTO v_revision;
 IF nullif(p_dados->>'expected_revision','')::integer IS DISTINCT FROM v_revision
 THEN RAISE EXCEPTION 'STALE_REVISION: alocação alterada; recarregue.'; END IF;
 v_before:=public.fn_quadro_dia_explicito(v_person,v_day); v_after:=v_before;
 IF p_acao='remover' THEN
  v_ids:=p_dados->'ids';
  IF jsonb_typeof(v_ids) IS DISTINCT FROM 'array' OR jsonb_array_length(v_ids)=0
   OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(v_ids) i WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_before) b WHERE b->>'id'=i))
  THEN RAISE EXCEPTION 'STALE_REVISION: origem inexistente; recarregue.'; END IF;
  SELECT coalesce(jsonb_agg(b ORDER BY b->>'id'),'[]') INTO v_after FROM jsonb_array_elements(v_before) b
  WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(v_ids) i WHERE b->>'id'=i);
 ELSE
  v_period:=p_dados->>'periodo'; v_kind:=p_dados->>'tipo_alocacao'; v_dest:=nullif(p_dados->>'obra_id','')::uuid;
  v_desc:=CASE WHEN v_kind='obra' THEN NULL ELSE nullif(btrim(p_dados->>'descricao_livre'),'') END;
  IF v_period IS NULL OR v_period NOT IN('manha','tarde','dia_inteiro') THEN RAISE EXCEPTION 'VALIDATION_ERROR: período inválido.'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_before) a JOIN jsonb_array_elements(v_before) b ON a->>'id'<b->>'id'
    WHERE a->>'periodo'='dia_inteiro' OR b->>'periodo'='dia_inteiro' OR a->>'periodo'=b->>'periodo')
  THEN RAISE EXCEPTION 'LEGACY_CONFLICT: sobreposição histórica; solicite revisão humana.'; END IF;
  SELECT coalesce(jsonb_agg(b ORDER BY b->>'id'),'[]') INTO v_overlap FROM jsonb_array_elements(v_before) b
   WHERE v_period='dia_inteiro' OR b->>'periodo'='dia_inteiro' OR b->>'periodo'=v_period;
  v_after:='[]';
  FOR v_row IN SELECT value FROM jsonb_array_elements(v_before) LOOP
   IF v_period<>'dia_inteiro' AND v_row->>'periodo'='dia_inteiro' THEN
    v_after:=v_after||jsonb_build_array(v_row||jsonb_build_object('periodo',CASE v_period WHEN 'manha' THEN 'tarde' ELSE 'manha' END));
   ELSIF NOT(v_period='dia_inteiro' OR v_row->>'periodo'=v_period) THEN v_after:=v_after||jsonb_build_array(v_row);
   END IF;
  END LOOP;
  v_source:=v_overlap->0;
  v_id:=CASE WHEN v_source IS NOT NULL AND NOT(v_period<>'dia_inteiro' AND v_source->>'periodo'='dia_inteiro')
   THEN (v_source->>'id')::uuid ELSE gen_random_uuid() END;
  v_after:=v_after||jsonb_build_array(coalesce(v_source,'{}')||jsonb_build_object('id',v_id,'colaborador_id',v_person,'data',v_day,
    'periodo',v_period,'tipo_alocacao',v_kind,'obra_id',v_dest,'descricao_livre',v_desc));
 END IF;
 SELECT coalesce(jsonb_agg(b ORDER BY b->>'id'),'[]') INTO v_after FROM jsonb_array_elements(v_after) b;
 -- IDs novos só pertencem ao plano transitório: não entram na assinatura do preview.
 SELECT coalesce(jsonb_agg((b-'id'-'criado_em'-'criado_por'-'semana_inicio') ORDER BY b->>'periodo'),'[]') INTO v_data FROM jsonb_array_elements(v_after) b;
 v_version:=md5(jsonb_build_object('before',v_before,'revision',v_revision,'after',v_data,'acao',p_acao,'dados',p_dados)::text);
 IF NOT public.fn_quadro_pode_gerir_v1(NULL) AND u.funcao<>'encarregado' THEN RAISE EXCEPTION 'PERMISSION_DENIED: consulta sem edição.' USING ERRCODE='42501'; END IF;
 FOR v_row IN SELECT value FROM jsonb_array_elements(v_before||v_after) LOOP
  IF NOT public.fn_quadro_pode_gerir_v1(NULL) AND (v_row->>'tipo_alocacao'<>'obra' OR NOT public.fn_quadro_minha_obra_v1((v_row->>'obra_id')::uuid))
  THEN RAISE EXCEPTION 'PERMISSION_DENIED: origem/destino fora da equipa autorizada.' USING ERRCODE='42501'; END IF;
 END LOOP;
 PERFORM public.fn_quadro_aplicar_interno(v_person,v_day,v_before,v_after,'quadro',v_request,true);
 IF NOT p_confirmar THEN RETURN jsonb_build_object('version',1,'committed',false,'revision',v_revision,'versao',v_version,'before',v_before,'after',v_after); END IF;
 IF p_versao IS DISTINCT FROM v_version THEN RAISE EXCEPTION 'STALE_REVISION: preview desatualizado; recarregue.'; END IF;
 v_result:=public.fn_quadro_aplicar_interno(v_person,v_day,v_before,v_after,'quadro',v_request);
 v_result:=v_result||jsonb_build_object('version',1,'committed',true,'idempotent',false,'colaborador_id',v_person,'data',v_day,'revision',coalesce((v_result->>'revision')::integer,v_revision));
 INSERT INTO public.quadro_operacoes(request_id,empresa_id,utilizador_id,pedido,resultado)
 VALUES(v_request,u.empresa_id,u.id,jsonb_build_object('acao',p_acao,'dados',p_dados,'versao',p_versao),v_result);
 RETURN v_result;
END $function$

definitions.fn_rh_guardar_interno(jsonb,boolean,bool:
CREATE OR REPLACE FUNCTION public.fn_rh_guardar_interno(p_dados jsonb, p_simular boolean, p_importacao boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_empresa uuid:=public.fn_rh_empresa(p_importacao); v_id uuid:=nullif(p_dados->>'id','')::uuid;
  v_antes jsonb; v_patch jsonb:=coalesce(p_dados->'campos','{}'); v_result jsonb;
  v_c public.colaboradores%rowtype; v_ct public.colaboradores_contratos%rowtype;
  v_cp jsonb:=p_dados->'contrato'; v_niss text; v_count integer; v_alterado boolean;
  v_novo boolean:=v_id is null; v_original_ct jsonb;
  v_avisos jsonb:='[]'; v_pendencia text;
begin
  perform pg_advisory_xact_lock(hashtextextended('rh:'||v_empresa::text,0));
  if p_importacao and v_novo then raise exception 'A importação exige ID existente.'; end if;
  if jsonb_typeof(v_patch) is distinct from 'object' then raise exception 'Campos inválidos.'; end if;
  if exists(select 1 from jsonb_object_keys(v_patch) k where k not in
    ('nome','funcao','nivel','valor_hora','nif','email','contacto','morada','data_admissao',
     'data_nascimento','data_saida','codigo_rh','observacoes','seguranca_social_ok','seguro_ok','registo_trabalhador_ok')) then
    raise exception 'Campos de RH desconhecidos.';
  end if;
  if not v_novo then
    perform 1 from public.colaboradores where id=v_id and empresa_id=v_empresa for update;
    if not found then raise exception 'Colaborador não encontrado nesta empresa.'; end if;
    perform 1 from public.colaboradores_contratos where colaborador_id=v_id for update;
    v_antes:=public.fn_rh_consultar(v_id)->0;
  end if;
  v_c:=jsonb_populate_record(null::public.colaboradores,coalesce(v_antes->'colaborador','{}')||v_patch);
  if nullif(btrim(v_c.nome),'') is null or nullif(btrim(v_c.funcao),'') is null or v_c.data_admissao is null then
    raise exception 'Nome, função e admissão são obrigatórios.';
  end if;
  if v_c.valor_hora<0 then raise exception 'Valor/hora não pode ser negativo.'; end if;
  if v_c.data_saida<v_c.data_admissao or v_c.data_nascimento>v_c.data_admissao then raise exception 'Datas incompatíveis.'; end if;
  if nullif(v_c.nif,'') is not null and v_c.nif !~ '^[0-9]{9}$' then raise exception 'NIF deve ter 9 algarismos.'; end if;
  if nullif(v_c.email,'') is not null and v_c.email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Email inválido.'; end if;
  if exists(select 1 from public.colaboradores c where c.empresa_id=v_empresa and c.id is distinct from v_id
    and ((nullif(v_c.nif,'') is not null and c.nif=v_c.nif) or
      (nullif(v_c.codigo_rh,'') is not null and c.codigo_rh=v_c.codigo_rh))) then
    raise exception 'NIF ou código RH já pertence a outro colaborador.';
  end if;
  v_niss:=case when p_dados ? 'niss' then nullif(p_dados->>'niss','') else v_antes->>'niss' end;
  if v_niss is not null and v_niss !~ '^[0-9]{11}$' then raise exception 'NISS deve ter 11 algarismos.'; end if;
  if v_cp is not null and v_cp<>'null'::jsonb then
    if jsonb_typeof(v_cp)<>'object' then raise exception 'Contrato inválido.'; end if;
    if exists(select 1 from jsonb_object_keys(v_cp) k where k not in ('tipo_contrato','data_inicio','data_fim_prevista')) then
      raise exception 'Campos de contrato desconhecidos.';
    end if;
    select count(*) into v_count from public.colaboradores_contratos where colaborador_id=v_id and estado='ativo';
    if v_count>1 then raise exception 'Existem vários contratos ativos; rever antes de editar.'; end if;
    select * into v_ct from public.colaboradores_contratos where colaborador_id=v_id and estado='ativo';
    v_original_ct:=to_jsonb(v_ct);
    v_ct:=jsonb_populate_record(v_ct,v_cp);
    if not p_importacao and (v_ct.tipo_contrato is null or v_ct.tipo_contrato not in ('a_prazo','tempo_indeterminado') or v_ct.data_inicio is null) then
      raise exception 'Tipo e início do contrato são obrigatórios.';
    end if;
    if v_ct.tipo_contrato is not null and v_ct.tipo_contrato not in ('a_prazo','tempo_indeterminado') then
      raise exception 'Tipo de contrato inválido.';
    end if;
    if v_ct.data_inicio is null then v_pendencia:='Início do contrato em falta.';
    elsif v_ct.tipo_contrato='a_prazo' and v_ct.data_fim_prevista is null then v_pendencia:='Indique o fim previsto.';
    elsif v_ct.data_fim_prevista<v_ct.data_inicio then v_pendencia:='Fim contratual anterior ao início.';
    end if;
    if v_pendencia is not null then
      if not p_importacao then raise exception '%',v_pendencia; end if;
      v_avisos:=v_avisos||jsonb_build_array('Contrato não alterado: '||v_pendencia||' Os restantes campos podem ser atualizados.');
      v_cp:=null;
    elsif v_ct.tipo_contrato='tempo_indeterminado' and v_ct.data_fim_prevista is not null then
      if not p_importacao then raise exception 'Tempo indeterminado não tem fim previsto.'; end if;
      -- Na importação parcial, vazio não autoriza apagar uma data anterior.
      if v_cp ? 'data_fim_prevista' then
        v_avisos:=v_avisos||jsonb_build_array('Contrato não alterado: tempo indeterminado com fim fornecido. Rever no cadastro individual.');
        v_cp:=null;
      else
        v_avisos:=v_avisos||jsonb_build_array('Fim previsto existente preservado. Rever no cadastro individual o contrato sem termo.');
      end if;
    elsif v_ct.tipo_contrato is null then
      v_avisos:=v_avisos||jsonb_build_array('Data contratual aceite; tipo de contrato por confirmar pelo RH.');
    end if;
  end if;
  v_alterado:=v_novo or to_jsonb(v_c) is distinct from v_antes->'colaborador'
    or v_niss is distinct from v_antes->>'niss'
    or (v_cp is not null and v_cp<>'null'::jsonb and to_jsonb(v_ct) is distinct from v_original_ct);
  -- Reimportar o mesmo conteúdo é um no-op, mesmo com a versão antiga do Excel.
  if not v_novo and v_alterado and p_dados->>'versao' is distinct from v_antes->>'versao' then
    raise exception 'Cadastro alterado entretanto. Reabra ou exporte novamente o modelo.';
  end if;
  if v_novo then
    if p_dados->>'alocacao_tipo' is not null and p_dados->>'alocacao_tipo' not in ('obra','escritorio') then raise exception 'Indique a alocação inicial.'; end if;
    if p_dados->>'alocacao_tipo'='obra' and not exists(select 1 from public.obras
      where id=nullif(p_dados->>'obra_id','')::uuid and empresa_id=v_empresa and situacao in ('preparacao','em_curso')) then
      raise exception 'Selecione uma obra ativa da empresa.';
    end if;
    if p_dados->>'alocacao_tipo'='escritorio' and nullif(p_dados->>'obra_id','') is not null then raise exception 'Escritório não tem obra.'; end if;
    perform nullif(p_dados->>'epi_data','')::date;
    perform nullif(p_dados->>'medicina_data','')::date;
  end if;
  if p_simular or not v_alterado then return jsonb_build_object('alterado',v_alterado,'id',v_id,'avisos',v_avisos); end if;
  if v_novo then
    v_id:=(public.fn_quadro_criar_colaborador_interno(v_c.nome,v_c.funcao,v_c.data_admissao,v_c.data_nascimento,
      p_dados->>'alocacao_tipo',nullif(p_dados->>'obra_id','')::uuid,v_c.nivel,v_c.valor_hora,v_c.nif,v_c.email,v_c.contacto,v_c.morada,case when p_importacao then 'importacao_rh' else 'cadastro_rh' end)
      ->'colaborador'->>'id')::uuid;
  end if;
  update public.colaboradores set nome=v_c.nome,funcao=v_c.funcao,nivel=v_c.nivel,valor_hora=v_c.valor_hora,
    nif=v_c.nif,email=v_c.email,contacto=v_c.contacto,morada=v_c.morada,data_admissao=v_c.data_admissao,
    data_nascimento=v_c.data_nascimento,data_saida=v_c.data_saida,codigo_rh=v_c.codigo_rh,observacoes=v_c.observacoes,
    seguranca_social_ok=v_c.seguranca_social_ok,seguro_ok=v_c.seguro_ok,registo_trabalhador_ok=v_c.registo_trabalhador_ok
    where id=v_id and empresa_id=v_empresa;
  if v_novo then
    if nullif(p_dados->>'epi_data','') is not null then
      insert into public.epis(colaborador_id,tipo_epi,data_entrega,data_validade)
      values(v_id,'Entrega inicial',(p_dados->>'epi_data')::date,null);
    end if;
    if nullif(p_dados->>'medicina_data','') is not null then
      insert into public.medicina_trabalho(colaborador_id,data_ultima_consulta,resultado,data_proxima_consulta)
      values(v_id,(p_dados->>'medicina_data')::date,'Consulta inicial registada na admissão',null);
    end if;
  elsif (v_antes->'colaborador'->>'data_saida') is distinct from v_c.data_saida::text then
    perform public.fn_atualizar_colaborador_ciclo_vida(v_id,v_c.nome,v_c.funcao,v_c.data_admissao,
      v_c.data_nascimento,v_c.data_saida,v_c.nivel,v_c.valor_hora,v_c.nif,v_c.email,v_c.contacto,v_c.morada);
  end if;
  insert into public.colaboradores_rh_privado(colaborador_id,niss) values(v_id,v_niss)
    on conflict(colaborador_id) do update set niss=excluded.niss;
  if v_cp is not null and v_cp<>'null'::jsonb then
    if v_ct.id is null then
      insert into public.colaboradores_contratos(colaborador_id,tipo_contrato,data_inicio,data_fim_prevista,estado)
      values(v_id,v_ct.tipo_contrato,v_ct.data_inicio,v_ct.data_fim_prevista,'ativo');
    else
      update public.colaboradores_contratos set tipo_contrato=v_ct.tipo_contrato,data_inicio=v_ct.data_inicio,
        data_fim_prevista=v_ct.data_fim_prevista where id=v_ct.id;
    end if;
  end if;
  v_result:=public.fn_rh_consultar(v_id)->0;
  insert into public.rh_cadastro_auditoria(empresa_id,colaborador_id,utilizador_id,origem,antes,depois)
    values(v_empresa,v_id,public.fn_utilizador_atual_id(),case when p_importacao then 'importacao_excel' else 'cadastro' end,v_antes,v_result);
  return jsonb_build_object('alterado',true,'id',v_id,'avisos',v_avisos);
end $function$

definitions.fn_parametro_operacional_dias(text,integ:
CREATE OR REPLACE FUNCTION public.fn_parametro_operacional_dias(p_chave text, p_default integer[])
 RETURNS integer[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_texto text;
  v_dias integer[];
begin
  v_texto := public.fn_parametro_operacional_texto(
    p_chave,
    array_to_string(p_default, ',')
  );

  select array_agg(x.dia order by x.ordem)
  into v_dias
  from (
    select
      btrim(parte)::integer as dia,
      ordem
    from unnest(string_to_array(v_texto, ','))
      with ordinality as partes(parte, ordem)
    where btrim(parte) ~ '^\d+$'
  ) x
  where x.dia >= 0;

  return coalesce(v_dias, p_default);
end;
$function$

definitions.fn_parametro_operacional_numero(text,num:
CREATE OR REPLACE FUNCTION public.fn_parametro_operacional_numero(p_chave text, p_default numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_valor text;
begin
  v_valor := public.fn_parametro_operacional_texto(
    p_chave,
    p_default::text
  );

  begin
    return replace(v_valor, ',', '.')::numeric;
  exception
    when invalid_text_representation then
      return p_default;
  end;
end;
$function$

definitions.fn_quadro_renomear_interno(jsonb,boolean:
CREATE OR REPLACE FUNCTION public.fn_quadro_renomear_interno(p_dados jsonb, p_confirmar boolean, p_versao text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE u public.utilizadores; v_request uuid; v_kind text; v_old text; v_new text;
 v_operation public.quadro_operacoes; v_days jsonb; v_day jsonb; v_after jsonb; v_version text; v_result jsonb;
BEGIN
 SELECT * INTO u FROM public.utilizadores WHERE id=public.fn_utilizador_atual_id() AND ativo IS TRUE;
 IF u.id IS NULL OR NOT public.fn_quadro_pode_gerir_v1(NULL) THEN RAISE EXCEPTION 'PERMISSION_DENIED: só Administrativo/Gestão pode renomear linhas.' USING ERRCODE='42501'; END IF;
 v_request:=nullif(p_dados->>'request_id','')::uuid; v_kind:=p_dados->>'tipo_alocacao';
 v_old:=nullif(btrim(p_dados->>'descricao_anterior'),''); v_new:=nullif(btrim(p_dados->>'descricao_nova'),'');
 IF v_request IS NULL OR v_old IS NULL OR v_new IS NULL OR v_kind IS NULL OR v_kind NOT IN('garantia','pontual')
 THEN RAISE EXCEPTION 'VALIDATION_ERROR: designação inválida.'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('quadro-request:'||v_request::text,0));
 SELECT * INTO v_operation FROM public.quadro_operacoes WHERE request_id=v_request;
 IF FOUND THEN
  IF v_operation.utilizador_id<>u.id OR v_operation.empresa_id<>u.empresa_id OR v_operation.pedido
    IS DISTINCT FROM jsonb_build_object('acao','renomear_linha','dados',p_dados,'versao',p_versao)
  THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: request_id usado com outro pedido.'; END IF;
  RETURN v_operation.resultado||jsonb_build_object('idempotent',true);
 END IF;
 -- Renomeação explícita abrange uma linha da empresa; serializar o conjunto para não perder novos registos.
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;
 PERFORM pg_advisory_xact_lock(61001,1);
 PERFORM c.id FROM public.colaboradores c WHERE c.empresa_id=u.empresa_id AND EXISTS(
 SELECT 1 FROM public.quadro_pessoal_alocacao q WHERE q.colaborador_id=c.id AND q.tipo_alocacao=v_kind AND q.descricao_livre=v_old) ORDER BY c.id FOR UPDATE;
 SELECT coalesce(jsonb_agg(jsonb_build_object('person',d.colaborador_id,'data',d.data,
  'before',public.fn_quadro_dia_explicito(d.colaborador_id,d.data),
  'revision',coalesce((SELECT r.revisao FROM public.quadro_dias_revisoes r WHERE r.colaborador_id=d.colaborador_id AND r.data=d.data),0))
 ORDER BY d.colaborador_id,d.data),'[]') INTO v_days FROM (
 SELECT DISTINCT q.colaborador_id,q.data FROM public.quadro_pessoal_alocacao q JOIN public.colaboradores c ON c.id=q.colaborador_id
 WHERE c.empresa_id=u.empresa_id AND q.tipo_alocacao=v_kind AND q.descricao_livre=v_old) d;
 v_version:=md5(jsonb_build_object('days',v_days,'dados',p_dados)::text);
 FOR v_day IN SELECT value FROM jsonb_array_elements(v_days) LOOP
  SELECT jsonb_agg(CASE WHEN a->>'tipo_alocacao'=v_kind AND a->>'descricao_livre'=v_old
    THEN a||jsonb_build_object('descricao_livre',v_new) ELSE a END ORDER BY a->>'id') INTO v_after
    FROM jsonb_array_elements(v_day->'before') a;
  PERFORM public.fn_quadro_aplicar_interno((v_day->>'person')::uuid,(v_day->>'data')::date,v_day->'before',v_after,'quadro',v_request,true);
 END LOOP;
 IF NOT p_confirmar THEN RETURN jsonb_build_object('version',1,'committed',false,'versao',v_version,'days',jsonb_array_length(v_days)); END IF;
 IF p_versao IS DISTINCT FROM v_version THEN RAISE EXCEPTION 'STALE_REVISION: designação alterada; recarregue.'; END IF;
 FOR v_day IN SELECT value FROM jsonb_array_elements(v_days) LOOP
  SELECT jsonb_agg(CASE WHEN a->>'tipo_alocacao'=v_kind AND a->>'descricao_livre'=v_old
    THEN a||jsonb_build_object('descricao_livre',v_new) ELSE a END ORDER BY a->>'id') INTO v_after
    FROM jsonb_array_elements(v_day->'before') a;
  PERFORM public.fn_quadro_aplicar_interno((v_day->>'person')::uuid,(v_day->>'data')::date,v_day->'before',v_after,'quadro',v_request);
 END LOOP;
 v_result:=jsonb_build_object('version',1,'committed',true,'idempotent',false,'days',jsonb_array_length(v_days));
 INSERT INTO public.quadro_operacoes(request_id,empresa_id,utilizador_id,pedido,resultado)
 VALUES(v_request,u.empresa_id,u.id,jsonb_build_object('acao','renomear_linha','dados',p_dados,'versao',p_versao),v_result);
 RETURN v_result;
END $function$

definitions.fn_validar_atualizacao_parametro_operaci:
CREATE OR REPLACE FUNCTION public.fn_validar_atualizacao_parametro_operacional()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  new.valor := btrim(new.valor);

  if new.chave in (
    'antecedencias_alerta_contrato_rh',
    'antecedencias_alerta_documento_empresa',
    'antecedencias_alerta_pedido_orcamento'
  )
  and new.valor !~ '^\s*\d+\s*(,\s*\d+\s*)*$'
  then
    raise exception
      'Indique uma lista de dias separada por vírgulas (ex.: 15,7,3).';
  end if;

  if new.chave like 'antecedencia_alerta_%'
     and new.chave not like 'antecedencias_%'
     and new.valor !~ '^\d+$'
  then
    raise exception
      'A antecedência deve ser um número inteiro de dias.';
  end if;

  if new.chave = 'valor_minimo_contrato_subempreitada'
     and new.valor !~ '^\d+([\.,]\d+)?$'
  then
    raise exception
      'O limite de contrato deve ser um valor numérico positivo.';
  end if;

  new.atualizado_por := public.fn_utilizador_atual_id();
  new.atualizado_em := now();

  return new;
end;
$function$

definitions.fn_medicina_consultar_colaborador(intege:
CREATE OR REPLACE FUNCTION public.fn_medicina_consultar_colaborador(p_version integer, p_colaborador_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_manage boolean; v_atual public.medicina_trabalho; v_linhas jsonb; v_audit jsonb;
BEGIN
 IF p_version IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'VALIDATION_FAILED: versão inválida.'; END IF;
 v_manage:=public.fn_medicina_pode_gerir(p_colaborador_id);
 IF NOT v_manage AND NOT (public.fn_colaborador_na_obra_atual_encarregado(p_colaborador_id)
 AND EXISTS(SELECT 1 FROM public.colaboradores c JOIN public.utilizadores u ON u.empresa_id=c.empresa_id
 WHERE c.id=p_colaborador_id AND u.id=public.fn_utilizador_atual_id() AND u.ativo)) THEN
  RAISE EXCEPTION 'PERMISSION_DENIED: sem acesso à Medicina deste colaborador.' USING ERRCODE='42501';
 END IF;
 SELECT * INTO v_atual FROM public.fn_medicina_atual(p_colaborador_id);
 IF NOT v_manage THEN
  RETURN jsonb_build_object('version',1,'can_write',false,'atual',
   CASE WHEN v_atual.id IS NULL THEN NULL ELSE jsonb_build_object('id',v_atual.id,
   'colaborador_id',v_atual.colaborador_id,'data_ultima_consulta',v_atual.data_ultima_consulta,
   'resultado',v_atual.resultado,'data_proxima_consulta',v_atual.data_proxima_consulta,'criado_em',v_atual.criado_em) END);
 END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY data_ultima_consulta DESC NULLS LAST,criado_em DESC,id DESC),'[]')
 INTO v_linhas FROM public.medicina_trabalho m WHERE colaborador_id=p_colaborador_id;
 SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY criado_em,id),'[]') INTO v_audit
 FROM public.medicina_operacoes o WHERE colaborador_id=p_colaborador_id
 AND empresa_id=(SELECT empresa_id FROM public.utilizadores WHERE id=public.fn_utilizador_atual_id());
 RETURN jsonb_build_object('version',1,'can_write',true,'atual',
 CASE WHEN v_atual.id IS NULL THEN NULL ELSE to_jsonb(v_atual) END,'consultas',v_linhas,'historico',v_audit);
END $function$

definitions.fn_registar_documento_obra(uuid,text,tex:
CREATE OR REPLACE FUNCTION public.fn_registar_documento_obra(p_obra_id uuid, p_tipo text, p_nome_arquivo text, p_arquivo_url text)
 RETURNS documentos_obra
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_documento public.documentos_obra;
  v_utilizador_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Sessão autenticada obrigatória.';
  end if;

  if not public.fn_pode_editar_obra(p_obra_id) then
    raise exception 'Sem permissão para enviar documentos para esta obra.';
  end if;

  if p_tipo is null or p_tipo not in (
    'contrato',
    'orcamento',
    'plantas_projeto',
    'licencas',
    'planeamento_detalhado',
    'outro'
  ) then
    raise exception 'Tipo de documento inválido.';
  end if;

  if nullif(btrim(p_nome_arquivo), '') is null then
    raise exception 'O nome do ficheiro é obrigatório.';
  end if;

  if nullif(btrim(p_arquivo_url), '') is null
     or p_arquivo_url not like p_obra_id::text || '/%' then
    raise exception 'O caminho do documento não pertence à obra indicada.';
  end if;

  v_utilizador_id := public.fn_utilizador_atual_id();
  if v_utilizador_id is null then
    raise exception 'O utilizador autenticado não está associado a public.utilizadores.';
  end if;

  insert into public.documentos_obra (
    obra_id,
    tipo,
    nome_arquivo,
    arquivo_url,
    enviado_por
  )
  values (
    p_obra_id,
    p_tipo,
    btrim(p_nome_arquivo),
    p_arquivo_url,
    v_utilizador_id
  )
  returning * into v_documento;

  return v_documento;
end;
$function$

definitions.fn_marcar_faturacao_auto_paga(uuid,date,:
CREATE OR REPLACE FUNCTION public.fn_marcar_faturacao_auto_paga(p_faturacao_id uuid, p_data_pagamento date, p_valor_pago numeric)
 RETURNS faturacao
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_faturacao public.faturacao;
begin
  if not public.fn_e_financeiro() then
    raise exception 'O pagamento está reservado ao papel Financeiro.';
  end if;

  select * into v_faturacao
  from public.faturacao
  where id = p_faturacao_id
  for update;

  if not found
     or v_faturacao.estado_aprovacao <> 'aprovado'
     or v_faturacao.estado_pagamento <> 'por_pagar' then
    raise exception 'A fatura não está aprovada ou já foi paga.';
  end if;

  if coalesce(p_valor_pago, 0) <= 0 then
    raise exception 'O valor pago tem de ser superior a zero.';
  end if;

  update public.faturacao
  set estado_pagamento = 'pago',
      pago_por = public.fn_utilizador_atual_id(),
      data_pagamento = coalesce(p_data_pagamento, current_date),
      data_recebimento = coalesce(p_data_pagamento, current_date),
      valor_recebido = p_valor_pago
  where id = p_faturacao_id
  returning * into v_faturacao;

  return v_faturacao;
end;
$function$

definitions.fn_previsualizar_mesclagem_fornecedor(uu:
CREATE OR REPLACE FUNCTION public.fn_previsualizar_mesclagem_fornecedor(p_fornecedor_origem_id uuid, p_fornecedor_destino_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_atual public.utilizadores;
  v_origem public.fornecedores;
  v_destino public.fornecedores;
  v_ref record;
  v_total bigint;
  v_total_referencias bigint := 0;
  v_referencias jsonb := '[]'::jsonb;
  v_conflitos jsonb := '[]'::jsonb;
begin
  if not (public.fn_e_admin() or public.fn_e_administrativo()) then
    raise exception 'SÃ³ o Administrativo ou a GestÃ£o da Plataforma pode mesclar fornecedores.' using errcode = '42501';
  end if;
  if p_fornecedor_origem_id is null or p_fornecedor_destino_id is null
     or p_fornecedor_origem_id = p_fornecedor_destino_id then
    raise exception 'Escolha dois registos diferentes: o duplicado e o registo que serÃ¡ mantido.';
  end if;

  select * into v_atual from public.utilizadores
  where id = public.fn_utilizador_atual_id() and coalesce(ativo, true);
  select * into v_origem from public.fornecedores
  where id = p_fornecedor_origem_id and empresa_id = v_atual.empresa_id;
  select * into v_destino from public.fornecedores
  where id = p_fornecedor_destino_id and empresa_id = v_atual.empresa_id;
  if v_origem.id is null or v_destino.id is null then
    raise exception 'Um dos fornecedores nÃ£o existe ou pertence a outra empresa.';
  end if;

  for v_ref in
    select c.conrelid::regclass as tabela, a.attname as coluna
    from pg_constraint c
    join pg_attribute a on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
    where c.contype = 'f'
      and c.confrelid = 'public.fornecedores'::regclass
      and array_length(c.conkey, 1) = 1
      and c.conrelid not in (
        'public.fornecedores_zonas'::regclass,
        'public.fornecedores_especialidades'::regclass,
        'public.fornecedores_aliases'::regclass
      )
  loop
    execute format('select count(*) from %s where %I = $1', v_ref.tabela, v_ref.coluna)
      into v_total using p_fornecedor_origem_id;
    if v_total > 0 then
      v_total_referencias := v_total_referencias + v_total;
      v_referencias := v_referencias || jsonb_build_array(jsonb_build_object(
        'tabela', v_ref.tabela::text, 'coluna', v_ref.coluna, 'registos', v_total
      ));
    end if;
  end loop;

  if to_regclass('public.comparativo_propostas') is not null then
    select count(*) into v_total
    from public.comparativo_propostas origem
    join public.comparativo_propostas destino
      on destino.mapa_id = origem.mapa_id
     and destino.fornecedor_id = p_fornecedor_destino_id
    where origem.fornecedor_id = p_fornecedor_origem_id;
    if v_total > 0 then
      v_conflitos := v_conflitos || jsonb_build_array(jsonb_build_object(
        'tipo', 'propostas_no_mesmo_mapa', 'registos', v_total,
        'mensagem', 'Os dois fornecedores tÃªm propostas no mesmo mapa comparativo. Reveja essas propostas antes de mesclar.'
      ));
    end if;
  end if;

  select count(*) into v_total
  from public.faturas origem
  join public.faturas destino
    on destino.fornecedor_id = p_fornecedor_destino_id
   and lower(btrim(destino.numero_doc)) = lower(btrim(origem.numero_doc))
   and destino.id <> origem.id
  where origem.fornecedor_id = p_fornecedor_origem_id
    and nullif(btrim(origem.numero_doc), '') is not null;
  if v_total > 0 then
    v_conflitos := v_conflitos || jsonb_build_array(jsonb_build_object(
      'tipo', 'faturas_com_mesmo_numero', 'registos', v_total,
      'mensagem', 'Existem faturas com o mesmo nÃºmero nos dois registos. Resolva essas duplicaÃ§Ãµes antes de mesclar.'
    ));
  end if;

  return jsonb_build_object(
    'origem', jsonb_build_object('id', v_origem.id, 'nome', v_origem.nome, 'nif', v_origem.nif),
    'destino', jsonb_build_object('id', v_destino.id, 'nome', v_destino.nome, 'nif', v_destino.nif),
    'total_referencias', v_total_referencias,
    'referencias', v_referencias,
    'conflitos', v_conflitos,
    'pode_mesclar', jsonb_array_length(v_conflitos) = 0
  );
end;
$function$

definitions.fn_avancar_estado_fluxo_fatura(uuid,text:
CREATE OR REPLACE FUNCTION public.fn_avancar_estado_fluxo_fatura(p_fatura_id uuid, p_novo_estado text, p_data_pagamento date DEFAULT NULL::date, p_observacao text DEFAULT NULL::text)
 RETURNS faturas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_fatura public.faturas;
  v_ordem constant text[] := array[
    'recebida',
    'em_validacao',
    'aprovada_tecnicamente',
    'enviada_financeiro',
    'paga'
  ];
  v_sem_guia boolean := false;
begin
  select * into v_fatura
  from public.faturas
  where id = p_fatura_id
  for update;

  if not found then
    raise exception 'Fatura não encontrada.';
  end if;

  if array_position(v_ordem, p_novo_estado) is null
     or array_position(v_ordem, p_novo_estado)
        <> array_position(v_ordem, v_fatura.estado_fluxo) + 1 then
    raise exception 'A fatura deve seguir os cinco estados pela ordem definida.';
  end if;

  if p_novo_estado = 'paga' then
    if not public.fn_e_financeiro() then
      raise exception 'Só o Financeiro pode marcar a fatura como paga.'
        using errcode = '42501';
    end if;
  elsif not (
    public.fn_pode_editar_obra(v_fatura.obra_id)
    or public.fn_e_admin()
  ) then
    raise exception 'Sem permissão para avançar a validação desta fatura.'
      using errcode = '42501';
  end if;

  if p_novo_estado = 'aprovada_tecnicamente' then
    v_sem_guia := not exists (
      select 1
      from public.faturas_guias
      where fatura_id = p_fatura_id
    );
  end if;

  update public.faturas
  set
    estado_fluxo = p_novo_estado,

    estado_aprovacao = case
      when p_novo_estado in (
        'aprovada_tecnicamente',
        'enviada_financeiro',
        'paga'
      ) then 'aprovado'
      else 'pendente'
    end,

    estado_pagamento = case
      when p_novo_estado = 'paga' then 'pago'
      else 'por_pagar'
    end,

    data_aprovacao = case
      when p_novo_estado = 'aprovada_tecnicamente' then now()
      else data_aprovacao
    end,

    aprovado_por = case
      when p_novo_estado = 'aprovada_tecnicamente'
        then public.fn_utilizador_atual_id()
      else aprovado_por
    end,

    observacao = case
      when p_novo_estado = 'aprovada_tecnicamente'
           and p_observacao is not null
        then nullif(btrim(p_observacao), '')
      else observacao
    end,

    aprovada_sem_guia = case
      when p_novo_estado = 'aprovada_tecnicamente' then v_sem_guia
      else aprovada_sem_guia
    end,

    data_pagamento = case
      when p_novo_estado = 'paga'
        then coalesce(p_data_pagamento, data_pagamento, current_date)
      else data_pagamento
    end

  where id = p_fatura_id
  returning * into v_fatura;

  return v_fatura;
end;
$function$

definitions.fn_decidir_aditamento_subempreitada(uuid:
CREATE OR REPLACE FUNCTION public.fn_decidir_aditamento_subempreitada(p_aditamento_id uuid, p_estado text, p_observacao text DEFAULT NULL::text)
 RETURNS subempreitada_aditamentos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_result public.subempreitada_aditamentos;
begin
  if not (public.fn_e_admin() or exists (
    select 1 from public.utilizadores u where u.id=public.fn_utilizador_atual_id()
      and u.funcao in ('gerencia','gestao_plataforma') and coalesce(u.ativo,true)
  )) then
    raise exception 'A aprovaÃ§Ã£o de aditamentos estÃ¡ reservada Ã  GerÃªncia/GestÃ£o da Plataforma.' using errcode='42501';
  end if;
  if p_estado not in ('aprovado','rejeitado') then raise exception 'DecisÃ£o invÃ¡lida.'; end if;
  update public.subempreitada_aditamentos
  set estado=p_estado,observacao_decisao=nullif(btrim(p_observacao),''),
      decidido_por=public.fn_utilizador_atual_id(),decidido_em=now()
