definitions.fn_verificar_limite_fatura_subempreitada:
CREATE OR REPLACE FUNCTION public.fn_verificar_limite_fatura_subempreitada(p_fatura_id uuid, p_etapa text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_fatura public.faturas; v_res record; v_proj_faturado numeric; v_proj_pago numeric;
begin
  select * into v_fatura from public.faturas where id=p_fatura_id;
  if not found then raise exception 'Fatura nÃ£o encontrada.' using errcode='P0002'; end if;
  if v_fatura.subempreitada_id is null then return jsonb_build_object('aplicavel',false); end if;
  select * into v_res from public.fn_resumo_controle_subempreitadas_obra(v_fatura.obra_id) r
  where r.subempreitada_id=v_fatura.subempreitada_id;
  if not found then return jsonb_build_object('aplicavel',false); end if;
  v_proj_faturado:=v_res.total_faturado+
    case when p_etapa='aprovada_tecnicamente' and v_fatura.estado_fluxo not in ('aprovada_tecnicamente','enviada_financeiro','paga') then v_fatura.valor else 0 end;
  v_proj_pago:=v_res.total_pago+
    case when p_etapa='paga' and v_fatura.estado_fluxo<>'paga' and v_fatura.estado_pagamento<>'pago' then v_fatura.valor else 0 end;
  return jsonb_build_object(
    'aplicavel',true,'valor_contratual',v_res.valor_contratual,
    'aditamentos_aprovados',v_res.aditamentos_aprovados,'total_aprovado',v_res.total_aprovado,
    'total_faturado_atual',v_res.total_faturado,'total_pago_atual',v_res.total_pago,
    'total_faturado_projetado',v_proj_faturado,'total_pago_projetado',v_proj_pago,
    'ultrapassa_faturacao',v_proj_faturado>v_res.total_aprovado,
    'ultrapassa_pagamento',v_proj_pago>v_res.total_aprovado,
    'excesso_faturacao',greatest(v_proj_faturado-v_res.total_aprovado,0),
    'excesso_pagamento',greatest(v_proj_pago-v_res.total_aprovado,0)
  );
end;$function$

definitions.fn_importar_mapa_financeiro_xlsx(integer:
CREATE OR REPLACE FUNCTION public.fn_importar_mapa_financeiro_xlsx(p_ano integer, p_linhas jsonb, p_nome_ficheiro text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_linha jsonb;
  v_valor jsonb;
  v_mes integer;
  v_importadas integer := 0;
  v_obra_id uuid;
  v_debito_id uuid;
  v_categoria text;
  v_descricao text;
begin
  if not (
    public.fn_e_admin()
    or public.fn_e_financeiro()
  )
  then
    raise exception using
      errcode = '42501',
      message =
        'Sem permissão para importar o Mapa Financeiro.';
  end if;

  if p_ano not between 2000 and 2200
     or jsonb_typeof(p_linhas) <> 'array'
  then
    raise exception using
      errcode = '22023',
      message = 'Ano ou linhas de importação inválidos.';
  end if;

  for v_linha in
    select value
    from jsonb_array_elements(p_linhas)
  loop
    if v_linha ->> 'tipo' = 'obra' then
      v_obra_id :=
        nullif(v_linha ->> 'obra_id', '')::uuid;

      if not exists (
        select 1
        from public.obras o
        where o.id = v_obra_id
      )
      then
        raise exception using
          errcode = '23503',
          message = 'Obra inexistente no Mapa Financeiro.';
      end if;

      v_mes := 0;

      for v_valor in
        select value
        from jsonb_array_elements(v_linha -> 'meses')
      loop
        v_mes := v_mes + 1;

        if jsonb_typeof(v_valor) = 'number' then
          insert into public.mapa_financeiro_ajustes (
            obra_id,
            ano,
            mes,
            valor_calculado_referencia,
            valor_ajustado,
            motivo,
            atualizado_por,
            atualizado_em
          )
          values (
            v_obra_id,
            p_ano,
            v_mes,
            null,
            (v_valor #>> '{}')::numeric,
            'Importação Excel: ' || p_nome_ficheiro,
            public.fn_utilizador_atual_id(),
            now()
          )
          on conflict (obra_id, ano, mes)
          do update set
            valor_ajustado = excluded.valor_ajustado,
            motivo = excluded.motivo,
            atualizado_por = excluded.atualizado_por,
            atualizado_em = excluded.atualizado_em;
        end if;
      end loop;

    elsif v_linha ->> 'tipo' = 'despesa_fixa' then
      v_categoria := v_linha ->> 'categoria';

      if v_categoria not in (
        'remuneracoes_sede',
        'despesas_sede',
        'despesas_armazem'
      )
      then
        raise exception using
          errcode = '23514',
          message = 'Grupo de despesas fixas inválido.';
      end if;

      v_descricao :=
        'Importação Mapa Financeiro · ' || v_categoria;

      select id
      into v_debito_id
      from public.debitos_diretos
      where obra_id is null
        and categoria = v_categoria
        and descricao = v_descricao
      order by criado_em
      limit 1;

      if v_debito_id is null then
        insert into public.debitos_diretos (
          obra_id,
          descricao,
          categoria,
          valor_previsto,
          recorrencia,
          dia_mes,
          data_inicio,
          ativo,
          criado_por
        )
        values (
          null,
          v_descricao,
          v_categoria,
          0,
          'mensal',
          1,
          make_date(p_ano, 1, 1),
          true,
          public.fn_utilizador_atual_id()
        )
        returning id into v_debito_id;
      end if;

      v_mes := 0;

      for v_valor in
        select value
        from jsonb_array_elements(v_linha -> 'meses')
      loop
        v_mes := v_mes + 1;

        if jsonb_typeof(v_valor) = 'number' then
          insert into public.debitos_diretos_lancamentos (
            debito_direto_id,
            data,
            valor
          )
          values (
            v_debito_id,
            make_date(p_ano, v_mes, 1),
            (v_valor #>> '{}')::numeric
          )
          on conflict (debito_direto_id, data)
          do update set
            valor = excluded.valor;
        end if;
      end loop;
    end if;

    v_importadas := v_importadas + 1;
  end loop;

  perform public.fn_log_importacao_xlsx(
    'mapa_financeiro',
    p_nome_ficheiro,
    v_importadas,
    jsonb_build_object('ano', p_ano)
  );

  return jsonb_build_object(
    'importadas',
    v_importadas
  );
end;
$function$

definitions.fn_criar_rnc(uuid,date,uuid,text,text,te:
CREATE OR REPLACE FUNCTION public.fn_criar_rnc(p_obra_id uuid, p_data_deteccao date, p_fase_id uuid, p_local_ocorrencia text, p_descricao text, p_origem text, p_subempreitada_id uuid, p_gravidade text)
 RETURNS rnc
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_numero integer;
  v_rnc public.rnc;
begin
  if not (
    public.fn_pode_editar_obra(p_obra_id)
    or public.fn_e_encarregado_da_obra(p_obra_id)
  ) then
    raise exception using
      errcode = '42501',
      message = 'Sem permissão para criar RNC nesta obra.';
  end if;

  if nullif(btrim(p_descricao), '') is null then
    raise exception using
      errcode = '23514',
      message = 'A descrição é obrigatória.';
  end if;

  if p_origem not in (
    'execucao_propria',
    'subempreiteiro',
    'material',
    'projeto_especificacao',
    'outro'
  ) then
    raise exception using
      errcode = '23514',
      message = 'Origem inválida.';
  end if;

  if p_gravidade not in ('critica', 'maior', 'menor') then
    raise exception using
      errcode = '23514',
      message = 'Gravidade inválida.';
  end if;

  if p_fase_id is not null and not exists (
    select 1
    from public.fases f
    where f.id = p_fase_id
      and f.obra_id = p_obra_id
  ) then
    raise exception using
      errcode = '23503',
      message = 'A fase não pertence à obra indicada.';
  end if;

  if p_origem = 'subempreiteiro' then
    if p_subempreitada_id is null or not exists (
      select 1
      from public.subempreitadas s
      where s.id = p_subempreitada_id
        and s.obra_id = p_obra_id
    ) then
      raise exception using
        errcode = '23503',
        message = 'Selecione uma subempreitada válida desta obra.';
    end if;
  else
    p_subempreitada_id := null;
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('rnc:' || p_obra_id::text, 0)
  );

  select coalesce(max(numero), 0) + 1
    into v_numero
  from public.rnc
  where obra_id = p_obra_id;

  insert into public.rnc (
    obra_id,
    numero,
    fase_id,
    subempreitada_id,
    data_deteccao,
    local_ocorrencia,
    descricao,
    origem,
    gravidade,
    estado,
    reportado_por
  )
  values (
    p_obra_id,
    v_numero,
    p_fase_id,
    p_subempreitada_id,
    coalesce(p_data_deteccao, current_date),
    nullif(btrim(p_local_ocorrencia), ''),
    btrim(p_descricao),
    p_origem,
    p_gravidade,
    'aberto',
    public.fn_utilizador_atual_id()
  )
  returning * into v_rnc;

  return v_rnc;
end;
$function$

definitions.fn_guardar_precos_candidato_subempreitad:
CREATE OR REPLACE FUNCTION public.fn_guardar_precos_candidato_subempreitada(p_candidato_id uuid, p_precos jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_obra_id uuid;
  v_total numeric;
begin
  select consulta.obra_id
  into v_obra_id
  from public.consultas_subempreitada_candidatos candidato
  join public.consultas_subempreitada consulta
    on consulta.id = candidato.consulta_subempreitada_id
  where candidato.id = p_candidato_id;

  if not found then
    raise exception using errcode = 'P0002',
      message = 'Candidato não encontrado.';
  end if;

  if not public.fn_pode_editar_obra(v_obra_id) then
    raise exception using errcode = '42501',
      message = 'Sem permissão para editar esta consulta.';
  end if;

  if p_precos is null or jsonb_typeof(p_precos) <> 'array' then
    raise exception using errcode = '23514',
      message = 'A lista de preços é inválida.';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_precos)
      as preco(item_orcamento_id uuid, preco_unitario numeric)
    group by preco.item_orcamento_id
    having count(*) > 1
  ) then
    raise exception using errcode = '23514',
      message = 'A lista contém o mesmo artigo mais de uma vez.';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_precos)
      as preco(item_orcamento_id uuid, preco_unitario numeric)
    left join public.consultas_subempreitada_candidatos candidato
      on candidato.id = p_candidato_id
    left join public.consultas_subempreitada_itens consulta_item
      on consulta_item.consulta_subempreitada_id =
         candidato.consulta_subempreitada_id
     and consulta_item.item_orcamento_id = preco.item_orcamento_id
    left join public.itens_orcamento item
      on item.id = preco.item_orcamento_id
    where consulta_item.id is null
       or item.quantidade is null
       or item.quantidade <= 0
       or (
         preco.preco_unitario is not null
         and preco.preco_unitario < 0
       )
  ) then
    raise exception using errcode = '23514',
      message = 'Existe um preço inválido ou um artigo que não pertence à consulta.';
  end if;

  delete from public.consultas_subempreitada_candidatos_itens
  where candidato_id = p_candidato_id;

  insert into public.consultas_subempreitada_candidatos_itens (
    candidato_id,
    item_orcamento_id,
    preco_unitario,
    preco_total
  )
  select
    p_candidato_id,
    preco.item_orcamento_id,
    preco.preco_unitario,
    preco.preco_unitario * item.quantidade
  from jsonb_to_recordset(p_precos)
    as preco(item_orcamento_id uuid, preco_unitario numeric)
  join public.itens_orcamento item
    on item.id = preco.item_orcamento_id
  where preco.preco_unitario is not null;

  select coalesce(sum(preco_total), 0)
  into v_total
  from public.consultas_subempreitada_candidatos_itens
  where candidato_id = p_candidato_id;

  update public.consultas_subempreitada_candidatos
  set valor_total = v_total
  where id = p_candidato_id;

  return v_total;
end;
$function$

definitions.fn_mgo_validar_periodo_mao_obra(jsonb,uu:
CREATE OR REPLACE FUNCTION public.fn_mgo_validar_periodo_mao_obra(p_linha jsonb, p_colaborador uuid, p_obra uuid, p_id uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 v_tipo text:=coalesce(nullif(btrim(p_linha->>'tipo_registo'),''),'diario');
 v_data date:=(p_linha->>'data')::date;
 v_mes date:=nullif(p_linha->>'mes_referencia','')::date;
 v_horas numeric:=(p_linha->>'horas')::numeric;
 v_nome text; v_obra text; v_erro text; v_ausencia record;
begin
 select nome into v_nome from public.colaboradores where id=p_colaborador;
 select numero::text into v_obra from public.obras where id=p_obra;
 if v_tipo not in ('diario','mensal') then v_erro:='Tipo de registo deve ser diario ou mensal.';
 elsif v_data is null or v_horas is null or v_horas<0 then v_erro:='Data e horas não negativas são obrigatórias.';
 elsif v_tipo='mensal' then
   if v_mes is null or v_mes<>date_trunc('month',v_data)::date then
     v_erro:='Indique o primeiro dia do mês de referência, correspondente à data do lançamento.';
   elsif v_horas>extract(day from (v_mes+interval '1 month - 1 day'))*24 then
     v_erro:='Horas superiores à duração do mês.';
   elsif exists(select 1 from public.lancamentos_mao_obra l where l.colaborador_id=p_colaborador and l.obra_id=p_obra
     and l.id is distinct from p_id and date_trunc('month',l.data)=v_mes) then
     v_erro:='Já existem horas nesta obra/mês. Rever antes de somar um total mensal para evitar dupla contagem.';
   end if;
 else
   if v_mes is not null then v_erro:='Lançamento diário não deve ter mês de referência.';
   elsif v_horas>24 then v_erro:='Mais de 24 horas num lançamento diário; indique mensal explicitamente se for um total do mês.';
   else
     select a.tipo,a.estado into v_ausencia from public.ausencias a
       where a.colaborador_id=p_colaborador and a.data=v_data order by a.id limit 1;
     if found then v_erro:=format('Conflito com ausência: %s (%s).',v_ausencia.tipo,v_ausencia.estado);
     elsif exists(select 1 from public.lancamentos_mao_obra l where l.colaborador_id=p_colaborador and l.obra_id=p_obra
       and l.id is distinct from p_id and l.tipo_registo='mensal' and l.mes_referencia=date_trunc('month',v_data)::date) then
       v_erro:='Já existe total mensal nesta obra/mês; não somar ponto diário ao mesmo custo.';
     end if;
   end if;
 end if;
 if v_erro is null then return null; end if;
 return format('Linha %s · %s · Obra %s · %s: %s',coalesce(p_linha->>'linha','—'),v_nome,v_obra,v_data,v_erro);
end $function$

definitions.fn_criar_consulta_subempreitada(uuid,uui:
CREATE OR REPLACE FUNCTION public.fn_criar_consulta_subempreitada(p_obra_id uuid, p_fase_id uuid, p_trabalho text, p_item_ids uuid[])
 RETURNS consultas_subempreitada
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_consulta public.consultas_subempreitada%rowtype;
  v_total_pedido integer;
  v_total_valido integer;
begin
  if not public.fn_pode_editar_obra(p_obra_id) then
    raise exception using errcode = '42501',
      message = 'Sem permissão para criar consultas nesta obra.';
  end if;

  if nullif(btrim(p_trabalho), '') is null then
    raise exception using errcode = '23514',
      message = 'A especialidade é obrigatória.';
  end if;

  if p_item_ids is null or cardinality(p_item_ids) = 0 then
    raise exception using errcode = '23514',
      message = 'Selecione pelo menos um item do orçamento.';
  end if;

  if not exists (
    select 1
    from public.fases f
    where f.id = p_fase_id
      and f.obra_id = p_obra_id
  ) then
    raise exception using errcode = '23514',
      message = 'A fase selecionada não pertence a esta obra.';
  end if;

  select count(distinct requested.item_id)
  into v_total_pedido
  from unnest(p_item_ids) as requested(item_id);

  select count(distinct i.id)
  into v_total_valido
  from public.itens_orcamento i
  where i.id = any(p_item_ids)
    and i.fase_id = p_fase_id
    and i.quantidade > 0;

  if v_total_valido <> v_total_pedido then
    raise exception using
      errcode = '23514',
      message = 'Um ou mais itens não pertencem à fase/obra indicada ou não têm quantidade válida.';
  end if;

  insert into public.consultas_subempreitada (
    obra_id,
    fase_id,
    trabalho,
    data_pedido,
    estado
  )
  values (
    p_obra_id,
    p_fase_id,
    btrim(p_trabalho),
    current_date,
    'em_consulta'
  )
  returning * into v_consulta;

  insert into public.consultas_subempreitada_itens (
    consulta_subempreitada_id,
    item_orcamento_id
  )
  select
    v_consulta.id,
    requested.item_id
  from (
    select distinct unnest(p_item_ids) as item_id
  ) requested;

  return v_consulta;
end;
$function$

definitions.fn_confirmar_remocao_custo_estimado_sube:
CREATE OR REPLACE FUNCTION public.fn_confirmar_remocao_custo_estimado_subempreitada(p_subempreitada_id uuid)
 RETURNS planeamento_custos_componentes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
