definitions.fn_guardar_componente_custo(uuid,text,nu:
CREATE OR REPLACE FUNCTION public.fn_guardar_componente_custo(p_planeamento_item_id uuid, p_tipo text, p_valor_orcamentado numeric, p_estado_custo text, p_valor_real_pl numeric, p_item_orcamento_id uuid)
 RETURNS planeamento_custos_componentes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_obra_id uuid; v_item public.planeamento_itens%rowtype; v_row public.planeamento_custos_componentes%rowtype;
begin
  select * into v_item from public.planeamento_itens where id=p_planeamento_item_id;
  if not found then raise exception 'Tarefa de planeamento não encontrada.'; end if;
  select obra_id into v_obra_id from public.fases where id=v_item.fase_id;
  if not public.fn_e_diretor_obra(v_obra_id) then raise exception 'A composição do custo só pode ser alterada pelo Diretor de Obra ou Gerência.' using errcode='42501'; end if;
  if p_tipo not in ('PL','subempreitada') then raise exception 'Tipo de componente inválido.'; end if;
  if p_estado_custo not in ('orcamentado_nao_comprometido','em_consulta','adjudicado','em_execucao','concluido','cancelado') then raise exception 'Estado de custo inválido.'; end if;

  if p_item_orcamento_id is null then
    insert into public.planeamento_custos_componentes(planeamento_item_id,especialidade_id,tipo,item_orcamento_id,subempreitada_id,valor_orcamentado,valor_real_pl,estado_custo)
    values(v_item.id,v_item.especialidade_id,p_tipo,null,case when p_tipo='subempreitada' then v_item.subempreitada_id end,greatest(coalesce(p_valor_orcamentado,0),0),case when p_tipo='PL' then p_valor_real_pl end,p_estado_custo)
    on conflict (planeamento_item_id,tipo) where item_orcamento_id is null
    do update set especialidade_id=excluded.especialidade_id,subempreitada_id=excluded.subempreitada_id,
      valor_orcamentado=excluded.valor_orcamentado,valor_real_pl=excluded.valor_real_pl,
      estado_custo=excluded.estado_custo,atualizado_em=now() returning * into v_row;
  else
    insert into public.planeamento_custos_componentes(planeamento_item_id,especialidade_id,tipo,item_orcamento_id,subempreitada_id,valor_orcamentado,valor_real_pl,estado_custo)
    values(v_item.id,v_item.especialidade_id,p_tipo,p_item_orcamento_id,case when p_tipo='subempreitada' then v_item.subempreitada_id end,greatest(coalesce(p_valor_orcamentado,0),0),case when p_tipo='PL' then p_valor_real_pl end,p_estado_custo)
    on conflict (planeamento_item_id,tipo,item_orcamento_id) where item_orcamento_id is not null
    do update set especialidade_id=excluded.especialidade_id,subempreitada_id=excluded.subempreitada_id,
      valor_orcamentado=excluded.valor_orcamentado,valor_real_pl=excluded.valor_real_pl,
      estado_custo=excluded.estado_custo,atualizado_em=now() returning * into v_row;
  end if;
  return v_row;
end;
$function$

definitions.fn_atualizar_colaborador_ciclo_vida(uuid:
CREATE OR REPLACE FUNCTION public.fn_atualizar_colaborador_ciclo_vida(p_colaborador_id uuid, p_nome text, p_funcao text, p_data_admissao date, p_data_nascimento date DEFAULT NULL::date, p_data_saida date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_colaborador public.colaboradores%rowtype;
begin
  if not (
    public.fn_e_admin()
    or public.fn_e_administrativo()
  ) then
    raise exception
      'A gestão de colaboradores está reservada ao Administrativo e à Gerência.';
  end if;

  if nullif(btrim(p_nome), '') is null
     or nullif(btrim(p_funcao), '') is null
     or p_data_admissao is null then
    raise exception
      'Nome, função e data de admissão são obrigatórios.';
  end if;

  if p_data_saida is not null
     and p_data_saida < p_data_admissao then
    raise exception
      'A data de saída não pode ser anterior à data de admissão.';
  end if;

  perform 1 from public.colaboradores where id=p_colaborador_id for update;
  if not public.fn_medicina_pode_gerir(p_colaborador_id) then
    raise exception 'PERMISSION_DENIED: colaborador de outra empresa ou sem autorização.' using errcode='42501';
  end if;
  update public.colaboradores
  set
    nome = btrim(p_nome),
    funcao = btrim(p_funcao),
    data_admissao = p_data_admissao,
    data_nascimento = p_data_nascimento,
    data_saida = p_data_saida
  where id = p_colaborador_id
  returning * into v_colaborador;

  if v_colaborador.id is null then
    raise exception 'Colaborador não encontrado.';
  end if;

  if p_data_saida is not null then
    delete from public.alertas a
    where a.estado = 'pendente'
      and (
        (
          a.entidade_tipo = 'epis'
          and a.entidade_id in (
            select e.id
            from public.epis e
            where e.colaborador_id = p_colaborador_id
          )
        )

      );
  elsif to_regprocedure(
    'public.fn_verificar_alertas_vencimento()'
  ) is not null then
    perform public.fn_verificar_alertas_vencimento();
  end if;

  perform public.fn_medicina_reconciliar_alertas(p_colaborador_id);
  return to_jsonb(v_colaborador);
end;
$function$

definitions.fn_quadro_aplicar_interno(uuid,date,json:
CREATE OR REPLACE FUNCTION public.fn_quadro_aplicar_interno(p_colaborador_id uuid, p_data date, p_antes jsonb, p_depois jsonb, p_origem text, p_request_id uuid DEFAULT NULL::uuid, p_simular boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE u public.utilizadores; c public.colaboradores; q public.quadro_pessoal_alocacao;
 v_antes jsonb; v_revisao integer; v_row jsonb;
BEGIN
 SELECT * INTO u FROM public.utilizadores WHERE id=public.fn_utilizador_atual_id() AND ativo IS TRUE;
 IF u.id IS NULL OR u.empresa_id IS NULL THEN RAISE EXCEPTION 'PERMISSION_DENIED: sessão sem utilizador ativo.' USING ERRCODE='42501'; END IF;
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;
 PERFORM pg_advisory_xact_lock(61001,1);
 SELECT * INTO c FROM public.colaboradores WHERE id=p_colaborador_id AND empresa_id=u.empresa_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: colaborador de outra empresa ou inexistente.' USING ERRCODE='42501'; END IF;
 IF p_data IS NULL OR p_origem NOT IN('quadro','cadastro_rh','importacao_rh') THEN RAISE EXCEPTION 'VALIDATION_ERROR: data/origem inválida.'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_colaborador_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended(p_colaborador_id::text||':'||p_data::text,0));
 v_antes:=public.fn_quadro_dia_explicito(p_colaborador_id,p_data);
 IF v_antes IS DISTINCT FROM p_antes THEN RAISE EXCEPTION 'STALE_REVISION: alocação alterada; recarregue.'; END IF;
 IF jsonb_typeof(p_depois) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'VALIDATION_ERROR: alocações inválidas.'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_depois) a GROUP BY a->>'id' HAVING count(*)>1)
 THEN RAISE EXCEPTION 'VALIDATION_ERROR: IDs repetidos.'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_depois) a JOIN jsonb_array_elements(p_depois) b
 ON a->>'id'<b->>'id' WHERE a->>'periodo'='dia_inteiro' OR b->>'periodo'='dia_inteiro' OR a->>'periodo'=b->>'periodo')
 THEN RAISE EXCEPTION 'OVERLAP_CONFLICT: destinos simultâneos; legado requer revisão humana.'; END IF;
 -- Permissão em TODAS as origens e destinos; responsabilidade não é presença.
 FOR v_row IN SELECT value FROM jsonb_array_elements(p_antes||p_depois) LOOP
  IF NOT (public.fn_quadro_pode_gerir_v1(NULL) OR (p_origem IN('cadastro_rh','importacao_rh') AND public.fn_rh_empresa(false)=u.empresa_id)) AND
    (v_row->>'tipo_alocacao'<>'obra' OR NOT public.fn_quadro_minha_obra_v1((v_row->>'obra_id')::uuid))
  THEN RAISE EXCEPTION 'PERMISSION_DENIED: origem/destino fora da equipa autorizada.' USING ERRCODE='42501'; END IF;
 END LOOP;
 FOR v_row IN SELECT value FROM jsonb_array_elements(p_depois) LOOP
  q:=jsonb_populate_record(NULL::public.quadro_pessoal_alocacao,v_row);
  IF q.id IS NULL OR q.colaborador_id IS DISTINCT FROM p_colaborador_id OR q.data IS DISTINCT FROM p_data
   OR q.periodo IS NULL OR q.periodo NOT IN('manha','tarde','dia_inteiro')
   OR q.tipo_alocacao IS NULL OR q.tipo_alocacao NOT IN('obra','escritorio','garantia','pontual')
   OR (q.tipo_alocacao='obra' AND (q.obra_id IS NULL OR q.descricao_livre IS NOT NULL))
   OR (q.tipo_alocacao<>'obra' AND (q.obra_id IS NOT NULL OR nullif(btrim(q.descricao_livre),'') IS NULL))
  THEN RAISE EXCEPTION 'VALIDATION_ERROR: destino/período inválido.'; END IF;
  IF q.obra_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.obras o WHERE o.id=q.obra_id AND o.empresa_id=u.empresa_id)
  THEN RAISE EXCEPTION 'PERMISSION_DENIED: obra de outra empresa.' USING ERRCODE='42501'; END IF;
  IF EXISTS(SELECT 1 FROM public.quadro_pessoal_alocacao x WHERE x.id=q.id AND (x.colaborador_id<>p_colaborador_id OR x.data<>p_data))
  THEN RAISE EXCEPTION 'VALIDATION_ERROR: identidade de outra alocação.'; END IF;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_antes) b WHERE b=v_row) THEN
   IF c.data_admissao>p_data OR (c.data_saida IS NOT NULL AND c.data_saida<=p_data)
   THEN RAISE EXCEPTION 'VALIDATION_ERROR: colaborador indisponível nesta data.'; END IF;
   -- Mantém a proteção instalada: qualquer ausência registada bloqueia a nova alocação.
   IF EXISTS(SELECT 1 FROM public.ausencias a WHERE a.colaborador_id=p_colaborador_id AND a.data=p_data)
   THEN RAISE EXCEPTION 'ABSENCE_CONFLICT: colaborador de férias/ausente nesta data.'; END IF;
  END IF;
 END LOOP;
 IF p_simular THEN RETURN jsonb_build_object('allocations',p_depois,'changed',p_antes IS DISTINCT FROM p_depois); END IF;
 IF p_antes=p_depois THEN RETURN jsonb_build_object('allocations',p_antes,'changed',false); END IF;
 INSERT INTO public.quadro_escrita_interna VALUES(txid_current(),p_colaborador_id,p_data,u.id,p_origem,p_request_id);
 DELETE FROM public.quadro_pessoal_alocacao x WHERE x.colaborador_id=p_colaborador_id AND x.data=p_data
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_depois) d WHERE (d->>'id')::uuid=x.id);
 FOR v_row IN SELECT value FROM jsonb_array_elements(p_depois) LOOP
  q:=jsonb_populate_record(NULL::public.quadro_pessoal_alocacao,v_row);
  IF EXISTS(SELECT 1 FROM public.quadro_pessoal_alocacao x WHERE x.id=q.id) THEN
   UPDATE public.quadro_pessoal_alocacao x SET obra_id=q.obra_id,periodo=q.periodo,
     tipo_alocacao=q.tipo_alocacao,descricao_livre=q.descricao_livre
   WHERE x.id=q.id AND (x.obra_id,x.periodo,x.tipo_alocacao,x.descricao_livre)
     IS DISTINCT FROM (q.obra_id,q.periodo,q.tipo_alocacao,q.descricao_livre);
  ELSE
   INSERT INTO public.quadro_pessoal_alocacao(id,colaborador_id,obra_id,data,periodo,semana_inicio,tipo_alocacao,descricao_livre,criado_por)
   VALUES(q.id,p_colaborador_id,q.obra_id,p_data,q.periodo,date_trunc('week',p_data::timestamp)::date,q.tipo_alocacao,q.descricao_livre,u.id);
  END IF;
 END LOOP;
 -- Um alerta por par origem/destino e destinatário, incluindo split/merge dos períodos.
 FOR v_row IN SELECT jsonb_build_object('origem',b->>'obra_id','destino',a->>'obra_id','id',min(a->>'id'))
 FROM jsonb_array_elements(p_depois) a LEFT JOIN jsonb_array_elements(p_antes) b
 ON b->>'periodo'='dia_inteiro' OR a->>'periodo'='dia_inteiro' OR b->>'periodo'=a->>'periodo'
 WHERE (b->>'obra_id') IS DISTINCT FROM (a->>'obra_id')
 GROUP BY b->>'obra_id',a->>'obra_id' LOOP
  PERFORM public.fn_quadro_notificar_controlado_v1(p_colaborador_id,p_data,(v_row->>'origem')::uuid,(v_row->>'destino')::uuid,(v_row->>'id')::uuid);
 END LOOP;
 DELETE FROM public.quadro_escrita_interna WHERE transacao=txid_current() AND colaborador_id=p_colaborador_id AND data=p_data;
 INSERT INTO public.quadro_dias_revisoes(colaborador_id,data,revisao,obras_visiveis)
 VALUES(p_colaborador_id,p_data,1,ARRAY(SELECT DISTINCT (r->>'obra_id')::uuid FROM jsonb_array_elements(p_antes||p_depois) r WHERE r->>'obra_id' IS NOT NULL))
 ON CONFLICT(colaborador_id,data) DO UPDATE SET revisao=quadro_dias_revisoes.revisao+1,
 obras_visiveis=ARRAY(SELECT DISTINCT x FROM unnest(quadro_dias_revisoes.obras_visiveis||EXCLUDED.obras_visiveis) x)
 RETURNING revisao INTO v_revisao;
 RETURN jsonb_build_object('allocations',public.fn_quadro_dia_explicito(p_colaborador_id,p_data),'revision',v_revisao,'changed',true);
END $function$

definitions.fn_alterar_responsavel_viatura(integer,u:
CREATE OR REPLACE FUNCTION public.fn_alterar_responsavel_viatura(p_version integer, p_viatura_id uuid, p_novo_colaborador_id uuid, p_revisao_esperada integer, p_request_id uuid, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v public.viaturas%ROWTYPE;
  c public.colaboradores%ROWTYPE;
  h public.viaturas_atribuicoes_historico%ROWTYPE;
  v_user uuid;
  v_motivo text := nullif(btrim(p_motivo), '');
  v_contexto text;
  v_idempotent boolean := false;
BEGIN
  IF p_version IS DISTINCT FROM 1 OR p_viatura_id IS NULL
     OR p_request_id IS NULL OR p_revisao_esperada IS NULL OR p_revisao_esperada < 0 THEN
    RAISE EXCEPTION 'VALIDATION_FAILED: versão ou parâmetros inválidos.' USING ERRCODE = '22023';
  END IF;
  v_user := public.fn_utilizador_atual_id();
  IF v_user IS NULL OR NOT (public.fn_e_admin() OR public.fn_e_administrativo()) THEN
    RAISE EXCEPTION 'FORBIDDEN: operação reservada a Administrativo/Gerência.' USING ERRCODE = '42501';
  END IF;

  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'STALE_REVISION: repita a atribuição em READ COMMITTED.' USING ERRCODE = '40001';
  END IF;

  -- Serializa o mesmo pedido, incluindo tentativas sobre viaturas diferentes.
  -- Colisões do hash apenas serializam pedidos distintos; UNIQUE é a garantia final.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_request_id::text, 0));
  SELECT * INTO v FROM public.viaturas WHERE id = p_viatura_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'VALIDATION_FAILED: viatura não encontrada.' USING ERRCODE = '22023';
  END IF;

  -- Replay antes do teste de revisão: devolve o resultado original, mesmo após outras trocas.
  SELECT * INTO h FROM public.viaturas_atribuicoes_historico WHERE request_id = p_request_id;
  IF FOUND THEN
    IF h.viatura_id IS DISTINCT FROM p_viatura_id
       OR h.colaborador_novo_id IS DISTINCT FROM p_novo_colaborador_id
       OR h.revisao_anterior IS DISTINCT FROM p_revisao_esperada
       OR h.motivo IS DISTINCT FROM v_motivo
       OR h.alterado_por IS DISTINCT FROM v_user THEN
      RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: request_id reutilizado com outro pedido ou autor.' USING ERRCODE = '22023';
    END IF;
    v_idempotent := true;
  ELSE
    IF v.atribuicao_revisao IS DISTINCT FROM p_revisao_esperada THEN
      RAISE EXCEPTION 'STALE_REVISION: atribuição alterada; atualize antes de repetir.' USING ERRCODE = '40001';
    END IF;
    IF p_novo_colaborador_id IS NOT NULL THEN
      -- Impede saída/mudança de empresa concorrente durante a validação e gravação.
      SELECT * INTO c FROM public.colaboradores WHERE id = p_novo_colaborador_id FOR SHARE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'VALIDATION_FAILED: colaborador não encontrado.' USING ERRCODE = '22023';
      END IF;
      IF c.empresa_id IS DISTINCT FROM v.empresa_id OR c.data_saida IS NOT NULL THEN
        RAISE EXCEPTION 'VALIDATION_FAILED: colaborador deve estar ativo e pertencer à empresa da viatura.' USING ERRCODE = '22023';
      END IF;
    END IF;
    IF v.colaborador_atribuido_id IS NOT DISTINCT FROM p_novo_colaborador_id THEN
      RAISE EXCEPTION 'VALIDATION_FAILED: responsável já corresponde ao pedido.' USING ERRCODE = '22023';
    END IF;
    IF v.atribuicao_revisao = 2147483647 THEN
      RAISE EXCEPTION 'VALIDATION_FAILED: limite da revisão atingido.' USING ERRCODE = '22023';
    END IF;

    v_contexto := coalesce(current_setting('primeline.atribuicao_viatura_rpc', true), '');
    PERFORM set_config('primeline.atribuicao_viatura_rpc', 'on', true);
    UPDATE public.viaturas
      SET colaborador_atribuido_id = p_novo_colaborador_id,
          atribuicao_revisao = atribuicao_revisao + 1
      WHERE id = v.id;
    -- O trigger existente trata os alertas pendentes. Não duplicar essa lógica.
    INSERT INTO public.viaturas_atribuicoes_historico (
      viatura_id, colaborador_anterior_id, colaborador_novo_id,
      revisao_anterior, revisao_nova, alterado_por, request_id, motivo
    ) VALUES (
      v.id, v.colaborador_atribuido_id, p_novo_colaborador_id,
      v.atribuicao_revisao, v.atribuicao_revisao + 1, v_user, p_request_id, v_motivo
    ) RETURNING * INTO h;
    PERFORM set_config('primeline.atribuicao_viatura_rpc', v_contexto, true);
  END IF;

  RETURN jsonb_build_object(
    'version', 1, 'committed', true, 'idempotent', v_idempotent,
    'viatura_id', h.viatura_id,
    'colaborador_anterior_id', h.colaborador_anterior_id,
    'colaborador_novo_id', h.colaborador_novo_id,
    'atribuicao_revisao', h.revisao_nova, 'historico_id', h.id
  );
END;
$function$

definitions.fn_criar_subempreitada_do_comparativo(uu:
CREATE OR REPLACE FUNCTION public.fn_criar_subempreitada_do_comparativo(p_mapa_id uuid, p_proposta_id uuid, p_fase_id uuid, p_data_inicio_prevista date, p_data_fim_prevista date, p_condicao_pagamento text DEFAULT NULL::text)
 RETURNS subempreitadas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_mapa public.mapas_comparativos;
  v_proposta public.comparativo_propostas;
  v_sub public.subempreitadas;
begin
  select *
  into v_mapa
  from public.mapas_comparativos
  where id = p_mapa_id
  for update;

  if not found then
    raise exception 'Mapa comparativo não encontrado.';
  end if;

  if not public.fn_pode_editar_obra(v_mapa.obra_id) then
    raise exception 'Sem permissão para adjudicar nesta obra.'
      using errcode = '42501';
  end if;

  if exists (
    select 1
    from public.subempreitadas
    where mapa_comparativo_id = p_mapa_id
  ) then
    raise exception 'Este mapa já originou uma subempreitada.'
      using errcode = '23505';
  end if;

  if v_mapa.valor_adjudicado_real is null then
    raise exception
      'Preencha o Valor Adjudicado Real antes de criar a subempreitada.'
      using errcode = '23514';
  end if;

  select *
  into v_proposta
  from public.comparativo_propostas
  where id = p_proposta_id
    and mapa_id = p_mapa_id;

  if not found then
    raise exception 'A proposta não pertence a este mapa.'
      using errcode = '23514';
  end if;

  if not exists (
    select 1
    from public.fases
    where id = p_fase_id
      and obra_id = v_mapa.obra_id
  ) then
    raise exception 'A fase não pertence a esta obra.'
      using errcode = '23514';
  end if;

  insert into public.subempreitadas (
    obra_id,
    fase_id,
    fornecedor_id,
    especialidade,
    valor_adjudicado,
    estado,
    data_inicio_prevista,
    data_fim_prevista,
    condicao_pagamento,
    mapa_comparativo_id
  )
  values (
    v_mapa.obra_id,
    p_fase_id,
    v_proposta.fornecedor_id,
    v_mapa.especialidade,
    v_mapa.valor_adjudicado_real,
    'em_execucao',
    p_data_inicio_prevista,
    p_data_fim_prevista,
    p_condicao_pagamento,
    p_mapa_id
  )
  returning * into v_sub;

  return v_sub;
end;
$function$

definitions.fn_editar_fornecedor_diretorio(uuid,text:
CREATE OR REPLACE FUNCTION public.fn_editar_fornecedor_diretorio(p_fornecedor_id uuid, p_nome text, p_nif text, p_email text, p_telefone text, p_representante text, p_notas text, p_estado_confianca text)
 RETURNS fornecedores
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_fornecedor public.fornecedores;
  v_empresa_id uuid;
  v_nif_normalizado text := nullif(regexp_replace(coalesce(p_nif, ''), '[^0-9A-Za-z]', '', 'g'), '');
begin
  if not (public.fn_e_admin() or public.fn_e_administrativo()) then
    raise exception 'SÃ³ o Administrativo ou a GestÃ£o da Plataforma pode editar fornecedores.' using errcode = '42501';
  end if;
  if nullif(btrim(p_nome), '') is null then
    raise exception 'O nome do fornecedor Ã© obrigatÃ³rio.';
  end if;
  if nullif(btrim(p_email), '') is not null and position('@' in btrim(p_email)) < 2 then
    raise exception 'O email indicado nÃ£o Ã© vÃ¡lido.';
  end if;

  select f.empresa_id into v_empresa_id
  from public.fornecedores f
  join public.utilizadores u on u.id = public.fn_utilizador_atual_id()
  where f.id = p_fornecedor_id
    and f.empresa_id = u.empresa_id
    and coalesce(u.ativo, true)
  for update of f;
  if not found then
    raise exception 'Fornecedor inexistente ou fora da sua empresa.';
  end if;

  if v_nif_normalizado is not null and exists (
    select 1 from public.fornecedores f
    where f.empresa_id = v_empresa_id
      and f.id <> p_fornecedor_id
      and regexp_replace(coalesce(f.nif, ''), '[^0-9A-Za-z]', '', 'g') = v_nif_normalizado
  ) then
    raise exception 'JÃ¡ existe outra empresa com este NIF. Reveja os possÃ­veis duplicados antes de guardar.';
  end if;

  update public.fornecedores
  set nome = btrim(p_nome),
      nif = nullif(btrim(p_nif), ''),
      email = nullif(lower(btrim(p_email)), ''),
      telefone = nullif(btrim(p_telefone), ''),
      representante = nullif(btrim(p_representante), ''),
      notas = nullif(btrim(p_notas), ''),
      estado_confianca = coalesce(nullif(btrim(p_estado_confianca), ''), estado_confianca)
  where id = p_fornecedor_id
  returning * into v_fornecedor;

  return v_fornecedor;
end;
$function$

definitions.fn_editar_fornecedor_diretorio_v2(uuid,t:
CREATE OR REPLACE FUNCTION public.fn_editar_fornecedor_diretorio_v2(p_fornecedor_id uuid, p_nome text, p_tipo_entidade text, p_nif text, p_email text, p_telefone text, p_representante text, p_notas text, p_estado_confianca text)
 RETURNS fornecedores
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_fornecedor public.fornecedores;
begin
  if p_tipo_entidade not in ('fornecedor', 'subempreiteiro', 'ambos') then
    raise exception 'Selecione Fornecedor, Subempreiteiro ou Fornecedor e Subempreiteiro.';
  end if;
  if p_estado_confianca not in (
    'ativo', 'recomendado', 'recomendado_com_ressalvas', 'nao_avaliado',
    'nao_recomendado', 'bloqueado', 'inativo'
  ) then
    raise exception 'O estado de confianÃ§a indicado nÃ£o Ã© vÃ¡lido.';
  end if;

  select * into v_fornecedor
  from public.fn_editar_fornecedor_diretorio(
    p_fornecedor_id, p_nome, p_nif, p_email, p_telefone,
    p_representante, p_notas, p_estado_confianca
  );

  update public.fornecedores
  set tipo_entidade = p_tipo_entidade
  where id = p_fornecedor_id
  returning * into v_fornecedor;

  return v_fornecedor;
end;
$function$

definitions.fn_medicina_guardar_interno(integer,text:
CREATE OR REPLACE FUNCTION public.fn_medicina_guardar_interno(p_version integer, p_operacao text, p_colaborador_id uuid, p_consulta_id uuid, p_data_consulta date, p_resultado text, p_proxima_consulta date, p_revisao_esperada integer, p_request_id uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_actor uuid:=public.fn_utilizador_atual_id(); v_c uuid; v_empresa uuid;
 v_old public.medicina_trabalho; v_new public.medicina_trabalho; v_replay public.medicina_operacoes;
 v_pedido jsonb; v_result jsonb; v_h uuid:=gen_random_uuid(); v_flag text;
BEGIN
 IF p_version IS DISTINCT FROM 1 OR p_request_id IS NULL
 OR p_operacao IS NULL OR p_operacao NOT IN ('registar','corrigir','anular') THEN
  RAISE EXCEPTION 'VALIDATION_FAILED: versão, operação ou request_id inválido.' USING ERRCODE='22023';
 END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'STALE_REVISION: repetir em READ COMMITTED.' USING ERRCODE='40001';
 END IF;
 v_c:=p_colaborador_id;
 IF p_operacao<>'registar' THEN
  SELECT colaborador_id INTO v_c FROM public.medicina_trabalho WHERE id=p_consulta_id;
 END IF;
 IF NOT public.fn_medicina_pode_gerir(v_c) THEN
  RAISE EXCEPTION 'PERMISSION_DENIED: Medicina reservada ao RH autorizado da empresa.' USING ERRCODE='42501';
 END IF;
 v_pedido:=jsonb_build_object('version',p_version,'operacao',p_operacao,'colaborador_id',v_c,
  'consulta_id',p_consulta_id,'data_consulta',p_data_consulta,'resultado',p_resultado,
  'proxima_consulta',p_proxima_consulta,'revisao_esperada',p_revisao_esperada,'motivo',p_motivo,'autor',v_actor);
 PERFORM pg_advisory_xact_lock(hashtextextended('medicina:'||p_request_id::text,0));
 -- Revalidar autorização com a pessoa bloqueada: pode ter mudado de empresa
 -- enquanto esperávamos. O replay também não pode devolver dados de outra empresa.
 SELECT empresa_id INTO v_empresa FROM public.colaboradores WHERE id=v_c FOR UPDATE;
 IF NOT FOUND OR NOT public.fn_medicina_pode_gerir(v_c) THEN
  RAISE EXCEPTION 'PERMISSION_DENIED: autorização alterada durante a operação.' USING ERRCODE='42501';
 END IF;
 SELECT * INTO v_replay FROM public.medicina_operacoes WHERE request_id=p_request_id;
 IF FOUND THEN
  IF v_replay.empresa_id IS DISTINCT FROM v_empresa THEN
   RAISE EXCEPTION 'PERMISSION_DENIED: operação histórica pertence a outra empresa.' USING ERRCODE='42501';
  END IF;
  IF v_replay.pedido IS DISTINCT FROM v_pedido THEN
   RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: request_id usado com pedido diferente.' USING ERRCODE='22023';
  END IF;
  RETURN v_replay.resposta||jsonb_build_object('idempotent',true);
 END IF;
 IF p_operacao<>'registar' THEN
  SELECT * INTO v_old FROM public.medicina_trabalho WHERE id=p_consulta_id FOR UPDATE;
  IF v_old.revisao IS DISTINCT FROM p_revisao_esperada THEN
   RAISE EXCEPTION 'STALE_REVISION: consulta alterada entretanto.' USING ERRCODE='40001';
  END IF;
  IF nullif(btrim(p_motivo),'') IS NULL THEN
   RAISE EXCEPTION 'VALIDATION_FAILED: motivo obrigatório para correção/anulação.' USING ERRCODE='22023';
  END IF;
 END IF;
 v_flag:=current_setting('primeline.medicina_rpc',true);
 PERFORM set_config('primeline.medicina_rpc','on',true);
 IF p_operacao='registar' THEN
  INSERT INTO public.medicina_trabalho(colaborador_id,data_ultima_consulta,resultado,data_proxima_consulta,registado_por,request_id)
  VALUES(v_c,p_data_consulta,p_resultado,p_proxima_consulta,v_actor,p_request_id) RETURNING * INTO v_new;
 ELSIF p_operacao='corrigir' THEN
  UPDATE public.medicina_trabalho SET data_ultima_consulta=p_data_consulta,resultado=p_resultado,
   data_proxima_consulta=p_proxima_consulta,revisao=revisao+1 WHERE id=p_consulta_id RETURNING * INTO v_new;
 ELSE
  UPDATE public.medicina_trabalho SET anulado_em=now(),anulado_por=v_actor,revisao=revisao+1
  WHERE id=p_consulta_id RETURNING * INTO v_new;
 END IF;
 PERFORM set_config('primeline.medicina_rpc',coalesce(v_flag,''),true);
 v_result:=jsonb_build_object('version',1,'committed',true,'idempotent',false,
  'consulta',to_jsonb(v_new),'historico_id',v_h);
 INSERT INTO public.medicina_operacoes(id,consulta_id,colaborador_id,empresa_id,operacao,autor_id,
  request_id,pedido,motivo,antes,depois,resposta)
 VALUES(v_h,v_new.id,v_c,v_empresa,p_operacao,v_actor,p_request_id,v_pedido,p_motivo,
  CASE WHEN p_operacao='registar' THEN NULL ELSE to_jsonb(v_old) END,to_jsonb(v_new),v_result);
 PERFORM public.fn_medicina_reconciliar_alertas(v_c);
 RETURN v_result;
END $function$

definitions.fn_editar_fatura_pendente(uuid,uuid,text:
CREATE OR REPLACE FUNCTION public.fn_editar_fatura_pendente(p_fatura_id uuid, p_obra_id uuid, p_tipo_origem text, p_fornecedor_id uuid, p_subempreitada_id uuid, p_numero_doc text, p_data_fatura date, p_valor numeric, p_condicao_pagamento text, p_data_vencimento date, p_itens jsonb DEFAULT '[]'::jsonb)
 RETURNS faturas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_fatura public.faturas;
  v_utilizador_id uuid := public.fn_utilizador_atual_id();
  v_item jsonb;
  v_quantidade numeric;
  v_valor_unitario numeric;
  v_valor_total numeric;
  v_desconto_percentual numeric;
  v_valor_desconto numeric;
  v_foi_devolvida boolean;
begin
  select * into v_fatura from public.faturas where id = p_fatura_id for update;
  if not found or v_fatura.estado_aprovacao <> 'pendente' then
    raise exception 'A fatura jÃ¡ nÃ£o estÃ¡ pendente e nÃ£o pode ser editada.';
  end if;
  v_foi_devolvida := v_fatura.estado_fluxo = 'devolvida_administrativo';

  if not public.fn_e_admin()
     and not (public.fn_e_administrativo() and (
       v_foi_devolvida or (v_fatura.criado_por is not null and v_fatura.criado_por = v_utilizador_id)
     )) then
    raise exception 'SÃ³ o Administrativo responsÃ¡vel pela correÃ§Ã£o ou a GerÃªncia pode editar esta fatura.';
  end if;

  if p_obra_id is null or p_fornecedor_id is null
     or nullif(btrim(p_numero_doc), '') is null or p_data_fatura is null
     or p_valor is null or p_valor <= 0 then
    raise exception 'Preencha obra, fornecedor, nÃºmero, data e valor da fatura.';
  end if;
  if p_tipo_origem not in ('subempreitada', 'material', 'estaleiro') then
    raise exception 'Tipo de despesa invÃ¡lido.';
  end if;
  if p_condicao_pagamento not in ('imediato', '15_dias', '30_dias', 'outra_data') then
    raise exception 'CondiÃ§Ã£o de pagamento invÃ¡lida.';
  end if;
  if p_condicao_pagamento = 'outra_data' and p_data_vencimento is null then
    raise exception 'Indique a data de vencimento para a opÃ§Ã£o Outra data.';
  end if;
  if p_condicao_pagamento <> 'outra_data' and p_data_vencimento is not null then
    raise exception 'A data manual sÃ³ pode ser usada com a opÃ§Ã£o Outra data.';
  end if;
  if p_tipo_origem = 'subempreitada' and p_subempreitada_id is not null and not exists (
    select 1 from public.subempreitadas s
    where s.id = p_subempreitada_id and s.obra_id = p_obra_id
      and s.fornecedor_id = p_fornecedor_id
  ) then
    raise exception 'A subempreitada nÃ£o corresponde Ã  obra e ao fornecedor selecionados.';
  elsif p_tipo_origem <> 'subempreitada' and p_subempreitada_id is not null then
    raise exception 'Faturas de material ou estaleiro nÃ£o podem ter subempreitada associada.';
  end if;

  update public.faturas
  set obra_id = p_obra_id,
      tipo_origem = p_tipo_origem,
      fornecedor_id = p_fornecedor_id,
      subempreitada_id = p_subempreitada_id,
      numero_doc = btrim(p_numero_doc),
      data_fatura = p_data_fatura,
      valor = p_valor,
      condicao_pagamento = p_condicao_pagamento,
      data_vencimento = case when p_condicao_pagamento = 'outra_data' then p_data_vencimento else null end,
      estado_fluxo = case when v_foi_devolvida then 'recebida' else estado_fluxo end,
      observacao_devolucao = case when v_foi_devolvida then null else observacao_devolucao end,
      devolvido_por = case when v_foi_devolvida then null else devolvido_por end,
      devolvido_em = case when v_foi_devolvida then null else devolvido_em end
  where id = p_fatura_id
  returning * into v_fatura;

  delete from public.faturas_itens where fatura_id = p_fatura_id;
  if p_tipo_origem = 'material' then
    if jsonb_typeof(coalesce(p_itens, '[]'::jsonb)) <> 'array'
       or jsonb_array_length(coalesce(p_itens, '[]'::jsonb)) = 0 then
      raise exception 'Uma fatura de material exige pelo menos um artigo.';
    end if;
    for v_item in select value from jsonb_array_elements(p_itens)
    loop
      v_quantidade := nullif(v_item ->> 'quantidade', '')::numeric;
      v_valor_unitario := nullif(v_item ->> 'valor_unitario', '')::numeric;
      v_valor_total := nullif(v_item ->> 'valor_total', '')::numeric;
      v_desconto_percentual := nullif(v_item ->> 'desconto_percentual', '')::numeric;
      v_valor_desconto := nullif(v_item ->> 'valor_desconto', '')::numeric;
      if nullif(btrim(v_item ->> 'designacao'), '') is null
         or nullif(btrim(v_item ->> 'unidade'), '') is null
         or v_quantidade is null or v_quantidade <= 0
         or v_valor_unitario is null or v_valor_unitario < 0
         or v_valor_total is null or v_valor_total < 0
         or (v_desconto_percentual is not null and (v_desconto_percentual < 0 or v_desconto_percentual > 100))
         or (v_valor_desconto is not null and v_valor_desconto < 0) then
        raise exception 'Existe um artigo de material incompleto ou invÃ¡lido.';
      end if;
      insert into public.faturas_itens (
        fatura_id, designacao, unidade, quantidade, valor_unitario, valor_total,
        desconto_percentual, valor_desconto
      ) values (
        p_fatura_id, btrim(v_item ->> 'designacao'), btrim(v_item ->> 'unidade'),
        v_quantidade, v_valor_unitario, v_valor_total,
        v_desconto_percentual, v_valor_desconto
      );
    end loop;
  end if;
  return v_fatura;
end;
$function$

definitions.fn_criar_obra_de_modelo(uuid,text,text,t:
CREATE OR REPLACE FUNCTION public.fn_criar_obra_de_modelo(p_modelo_obra_id uuid, p_numero text, p_nome text, p_cliente text DEFAULT NULL::text, p_morada text DEFAULT NULL::text, p_tipo text DEFAULT NULL::text, p_modalidade text DEFAULT NULL::text, p_diretor_obra_id uuid DEFAULT NULL::uuid, p_situacao text DEFAULT 'planeamento'::text, p_data_inicio date DEFAULT NULL::date, p_data_fim_prevista date DEFAULT NULL::date, p_copiar_orcamento boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_obra public.obras%rowtype;
  v_fase record;
  v_fase_nova_id uuid;
  v_total_fases integer := 0;
  v_total_itens integer := 0;
  v_itens_inseridos integer := 0;
  v_colunas_itens text;
begin
  if not public.fn_e_admin() then
    raise exception 'A criação de obras por modelo está reservada à Gerência.';
  end if;

  if p_modelo_obra_id is null or not exists (
    select 1 from public.obras where id = p_modelo_obra_id
  ) then
    raise exception 'A obra-modelo selecionada não existe.';
  end if;

  if nullif(btrim(p_numero), '') is null or nullif(btrim(p_nome), '') is null then
    raise exception 'Número e designação da nova obra são obrigatórios.';
  end if;

  if p_data_inicio is not null and p_data_fim_prevista is not null
     and p_data_fim_prevista < p_data_inicio then
    raise exception 'A data de fim prevista não pode ser anterior à data de início.';
  end if;

  if exists (
    select 1 from public.obras
    where empresa_id = '73fb13c8-d29f-4192-a506-4ca243343add'::uuid
      and lower(btrim(numero::text)) = lower(btrim(p_numero))
  ) then
    raise exception 'Já existe uma obra com este número.';
  end if;

  insert into public.obras (
    empresa_id, numero, nome, cliente, morada, tipo, modalidade,
    diretor_obra_id, situacao, data_inicio, data_fim_prevista
  ) values (
    '73fb13c8-d29f-4192-a506-4ca243343add'::uuid,
    btrim(p_numero), btrim(p_nome), nullif(btrim(p_cliente), ''),
    nullif(btrim(p_morada), ''), nullif(btrim(p_tipo), ''),
    nullif(btrim(p_modalidade), ''), p_diretor_obra_id,
    coalesce(nullif(btrim(p_situacao), ''), 'planeamento'),
    p_data_inicio, p_data_fim_prevista
  ) returning * into v_obra;

  -- Apenas campos descritivos são elegíveis para copiar do orçamento.
  select string_agg(quote_ident(c.column_name), ', ' order by c.ordinal_position)
    into v_colunas_itens
  from information_schema.columns c
  where c.table_schema = 'public'
    and c.table_name = 'itens_orcamento'
    and c.column_name = any(array[
      'codigo', 'descricao', 'designacao', 'unidade', 'categoria',
      'especialidade', 'capitulo', 'subcapitulo', 'ordem'
    ]);

  for v_fase in
    select id, codigo, descricao
    from public.fases
    where obra_id = p_modelo_obra_id
    order by codigo, descricao
  loop
    v_fase_nova_id := gen_random_uuid();
    insert into public.fases (id, obra_id, codigo, descricao)
    values (v_fase_nova_id, v_obra.id, v_fase.codigo, v_fase.descricao);
    v_total_fases := v_total_fases + 1;

    if to_regclass('public.planeamento_fases_resumo') is not null
       and exists (select 1 from public.planeamento_fases_resumo where fase_id = v_fase.id) then
      insert into public.planeamento_fases_resumo (fase_id)
      values (v_fase_nova_id);
    end if;

    if coalesce(p_copiar_orcamento, true) and v_colunas_itens is not null then
      execute format(
        'insert into public.itens_orcamento (id, fase_id, %1$s) '
        'select gen_random_uuid(), $1, %1$s from public.itens_orcamento where fase_id = $2',
        v_colunas_itens
      ) using v_fase_nova_id, v_fase.id;
      get diagnostics v_itens_inseridos = row_count;
      v_total_itens := v_total_itens + v_itens_inseridos;
    end if;
  end loop;

  return jsonb_build_object(
    'obra', to_jsonb(v_obra),
    'fases_copiadas', v_total_fases,
    'itens_orcamento_copiados', v_total_itens
  );
end;
$function$

definitions.fn_guardar_cadastro_fornecedor(uuid,text:
CREATE OR REPLACE FUNCTION public.fn_guardar_cadastro_fornecedor(p_fornecedor_id uuid, p_nome text, p_tipo_entidade text, p_nif text, p_email text, p_telefone text, p_representante text, p_notas text, p_estado_confianca text, p_zonas text[] DEFAULT '{}'::text[], p_especialidades uuid[] DEFAULT '{}'::uuid[], p_nova_especialidade text DEFAULT NULL::text)
 RETURNS fornecedores
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_fornecedor public.fornecedores;
  v_fornecedor_id uuid := p_fornecedor_id;
  v_empresa_id uuid;
  v_nome_normalizado text := lower(regexp_replace(btrim(coalesce(p_nome, '')), '[[:space:]]+', ' ', 'g'));
  v_nif_normalizado text := nullif(regexp_replace(coalesce(p_nif, ''), '[^0-9A-Za-z]', '', 'g'), '');
  v_especialidades uuid[] := coalesce(p_especialidades, '{}'::uuid[]);
  v_especialidade_id uuid;
begin
  if not (public.fn_e_admin() or public.fn_e_administrativo()) then
    raise exception 'SÃ³ o Administrativo ou a GestÃ£o da Plataforma pode editar o diretÃ³rio.' using errcode = '42501';
  end if;

  if nullif(v_nome_normalizado, '') is null then
    raise exception 'O nome do fornecedor ou subempreiteiro Ã© obrigatÃ³rio.';
  end if;
  if p_tipo_entidade not in ('fornecedor', 'subempreiteiro', 'ambos') then
    raise exception 'Selecione Fornecedor, Subempreiteiro ou Fornecedor e Subempreiteiro.';
  end if;
  if p_estado_confianca not in (
    'ativo', 'recomendado', 'recomendado_com_ressalvas', 'nao_avaliado',
    'nao_recomendado', 'bloqueado', 'inativo'
  ) then
    raise exception 'O estado de confianÃ§a indicado nÃ£o Ã© vÃ¡lido.';
  end if;
  if nullif(btrim(p_email), '') is not null and position('@' in btrim(p_email)) < 2 then
    raise exception 'O email indicado nÃ£o Ã© vÃ¡lido.';
  end if;

  select u.empresa_id into v_empresa_id
  from public.utilizadores u
  where u.id = public.fn_utilizador_atual_id()
    and coalesce(u.ativo, true);
  if v_empresa_id is null then
    raise exception 'Utilizador sem empresa ativa.' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtext(v_empresa_id::text), hashtext(v_nome_normalizado));

  if exists (
    select 1 from public.fornecedores f
    where f.empresa_id = v_empresa_id
      and (v_fornecedor_id is null or f.id <> v_fornecedor_id)
      and lower(regexp_replace(btrim(coalesce(f.nome, '')), '[[:space:]]+', ' ', 'g')) = v_nome_normalizado
  ) then
    raise exception 'JÃ¡ existe um cadastro com este nome. Abra o registo existente para o rever ou completar.';
  end if;

  if v_nif_normalizado is not null and exists (
    select 1 from public.fornecedores f
    where f.empresa_id = v_empresa_id
      and (v_fornecedor_id is null or f.id <> v_fornecedor_id)
      and regexp_replace(coalesce(f.nif, ''), '[^0-9A-Za-z]', '', 'g') = v_nif_normalizado
  ) then
    raise exception 'JÃ¡ existe um cadastro com este NIF. Abra o registo existente para o rever ou completar.';
  end if;

  if exists (
    select 1
    from unnest(v_especialidades) as selecionada(especialidade_id)
    left join public.especialidades e
      on e.id = selecionada.especialidade_id
    where e.id is null or not coalesce(e.aplicavel_subempreiteiro, false)
  ) then
    raise exception 'A seleÃ§Ã£o contÃ©m uma especialidade invÃ¡lida.';
  end if;

  if v_fornecedor_id is null then
    begin
      insert into public.fornecedores (
        empresa_id, nome, tipo_entidade, nif, email, telefone,
        representante, notas, estado_confianca
      ) values (
        v_empresa_id, btrim(p_nome), p_tipo_entidade,
        nullif(btrim(p_nif), ''), nullif(lower(btrim(p_email)), ''),
        nullif(btrim(p_telefone), ''), nullif(btrim(p_representante), ''),
        nullif(btrim(p_notas), ''), p_estado_confianca
      ) returning * into v_fornecedor;
      v_fornecedor_id := v_fornecedor.id;
    exception when unique_violation then
      raise exception 'JÃ¡ existe um cadastro com este nome ou NIF. Abra o registo existente para o rever ou completar.';
    end;
  else
    select * into v_fornecedor
    from public.fn_editar_fornecedor_diretorio_v2(
      v_fornecedor_id, p_nome, p_tipo_entidade, p_nif, p_email,
      p_telefone, p_representante, p_notas, p_estado_confianca
    );
  end if;

  perform public.fn_definir_zonas_fornecedor(
    v_fornecedor_id,
    coalesce(p_zonas, '{}'::text[])
  );

  delete from public.fornecedores_especialidades fe
  where fe.fornecedor_id = v_fornecedor_id
    and not (fe.especialidade_id = any(v_especialidades));

  foreach v_especialidade_id in array v_especialidades loop
    insert into public.fornecedores_especialidades (
      fornecedor_id, especialidade_id, origem, criado_por
    ) values (
      v_fornecedor_id, v_especialidade_id, 'manual', public.fn_utilizador_atual_id()
    ) on conflict (fornecedor_id, especialidade_id) do nothing;
  end loop;

  if nullif(btrim(p_nova_especialidade), '') is not null then
    perform public.fn_criar_especialidade_fornecedor(
      v_fornecedor_id,
      p_nova_especialidade
    );
  end if;

  select * into v_fornecedor
  from public.fornecedores f
  where f.id = v_fornecedor_id;

  return v_fornecedor;
end;
$function$

definitions.fn_atualizar_colaborador_ciclo_vida(uuid:
CREATE OR REPLACE FUNCTION public.fn_atualizar_colaborador_ciclo_vida(p_colaborador_id uuid, p_nome text, p_funcao text, p_data_admissao date, p_data_nascimento date, p_data_saida date, p_nivel text, p_valor_hora numeric, p_nif text, p_email text, p_contacto text, p_morada text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_colaborador public.colaboradores%rowtype;
begin
  if not (
    public.fn_e_admin()
    or public.fn_e_administrativo()
  ) then
    raise exception
      'A gestão de colaboradores está reservada ao Administrativo e à Gerência.';
  end if;

  if nullif(btrim(p_nome), '') is null
     or nullif(btrim(p_funcao), '') is null
     or p_data_admissao is null then
    raise exception
      'Nome, função e data de admissão são obrigatórios.';
  end if;

  if p_data_saida is not null
     and p_data_saida < p_data_admissao then
    raise exception
      'A data de saída não pode ser anterior à data de admissão.';
  end if;

  if p_valor_hora is not null and p_valor_hora < 0 then
    raise exception 'O valor/hora não pode ser negativo.';
  end if;

  perform 1 from public.colaboradores where id=p_colaborador_id for update;
  if not public.fn_medicina_pode_gerir(p_colaborador_id) then
    raise exception 'PERMISSION_DENIED: colaborador de outra empresa ou sem autorização.' using errcode='42501';
  end if;
  update public.colaboradores
  set
    nome = btrim(p_nome),
    funcao = btrim(p_funcao),
    nivel = nullif(btrim(p_nivel), ''),
    valor_hora = p_valor_hora,
    nif = nullif(btrim(p_nif), ''),
    email = nullif(btrim(p_email), ''),
    contacto = nullif(btrim(p_contacto), ''),
    morada = nullif(btrim(p_morada), ''),
    data_admissao = p_data_admissao,
    data_nascimento = p_data_nascimento,
    data_saida = p_data_saida
  where id = p_colaborador_id
  returning *
  into v_colaborador;

  if v_colaborador.id is null then
    raise exception 'Colaborador não encontrado.';
  end if;

  if p_data_saida is not null then
    delete from public.alertas a
    where a.estado = 'pendente'
      and (
        (
          a.entidade_tipo = 'epis'
          and a.entidade_id in (
            select e.id
            from public.epis e
            where e.colaborador_id = p_colaborador_id
          )
        )

      );
  elsif to_regprocedure(
    'public.fn_verificar_alertas_vencimento()'
  ) is not null then
    perform public.fn_verificar_alertas_vencimento();
  end if;

  perform public.fn_medicina_reconciliar_alertas(p_colaborador_id);
  return to_jsonb(v_colaborador);
end;
$function$

definitions.fn_quadro_criar_colaborador_interno(text:
CREATE OR REPLACE FUNCTION public.fn_quadro_criar_colaborador_interno(p_nome text, p_funcao text, p_data_admissao date, p_data_nascimento date, p_alocacao_tipo text, p_obra_id uuid, p_nivel text, p_valor_hora numeric, p_nif text, p_email text, p_contacto text, p_morada text, p_origem text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_empresa_id uuid;
  v_utilizador_id uuid := public.fn_utilizador_atual_id();
  v_colaborador public.colaboradores%rowtype;
  v_alocacao public.quadro_pessoal_alocacao%rowtype;
  v_semana_inicio date;
begin
  if p_origem not in ('cadastro_rh','importacao_rh') then raise exception 'VALIDATION_ERROR: origem RH inválida.'; end if;
  if public.fn_rh_empresa(false) is null then raise exception 'PERMISSION_DENIED: cadastro não autorizado.' using errcode='42501'; end if;
  if nullif(btrim(p_nome), '') is null
     or nullif(btrim(p_funcao), '') is null
     or p_data_admissao is null then
    raise exception
      'Nome, função e data de admissão são obrigatórios.';
  end if;

  if p_valor_hora is not null and p_valor_hora < 0 then
    raise exception 'O valor/hora não pode ser negativo.';
  end if;

  if p_alocacao_tipo is not null and p_alocacao_tipo not in ('obra', 'escritorio') then
    raise exception
      'A alocação inicial deve ser uma obra ativa ou o Escritório.';
  end if;

  select u.empresa_id
  into v_empresa_id
  from public.utilizadores u
  where u.id = v_utilizador_id;

  if v_empresa_id is null then
    raise exception
      'Não foi possível identificar a empresa do utilizador atual.';
  end if;

  if p_alocacao_tipo = 'obra' then
    if p_obra_id is null or not exists (
      select 1
      from public.obras o
      where o.id = p_obra_id
        and o.empresa_id = v_empresa_id
        and coalesce(lower(o.situacao), '') not in (
          'concluida',
          'concluído',
          'concluido',
          'cancelada'
        )
    ) then
      raise exception
        'Selecione uma obra ativa válida para a alocação inicial.';
    end if;
  elsif p_obra_id is not null then
    raise exception
      'A alocação de Escritório não pode ficar ligada a uma obra.';
  end if;

  insert into public.colaboradores (
    empresa_id,
    nome,
    funcao,
    nivel,
    valor_hora,
    nif,
    email,
    contacto,
    morada,
    data_admissao,
    data_nascimento,
    data_saida
  )
  values (
    v_empresa_id,
    btrim(p_nome),
    btrim(p_funcao),
    nullif(btrim(p_nivel), ''),
    p_valor_hora,
    nullif(btrim(p_nif), ''),
    nullif(btrim(p_email), ''),
    nullif(btrim(p_contacto), ''),
    nullif(btrim(p_morada), ''),
    p_data_admissao,
    p_data_nascimento,
    null
  )
  returning *
  into v_colaborador;

  v_semana_inicio :=
    p_data_admissao
    - (extract(isodow from p_data_admissao)::integer - 1);

  if p_alocacao_tipo is not null then
    perform public.fn_quadro_aplicar_interno(v_colaborador.id,p_data_admissao,'[]',
      jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'colaborador_id',v_colaborador.id,
       'data',p_data_admissao,'periodo','dia_inteiro','obra_id',p_obra_id,'tipo_alocacao',p_alocacao_tipo,
       'descricao_livre',case when p_alocacao_tipo='escritorio' then 'Escritório' else null end)),p_origem);
    select * into v_alocacao from public.quadro_pessoal_alocacao
      where colaborador_id=v_colaborador.id and data=p_data_admissao;
  end if;
  return jsonb_build_object(
    'colaborador', to_jsonb(v_colaborador),
    'alocacao', to_jsonb(v_alocacao)
  );
end;
$function$

definitions.fn_guardar_compromisso(uuid,text,date,ti:
CREATE OR REPLACE FUNCTION public.fn_guardar_compromisso(p_compromisso_id uuid, p_titulo text, p_data date, p_hora_inicio time without time zone, p_hora_fim time without time zone, p_dia_inteiro boolean, p_categoria text, p_obra_id uuid, p_responsavel_id uuid, p_local text, p_descricao text, p_prioridade text, p_lembrete_dias integer, p_participantes uuid[])
 RETURNS compromissos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_atual public.utilizadores;v_row public.compromissos;v_dest public.utilizadores;v_id uuid;v_expira timestamptz;
begin
  select * into v_atual from public.utilizadores where id=public.fn_utilizador_atual_id() and coalesce(ativo,true);
  if not found then raise exception 'Utilizador autenticado sem perfil ativo.';end if;
  if nullif(btrim(p_titulo),'') is null then raise exception 'Indique o tÃ­tulo do compromisso.';end if;
  if p_data is null then raise exception 'Indique a data do compromisso.';end if;
  if p_categoria not in ('reuniao','visita_obra','prazo','fornecedor','cliente','outro') then raise exception 'Categoria invÃ¡lida.';end if;
  if p_prioridade not in ('normal','alta') or p_lembrete_dias not in (0,1,7) then raise exception 'ConfiguraÃ§Ã£o do compromisso invÃ¡lida.';end if;
  if not p_dia_inteiro and (p_hora_inicio is null or p_hora_fim is null or p_hora_fim<=p_hora_inicio) then raise exception 'Indique um horÃ¡rio vÃ¡lido.';end if;
  if not exists(select 1 from public.utilizadores where id=p_responsavel_id and empresa_id=v_atual.empresa_id and coalesce(ativo,true)) then raise exception 'ResponsÃ¡vel invÃ¡lido ou inativo.';end if;
  if p_obra_id is not null and not exists(select 1 from public.obras where id=p_obra_id and empresa_id=v_atual.empresa_id) then raise exception 'A obra nÃ£o pertence Ã  empresa.';end if;
  if p_compromisso_id is null then
    insert into public.compromissos(empresa_id,titulo,data,hora_inicio,hora_fim,dia_inteiro,categoria,obra_id,responsavel_id,criado_por,local,descricao,prioridade,lembrete_dias)
    values(v_atual.empresa_id,btrim(p_titulo),p_data,case when p_dia_inteiro then null else p_hora_inicio end,case when p_dia_inteiro then null else p_hora_fim end,p_dia_inteiro,p_categoria,p_obra_id,p_responsavel_id,v_atual.id,nullif(btrim(p_local),''),nullif(btrim(p_descricao),''),p_prioridade,p_lembrete_dias) returning * into v_row;
  else
    select * into v_row from public.compromissos where id=p_compromisso_id for update;
    if not found or v_row.empresa_id<>v_atual.empresa_id then raise exception 'O compromisso jÃ¡ nÃ£o existe.';end if;
    if v_row.criado_por<>v_atual.id and v_row.responsavel_id<>v_atual.id and not public.fn_e_admin() then raise exception 'Sem permissÃ£o para editar este compromisso.' using errcode='42501';end if;
    update public.compromissos set titulo=btrim(p_titulo),data=p_data,hora_inicio=case when p_dia_inteiro then null else p_hora_inicio end,hora_fim=case when p_dia_inteiro then null else p_hora_fim end,dia_inteiro=p_dia_inteiro,categoria=p_categoria,obra_id=p_obra_id,responsavel_id=p_responsavel_id,local=nullif(btrim(p_local),''),descricao=nullif(btrim(p_descricao),''),prioridade=p_prioridade,lembrete_dias=p_lembrete_dias,atualizado_em=now() where id=p_compromisso_id returning * into v_row;
  end if;
  update public.alertas set estado='resolvido',expira_em=now() where tipo='compromisso_agenda' and entidade_tipo='compromissos' and entidade_id=v_row.id and estado='pendente';
  delete from public.compromissos_participantes where compromisso_id=v_row.id;
  insert into public.compromissos_participantes(compromisso_id,utilizador_id)
  select v_row.id,u.id from public.utilizadores u where u.id=any(coalesce(p_participantes,'{}'::uuid[])) and u.empresa_id=v_atual.empresa_id and coalesce(u.ativo,true) on conflict do nothing;
  v_expira:=(p_data+coalesce(case when p_dia_inteiro then time '23:59' else p_hora_fim end,time '23:59')) at time zone 'Europe/Lisbon';
  for v_id in select distinct id from (select p_responsavel_id id union select unnest(coalesce(p_participantes,'{}'::uuid[]))) d where id is not null and id<>v_atual.id loop
    select * into v_dest from public.utilizadores where id=v_id and empresa_id=v_atual.empresa_id and coalesce(ativo,true);
    if found then insert into public.alertas(empresa_id,obra_id,tipo,entidade_tipo,entidade_id,titulo,descricao,data_evento_referencia,antecedencia_dias,data_gatilho,destinatario_role,estado,enviar_email,destinatario_utilizador_id,expira_em)
      values(v_atual.empresa_id,p_obra_id,'compromisso_agenda','compromissos',v_row.id,'Compromisso: '||v_row.titulo,to_char(p_data,'DD/MM/YYYY')||case when p_dia_inteiro then ' Â· dia inteiro' else ' Â· '||to_char(p_hora_inicio,'HH24:MI')||'â€“'||to_char(p_hora_fim,'HH24:MI') end||' Â· Marcado por '||v_atual.nome||'.',p_data,p_lembrete_dias,p_data-p_lembrete_dias,v_dest.funcao,'pendente',false,v_dest.id,v_expira);end if;
  end loop;
  return v_row;
end;$function$

definitions.fn_guardar_ponto_obra(uuid,uuid,date,tex:
CREATE OR REPLACE FUNCTION public.fn_guardar_ponto_obra(p_obra_id uuid, p_colaborador_id uuid, p_data date, p_estado text, p_entrada_manha time without time zone DEFAULT NULL::time without time zone, p_saida_manha time without time zone DEFAULT NULL::time without time zone, p_entrada_tarde time without time zone DEFAULT NULL::time without time zone, p_saida_tarde time without time zone DEFAULT NULL::time without time zone, p_observacao text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_atual public.utilizadores;
  v_empresa_id uuid;
  v_pode_gerir boolean;
  v_periodos text[];
  v_horas numeric(5,2);
  v_registo public.ponto_pessoal_obra;
begin
  select * into v_atual from public.utilizadores
  where id = public.fn_utilizador_atual_id() and ativo is true;
  if v_atual.id is null then raise exception 'Utilizador sem perfil ativo.'; end if;
  v_empresa_id := v_atual.empresa_id;
  v_pode_gerir := public.fn_e_admin() or public.fn_e_administrativo();
  if not v_pode_gerir and not public.fn_e_encarregado_da_obra(p_obra_id) then
    raise exception 'Sem permissÃ£o para registar o ponto desta obra.' using errcode = '42501';
  end if;
  if p_estado not in ('presente','falta_com_justificacao','falta_sem_justificacao') then
    raise exception 'Estado de presenÃ§a invÃ¡lido.';
  end if;
  if p_estado = 'falta_com_justificacao' and nullif(btrim(p_observacao), '') is null then
    raise exception 'Indique a justificaÃ§Ã£o apresentada pelo colaborador.';
  end if;

  with eventos as (
    select q.*, slot.periodo_efetivo
    from public.quadro_pessoal_alocacao q
    cross join lateral unnest(case when q.periodo = 'dia_inteiro'
      then array['manha','tarde']::text[] else array[q.periodo]::text[] end) slot(periodo_efetivo)
    where q.colaborador_id = p_colaborador_id and q.data <= p_data
  ), efetivos as (
    select distinct on (periodo_efetivo) obra_id, tipo_alocacao, periodo_efetivo
    from eventos order by periodo_efetivo, data desc, criado_em desc, id desc
  )
  select array_agg(periodo_efetivo order by periodo_efetivo) into v_periodos
  from efetivos where obra_id = p_obra_id and tipo_alocacao = 'obra';

  if coalesce(cardinality(v_periodos), 0) = 0 then
    raise exception 'Este colaborador nÃ£o estÃ¡ alocado a esta obra na data indicada.';
  end if;
  if not exists (select 1 from public.colaboradores c where c.id = p_colaborador_id and c.empresa_id = v_empresa_id) then
    raise exception 'Colaborador inexistente ou fora da empresa.';
  end if;
  if p_estado = 'presente' and exists (
    select 1 from public.ausencias a
    where a.colaborador_id = p_colaborador_id and a.data = p_data
      and (a.tipo = 'ferias' or a.estado in ('confirmada','justificada'))
  ) then
    raise exception 'Este colaborador tem uma ausÃªncia ou fÃ©rias jÃ¡ confirmadas nesta data.';
  end if;

  if p_estado = 'presente' then
    if 'manha' = any(v_periodos) and (p_entrada_manha is null or p_saida_manha is null or p_saida_manha <= p_entrada_manha) then
      raise exception 'Preencha um horÃ¡rio vÃ¡lido para a manhÃ£.';
    end if;
    if 'tarde' = any(v_periodos) and (p_entrada_tarde is null or p_saida_tarde is null or p_saida_tarde <= p_entrada_tarde) then
      raise exception 'Preencha um horÃ¡rio vÃ¡lido para a tarde.';
    end if;
    if p_saida_manha is not null and p_entrada_tarde is not null and p_entrada_tarde < p_saida_manha then
      raise exception 'Os perÃ­odos da manhÃ£ e da tarde nÃ£o podem sobrepor-se.';
    end if;
    if not ('manha'=any(v_periodos)) then p_entrada_manha:=null; p_saida_manha:=null; end if;
    if not ('tarde'=any(v_periodos)) then p_entrada_tarde:=null; p_saida_tarde:=null; end if;
    v_horas := public.fn_ponto_horas(
      p_entrada_manha, p_saida_manha, p_entrada_tarde, p_saida_tarde
    );
    if v_horas <= 0 or v_horas > 16 then raise exception 'O total diÃ¡rio deve estar entre 0 e 16 horas.'; end if;
    if exists (
      select 1 from public.ponto_pessoal_obra outro
      where outro.colaborador_id=p_colaborador_id and outro.data=p_data
        and outro.obra_id<>p_obra_id and outro.estado='presente'
        and (
          (p_entrada_manha is not null and outro.entrada_manha is not null and p_entrada_manha < outro.saida_manha and outro.entrada_manha < p_saida_manha)
          or (p_entrada_manha is not null and outro.entrada_tarde is not null and p_entrada_manha < outro.saida_tarde and outro.entrada_tarde < p_saida_manha)
          or (p_entrada_tarde is not null and outro.entrada_manha is not null and p_entrada_tarde < outro.saida_manha and outro.entrada_manha < p_saida_tarde)
          or (p_entrada_tarde is not null and outro.entrada_tarde is not null and p_entrada_tarde < outro.saida_tarde and outro.entrada_tarde < p_saida_tarde)
        )
    ) then raise exception 'O horÃ¡rio sobrepÃµe-se ao ponto deste colaborador noutra obra.'; end if;
  else
    v_horas := 0;
    p_entrada_manha := null; p_saida_manha := null;
    p_entrada_tarde := null; p_saida_tarde := null;
  end if;

  insert into public.ponto_pessoal_obra(
    empresa_id, obra_id, colaborador_id, data, periodos_alocados, estado,
    entrada_manha, saida_manha, entrada_tarde, saida_tarde, horas,
    observacao, justificacao_estado, registado_por, atualizado_por, atualizado_em
  ) values (
    v_empresa_id, p_obra_id, p_colaborador_id, p_data, v_periodos, p_estado,
    p_entrada_manha, p_saida_manha, p_entrada_tarde, p_saida_tarde, v_horas,
    nullif(btrim(p_observacao), ''),
    case when p_estado='falta_com_justificacao' then 'pendente' else 'nao_aplicavel' end,
    v_atual.id, v_atual.id, now()
  ) on conflict (colaborador_id, obra_id, data) do update set
    periodos_alocados = excluded.periodos_alocados,
    estado = excluded.estado,
    entrada_manha = excluded.entrada_manha,
    saida_manha = excluded.saida_manha,
    entrada_tarde = excluded.entrada_tarde,
    saida_tarde = excluded.saida_tarde,
    horas = excluded.horas,
    observacao = excluded.observacao,
    justificacao_estado = excluded.justificacao_estado,
    atualizado_por = v_atual.id,
    atualizado_em = now()
  returning * into v_registo;

  return to_jsonb(v_registo);
end;
$function$
